window.IELTS_AUDIO_CUES={"audio/daniel-synced-160/c00af183d1131772.m4a":{"duration":70.48362811791384,"segments":[{"text":"I'd like to talk about a colleague of mine called Adam.","start":0.0,"end":3.0360090702947846},{"text":"We met at work about two years ago, and we gradually became friends.","start":3.0360090702947846,"end":7.545532879818594},{"text":"He's a few years older than me, and he's someone I often turn to when I need advice.","start":7.545532879818594,"end":12.925759637188209},{"text":"What stands out about him is how organised he is.","start":12.925759637188209,"end":15.821496598639456},{"text":"Before starting a task, he writes down the main steps and decides what needs to be done first.","start":15.821496598639456,"end":21.620045351473923},{"text":"He doesn't make things complicated.","start":21.620045351473923,"end":23.920997732426304},{"text":"In fact, he's usually the person who makes a confusing situation easier to understand.","start":23.920997732426304,"end":29.664761904761903},{"text":"A few months ago, I had to explain a new idea to our team.","start":29.664761904761903,"end":33.7108843537415},{"text":"I knew the details, but I couldn't present them clearly.","start":33.7108843537415,"end":37.23777777777778},{"text":"Adam suggested using one simple example instead of showing everything at once.","start":37.23777777777778,"end":42.1546485260771},{"text":"He also helped me practise and pointed out the parts that were difficult to follow.","start":42.1546485260771,"end":46.73378684807256},{"text":"The presentation went much better than I expected.","start":46.73378684807256,"end":49.729569160997734},{"text":"People understood the idea, and I felt more confident afterwards.","start":49.729569160997734,"end":53.96984126984127},{"text":"What I appreciate most is that he helped me learn a useful skill rather than just doing the work for me.","start":53.96984126984127,"end":60.0609977324263},{"text":"Since then, I've tried to follow his approach.","start":60.0609977324263,"end":63.18757369614512},{"text":"Whenever a task feels overwhelming, I break it into smaller steps.","start":63.18757369614512,"end":67.54612244897959},{"text":"So he's had a positive influence on the way I work.","start":67.54612244897959,"end":70.48362811791384}],"sha256":"9088672c3561c47dfb361bdbf8ceaa2440c9d47f300109a47c5dd200a0ce0f35"},"audio/daniel-synced-160/429b3f4b9218f598.m4a":{"duration":69.00585034013605,"segments":[{"text":"I'd like to talk about a novel called The Martian, by Andy Weir.","start":0.0,"end":3.9299773242630387},{"text":"I read it a few months ago after a friend recommended it.","start":3.9299773242630387,"end":7.292879818594105},{"text":"I usually prefer stories that feel practical, so the combination of science and adventure appealed to me.","start":7.292879818594105,"end":14.071836734693878},{"text":"The main character is an astronaut called Mark Watney, who is accidentally left behind on Mars.","start":14.071836734693878,"end":19.98385487528345},{"text":"He has to find ways to stay alive and contact people on Earth.","start":19.98385487528345,"end":23.770884353741497},{"text":"The situation sounds hopeless, but he doesn't give up.","start":23.770884353741497,"end":27.18675736961451},{"text":"He deals with one problem at a time, using whatever resources he has.","start":27.18675736961451,"end":31.81233560090703},{"text":"What I enjoyed most was the way he thought through his difficulties.","start":31.81233560090703,"end":35.5556462585034},{"text":"The book made me feel as if I was following his attempts step by step.","start":35.5556462585034,"end":39.67759637188209},{"text":"Some parts were tense, but his sense of humour made the story enjoyable as well.","start":39.67759637188209,"end":44.76888888888889},{"text":"I read a little in the evening, and I often continued longer than I had planned because I wanted to know what would happen next.","start":44.76888888888889,"end":51.87024943310658},{"text":"I felt relieved whenever one of his ideas worked.","start":51.87024943310658,"end":55.06108843537415},{"text":"The story also gave me a useful reminder: a big problem becomes less frightening when you focus on the next small action.","start":55.06108843537415,"end":62.3314739229025},{"text":"I think that's why it stayed with me.","start":62.3314739229025,"end":64.48639455782313},{"text":"I'd recommend it to someone who enjoys a hopeful story with a clever main character.","start":64.48639455782313,"end":69.00585034013605}],"sha256":"896f22da499b5360953aeeb130a683cce83be83cd52ac84e914e3249949c048e"},"audio/daniel-synced-160/5a02bf1371eb47f4.m4a":{"duration":69.43555555555555,"segments":[{"text":"I'd like to describe an afternoon I spent exploring an older part of Dubai with a friend.","start":0.0,"end":5.149024943310658},{"text":"We went there on a weekend because we wanted a break from our usual routine.","start":5.149024943310658,"end":9.310249433106575},{"text":"We weren't trying to visit every attraction.","start":9.310249433106575,"end":11.857732426303855},{"text":"We just wanted to walk around and see something different.","start":11.857732426303855,"end":15.336598639455783},{"text":"We started near the creek and spent some time looking at the old buildings and small shops.","start":15.336598639455783,"end":20.322131519274375},{"text":"What I liked was the atmosphere.","start":20.322131519274375,"end":22.347120181405895},{"text":"It felt different from the modern shopping malls I normally see.","start":22.347120181405895,"end":25.893968253968254},{"text":"There were narrow streets, people selling different products, and plenty of small details to notice.","start":25.893968253968254,"end":32.27342403628118},{"text":"At one point, we walked through a busy market.","start":32.27342403628118,"end":35.35591836734694},{"text":"It was quite crowded, and I could hear people talking and calling out to customers.","start":35.35591836734694,"end":40.20308390022676},{"text":"Later, we moved to a quieter spot by the water and took a few photos.","start":40.20308390022676,"end":44.794603174603175},{"text":"The light was softer by then, which made the area look especially nice.","start":44.794603174603175,"end":49.40925170068027},{"text":"We also had a simple drink and talked for a while.","start":49.40925170068027,"end":52.44430839002268},{"text":"The outing didn't cost us much, but I enjoyed it more than some expensive activities I've tried.","start":52.44430839002268,"end":58.46136054421769},{"text":"I remember feeling relaxed afterwards.","start":58.46136054421769,"end":61.0697052154195},{"text":"It reminded me that I don't always need a complicated plan to have a good day.","start":61.0697052154195,"end":65.61501133786848},{"text":"Sometimes a walk, a friend and a change of surroundings are enough.","start":65.61501133786848,"end":69.43555555555555}],"sha256":"6dbfc48979973ab08d1516eeb9e2cf64f3a4700d4665202d3ff390829728fa86"},"audio/daniel-synced-160/23b21937cd25ee34.m4a":{"duration":72.25156462585034,"segments":[{"text":"I'd like to describe a decision I made while working on a small project with my team.","start":0.0,"end":4.812335600907029},{"text":"We had a repetitive task that involved checking information manually, and I wanted to build a tool to make it easier.","start":4.812335600907029,"end":11.623265306122448},{"text":"At first, I thought we should create a complete system with lots of features.","start":11.623265306122448,"end":16.331156462585035},{"text":"However, a colleague suggested starting with a simple version.","start":16.331156462585035,"end":20.12643990929705},{"text":"I wasn't fully convinced because I worried it would look unfinished, but we discussed the idea and agreed to test it.","start":20.12643990929705,"end":26.905351473922902},{"text":"We divided the work between us and focused on the most common problem.","start":26.905351473922902,"end":30.811156462585036},{"text":"I worked on the main function, while another person tested it with a few examples.","start":30.811156462585036,"end":35.79954648526077},{"text":"Our first attempt didn't work properly because we had misunderstood part of the information.","start":35.79954648526077,"end":41.07628117913832},{"text":"We checked the issue together and corrected it.","start":41.07628117913832,"end":43.83532879818594},{"text":"Eventually, the tool handled the basic task well.","start":43.83532879818594,"end":47.208072562358275},{"text":"It wasn't perfect, but it saved us time and helped us understand what to improve next.","start":47.208072562358275,"end":52.57768707482993},{"text":"Seeing it work was a satisfying moment for me.","start":52.57768707482993,"end":55.799183673469386},{"text":"I was happy with the decision because we learned something useful without spending weeks on an idea that might not work.","start":55.799183673469386,"end":62.053061224489795},{"text":"The experience changed my opinion about planning.","start":62.053061224489795,"end":65.21151927437641},{"text":"I still think planning matters, but now I prefer to try a small, practical solution before making a bigger commitment.","start":65.21151927437641,"end":72.25156462585034}],"sha256":"09e6f72f980a7afe96f0277c62ec873673b692c1b63a643313f9c63272848a37"},"audio/daniel-synced-160/31bf46c69725e72d.m4a":{"duration":67.38458049886621,"segments":[{"text":"I'd like to talk about a small change I made to my evening routine.","start":0.0,"end":4.01124716553288},{"text":"I used to come home from work and immediately start looking at my phone.","start":4.01124716553288,"end":8.152108843537414},{"text":"I told myself I was taking a short break, but quite often I ended up scrolling for nearly an hour.","start":8.152108843537414,"end":14.269251700680272},{"text":"The problem was that I didn't feel rested afterwards.","start":14.269251700680272,"end":17.52045351473923},{"text":"I was still tired, and sometimes I went to bed later than I had planned.","start":17.52045351473923,"end":21.976145124716552},{"text":"So I decided to replace part of that screen time with a short walk.","start":21.976145124716552,"end":26.13795918367347},{"text":"I started with just ten minutes because I knew I wouldn't stick to an ambitious exercise plan.","start":26.13795918367347,"end":31.5784126984127},{"text":"When the weather was comfortable, I walked outside.","start":31.5784126984127,"end":34.77591836734694},{"text":"On other days, I found somewhere indoors where I could move around.","start":34.77591836734694,"end":38.972925170068024},{"text":"I usually left my phone in my pocket and paid attention to my surroundings.","start":38.972925170068024,"end":43.66208616780045},{"text":"After a while, a friend began joining me.","start":43.66208616780045,"end":46.71727891156463},{"text":"That made the habit easier to maintain because we could chat and remind each other to go.","start":46.71727891156463,"end":51.419591836734696},{"text":"We weren't trying to become athletes.","start":51.419591836734696,"end":53.59560090702948},{"text":"We just wanted to do something more active after sitting for most of the day.","start":53.59560090702948,"end":58.15419501133787},{"text":"The walk gives me a clear break between work and the rest of my evening.","start":58.15419501133787,"end":62.07859410430839},{"text":"The change is simple, but it helps me relax and makes me feel more in control of my time.","start":62.07859410430839,"end":67.38458049886621}],"sha256":"479f1b00ee527d4db6c403a2b9973421ea2e3ce577fede84d258d604aa21e908"},"audio/daniel-synced-160/f06e3e348f714cbf.m4a":{"duration":69.82421768707484,"segments":[{"text":"I'd like to talk about a pair of headphones that I saved up to buy.","start":0.0,"end":3.8951473922902493},{"text":"I wanted them because I often needed to concentrate in places where there was background noise.","start":3.8951473922902493,"end":9.255056689342403},{"text":"I also thought they would be useful for listening to English recordings.","start":9.255056689342403,"end":13.444172335600907},{"text":"They were more expensive than the basic headphones I had used before, so I didn't buy them immediately.","start":13.444172335600907,"end":19.425804988662133},{"text":"I compared a few options and put aside a little money each month.","start":19.425804988662133,"end":23.19514739229025},{"text":"I also cut back on a few small purchases that I didn't really need.","start":23.19514739229025,"end":27.616462585034014},{"text":"When I finally bought them, I was pleased because I had made a deliberate choice rather than buying something on impulse.","start":27.616462585034014,"end":34.35510204081633},{"text":"I started using them regularly for work and language practice.","start":34.35510204081633,"end":38.358548752834466},{"text":"A few weeks later, one side stopped working properly.","start":38.358548752834466,"end":41.91705215419501},{"text":"I took them back to the shop, expecting a long argument.","start":41.91705215419501,"end":45.43097505668934},{"text":"Instead, the assistant listened carefully, checked the problem and explained the next steps.","start":45.43097505668934,"end":51.00961451247166},{"text":"After confirming the fault, the shop arranged a replacement.","start":51.00961451247166,"end":54.99283446712018},{"text":"That experience made the purchase more memorable.","start":54.99283446712018,"end":57.87238095238095},{"text":"I appreciated both the product and the way the problem was handled.","start":57.87238095238095,"end":61.4902947845805},{"text":"For me, the value wasn't just the price or the brand.","start":61.4902947845805,"end":64.8984126984127},{"text":"It was having something useful and knowing that I could get help when it didn't work as expected.","start":64.8984126984127,"end":69.82421768707484}],"sha256":"b51ed1522bb2eee3eb625fd79e12843bcf407b07f66fc6854a876529a21fb09e"},"audio/daniel-synced-160/c3a8b306a2bcd931.m4a":{"duration":68.42467120181406,"segments":[{"text":"I'd like to talk about my grandmother and a skill she taught me when I was a child.","start":0.0,"end":4.847165532879819},{"text":"She enjoyed looking after plants, and whenever I visited her, I liked spending time in the small garden near her home.","start":4.847165532879819,"end":12.386757369614513},{"text":"When I was about ten, she helped me grow a plant of my own.","start":12.386757369614513,"end":16.339002267573697},{"text":"At first, I thought I only needed to put it in the soil and water it as much as possible.","start":16.339002267573697,"end":21.61578231292517},{"text":"She explained that plants needed the right amount of water and enough light, and that doing more wasn't always doing better.","start":21.61578231292517,"end":28.52843537414966},{"text":"We checked the plant together every few days.","start":28.52843537414966,"end":31.28485260770975},{"text":"I was impatient because I wanted to see a result immediately.","start":31.28485260770975,"end":34.926485260770974},{"text":"She encouraged me to notice small changes instead of expecting something dramatic overnight.","start":34.926485260770974,"end":40.4459410430839},{"text":"Eventually, I saw new leaves, and I felt surprisingly proud.","start":40.4459410430839,"end":44.80553287981859},{"text":"It was a small achievement, but it was something I had helped create and look after myself.","start":44.80553287981859,"end":50.36353741496599},{"text":"What I admire about my grandmother is her patience.","start":50.36353741496599,"end":53.607619047619046},{"text":"She didn't make me feel foolish when I made mistakes.","start":53.607619047619046,"end":56.94176870748299},{"text":"She explained things calmly and let me try again.","start":56.94176870748299,"end":60.11337868480726},{"text":"I still remember that experience because it taught me more than how to care for a plant.","start":60.11337868480726,"end":65.08943310657597},{"text":"It also taught me to be consistent and to give things time.","start":65.08943310657597,"end":68.42467120181406}],"sha256":"b7647280c15ba71735b46c1b8920eb763bc0e1970be14af5e1f14ef7bc517e42"},"audio/daniel-synced-160/3fab4a86ba272c39.m4a":{"duration":64.87356009070295,"segments":[{"text":"I'd like to describe a birthday dinner I helped organise for a friend.","start":0.0,"end":4.104126984126984},{"text":"It happened a few months ago, and there were just a few of us.","start":4.104126984126984,"end":7.732244897959184},{"text":"We wanted to make the evening special without turning it into a complicated or expensive event.","start":7.732244897959184,"end":13.277687074829933},{"text":"I checked when everyone was available and chose a place that was easy for us to reach.","start":13.277687074829933,"end":18.103492063492062},{"text":"Another friend arranged the cake, while I made the reservation and confirmed the time.","start":18.103492063492062,"end":22.857823129251702},{"text":"We also asked him what food he liked so that he would enjoy the meal.","start":22.857823129251702,"end":26.893968253968254},{"text":"On the evening itself, we arrived a little early and made sure everything was ready.","start":26.893968253968254,"end":31.7643537414966},{"text":"The atmosphere was relaxed.","start":31.7643537414966,"end":33.68054421768707},{"text":"We talked about work, shared some funny stories and took a few photos together.","start":33.68054421768707,"end":38.842902494331064},{"text":"The most memorable moment was when the cake came out.","start":38.842902494331064,"end":41.85006802721088},{"text":"It was quite simple, but it had a small decoration connected to one of his hobbies.","start":41.85006802721088,"end":46.720453514739226},{"text":"He hadn't expected it, and his reaction made the effort feel worthwhile.","start":46.720453514739226,"end":51.46213151927438},{"text":"I was pleased that the plan worked and that everyone had a good time.","start":51.46213151927438,"end":55.20825396825397},{"text":"It reminded me that a successful celebration doesn't depend on spending a lot of money.","start":55.20825396825397,"end":60.229569160997734},{"text":"Paying attention to the person and making time for each other can be much more important.","start":60.229569160997734,"end":64.87356009070295}],"sha256":"0f8b956b17b9786f1fbf4f675105a5b24d957993e256b2cf17fea6317ee4d7ea"},"audio/daniel-synced-160/8392c3b8e44b8b71.m4a":{"duration":73.48553287981859,"segments":[{"text":"I'd like to talk about my childhood friend Ben.","start":0.0,"end":2.9895691609977324},{"text":"We grew up in the same neighbourhood and became friends when we were about ten.","start":2.9895691609977324,"end":6.9766439909297056},{"text":"We used to ride our bikes after school, and although we now live in different cities, we still talk regularly.","start":6.9766439909297056,"end":13.601814058956917},{"text":"One thing I admire about him is the way he learns languages.","start":13.601814058956917,"end":17.32185941043084},{"text":"He studies English by watching short videos with subtitles, noting useful expressions and recording himself using them.","start":17.32185941043084,"end":24.70798185941043},{"text":"He also learns Chinese, and we practise together through voice messages.","start":24.70798185941043,"end":29.249659863945578},{"text":"Rather than memorising long lists, he uses new words in simple conversations.","start":29.249659863945578,"end":34.58403628117914},{"text":"Recently, he managed to order a meal in Chinese and ask the waiter about the ingredients without switching to English.","start":34.58403628117914,"end":41.44190476190476},{"text":"Ben is also interested in history.","start":41.44190476190476,"end":43.60634920634921},{"text":"He once found a box of his grandfather's old photographs and asked him about the people and places in them.","start":43.60634920634921,"end":49.483174603174604},{"text":"He put the pictures in an album with short descriptions.","start":49.483174603174604,"end":52.6897052154195},{"text":"When we visited a local museum, he explained how an old railway had changed the town.","start":52.6897052154195,"end":58.327891156462584},{"text":"What makes our friendship special is that he never makes me feel embarrassed when I get something wrong.","start":58.327891156462584,"end":63.92879818594104},{"text":"He corrects me gently and usually adds a funny example.","start":63.92879818594104,"end":67.29786848072563},{"text":"He's curious, patient and easy to talk to, so spending time with him always feels worthwhile.","start":67.29786848072563,"end":73.48553287981859}],"sha256":"3cef340856b5b1a24fe0949b70274e3ee165e1559e97ac523ca483bdd27a599d"},"audio/daniel-synced-160/ac913d1a1e925fba.m4a":{"duration":77.23206349206349,"segments":[{"text":"I'd like to talk about my cousin Sara, who wants to become a nurse.","start":0.0,"end":4.4175963718820865},{"text":"She's a few years younger than me, and we've known each other since childhood.","start":4.4175963718820865,"end":8.703764172335601},{"text":"We usually meet at family gatherings, but recently we've also been talking about her future career.","start":8.703764172335601,"end":14.806530612244899},{"text":"Her interest in nursing began when our grandmother spent several days in hospital.","start":14.806530612244899,"end":19.354829931972787},{"text":"Sara noticed that the nurses did much more than check equipment.","start":19.354829931972787,"end":23.08512471655329},{"text":"They explained what was happening and helped our grandmother feel less anxious.","start":23.08512471655329,"end":27.555283446712018},{"text":"She said she wanted a job where her work could make a practical difference to someone's day.","start":27.555283446712018,"end":32.72643990929705},{"text":"To explore the idea, she volunteered at a community health event last summer.","start":32.72643990929705,"end":37.4449433106576},{"text":"Her role was simple: welcoming visitors, showing them where to queue and helping them complete basic forms.","start":37.4449433106576,"end":43.8740589569161},{"text":"She didn't provide medical treatment.","start":43.8740589569161,"end":46.08204081632653},{"text":"One older visitor was confused about the registration process, and Sara patiently explained each step.","start":46.08204081632653,"end":52.611655328798186},{"text":"Afterwards, she told me that she had enjoyed helping him feel comfortable.","start":52.611655328798186,"end":57.58512471655329},{"text":"Her plan is to apply for a nursing course, improve her science knowledge and keep volunteering when she can.","start":57.58512471655329,"end":63.95519274376417},{"text":"She knows the work can involve long shifts and difficult situations, so she doesn't see it as an easy career.","start":63.95519274376417,"end":70.37759637188209},{"text":"I admire her because her ambition is based on real interest and some first-hand experience, rather than just the title.","start":70.37759637188209,"end":77.23206349206349}],"sha256":"ddbefa79110ba8872856057ca79414ed4ef92fdf57279f40d13491516c963e6a"},"audio/daniel-synced-160/36029c1f6798722c.m4a":{"duration":79.69328798185941,"segments":[{"text":"I'd like to talk about Lei Jun, the co-founder of Xiaomi.","start":0.0,"end":4.01124716553288},{"text":"He's a well-known Chinese entrepreneur, but I feel a particular connection with him.","start":4.01124716553288,"end":9.01732426303855},{"text":"We come from the same part of China, and we both studied at Wuhan University.","start":9.01732426303855,"end":13.782267573696146},{"text":"That gives me a personal reason to pay attention to him, beyond simply recognising his name.","start":13.782267573696146,"end":19.65981859410431},{"text":"He co-founded Xiaomi in 2010, and the company became known for its smartphones and other technology products.","start":19.65981859410431,"end":26.94145124716553},{"text":"What interests me is the journey from having an idea to building something that ordinary people actually use.","start":26.94145124716553,"end":32.67006802721088},{"text":"I think that requires more than technical knowledge; it also takes teamwork and an understanding of customers.","start":32.67006802721088,"end":39.18136054421769},{"text":"His career wasn't a straight line.","start":39.18136054421769,"end":41.331383219954645},{"text":"In an account of his university years, he described an early business that eventually closed.","start":41.331383219954645,"end":46.84031746031746},{"text":"He realised that technical ability alone wasn't enough to run a company.","start":46.84031746031746,"end":51.04530612244898},{"text":"I find that experience encouraging because it shows that a disappointing start doesn't have to decide the rest of your career.","start":51.04530612244898,"end":58.11387755102041},{"text":"What interests me most is how he built his wealth.","start":58.11387755102041,"end":60.98639455782313},{"text":"As someone from my home region and a fellow university alumnus, he feels quite relatable to me.","start":60.98639455782313,"end":66.94816326530612},{"text":"If I could meet him, I'd ask how he made his first significant amount of money and which decision contributed most to his financial success.","start":66.94816326530612,"end":75.40603174603174},{"text":"I'd also like to know what he would do if he had to start again with very little money.","start":75.40603174603174,"end":79.69328798185941}],"sha256":"39e322582322b60db5cd168d710f2f6090d0c04dc0ac3b4fee70729daf22f6f6"},"audio/daniel-synced-160/0d51a56c67d10354.m4a":{"duration":79.43904761904761,"segments":[{"text":"I'd like to talk about my friend Alex, who runs a small coffee shop near a residential area.","start":0.0,"end":5.950113378684807},{"text":"I met him through a mutual friend a few years ago.","start":5.950113378684807,"end":8.896598639455782},{"text":"Since then, I've visited his shop fairly often, usually on a Saturday morning.","start":8.896598639455782,"end":14.0459410430839},{"text":"When he first opened it, the business was difficult.","start":14.0459410430839,"end":17.162267573696145},{"text":"There weren't many customers in the morning, and some food was left unsold at the end of each day.","start":17.162267573696145,"end":22.574920634920634},{"text":"Instead of immediately spending more money on advertising, he asked regular customers what they wanted and checked which items actually sold.","start":22.574920634920634,"end":30.81482993197279},{"text":"He reduced the menu to a few reliable choices, prepared smaller batches and introduced a simple breakfast combination.","start":30.81482993197279,"end":38.02680272108844},{"text":"He also created a quiet corner where customers could read or work.","start":38.02680272108844,"end":42.10408163265306},{"text":"Gradually, people started coming back.","start":42.10408163265306,"end":44.95369614512472},{"text":"What I like most is the service: he remembers regular customers' orders and deals with problems politely.","start":44.95369614512472,"end":51.16988662131519},{"text":"Once, my coffee arrived cold, and he replaced it without making the situation awkward.","start":51.16988662131519,"end":56.91269841269841},{"text":"I think the shop succeeds because he understands his customers and pays attention to everyday details.","start":56.91269841269841,"end":62.8524716553288},{"text":"He keeps a clear stock list and gives his team sensible tasks, but he's also friendly and enjoys chatting with people.","start":62.8524716553288,"end":69.79741496598639},{"text":"I'm pleased to see his hard work paying off.","start":69.79741496598639,"end":72.42707482993197},{"text":"His experience reminds me that running a good business often depends on steady improvements, rather than one dramatic idea.","start":72.42707482993197,"end":79.43904761904761}],"sha256":"a6296a5679bdb79e701c33bd817d2e710858ce0eae55b5551fd85c1ea045fb37"},"audio/daniel-synced-160/d53cb311ba010164.m4a":{"duration":70.68993197278911,"segments":[{"text":"I'd like to talk about Roger Federer, the retired Swiss tennis player.","start":0.0,"end":4.255056689342403},{"text":"I first became interested in him when I watched some of his matches on television as a student.","start":4.255056689342403,"end":9.416961451247165},{"text":"I didn't understand every rule, but I could tell that his movement and timing were special.","start":9.416961451247165,"end":14.653151927437642},{"text":"He finished his career with twenty Grand Slam singles titles, including eight Wimbledon titles.","start":14.653151927437642,"end":20.646077097505668},{"text":"What I admire most, though, is the way he makes a difficult sport look natural.","start":20.646077097505668,"end":25.712879818594104},{"text":"His movements seem smooth, and watching him has made me appreciate the importance of technique.","start":25.712879818594104,"end":31.20920634920635},{"text":"One part of his career that really impressed me was his return after injury.","start":31.20920634920635,"end":35.45170068027211},{"text":"He missed the second half of the 2016 season because of a knee problem.","start":35.45170068027211,"end":40.20235827664399},{"text":"Then, in 2017, he came back and won both the Australian Open and Wimbledon.","start":40.20235827664399,"end":46.044716553287984},{"text":"To me, that is a powerful example of recovering from a setback.","start":46.044716553287984,"end":50.30108843537415},{"text":"I also like the fact that I can learn something from his story without becoming a professional athlete.","start":50.30108843537415,"end":55.98526077097506},{"text":"When I'm struggling with a new skill, I sometimes expect results too quickly.","start":55.98526077097506,"end":60.726938775510206},{"text":"Thinking about his comeback reminds me to be patient, work on the basics and give myself time.","start":60.726938775510206,"end":66.52430839002268},{"text":"That's why I admire him as both a sportsman and an example of persistence.","start":66.52430839002268,"end":70.68993197278911}],"sha256":"ab01a5f6606f63eb7d4f2bfeaaf92cfb3c39f102e39fcc5b73a93fc0970351ae"},"audio/daniel-synced-160/12f8d0647be493dd.m4a":{"duration":66.12353741496598,"segments":[{"text":"An animal story I remember clearly is The Tortoise and the Hare.","start":0.0,"end":3.500453514739229},{"text":"It's a short fable associated with Aesop, and I first heard it from my father when I was in primary school.","start":3.500453514739229,"end":9.880136054421769},{"text":"Later, I read an illustrated version myself, which made me feel quite proud.","start":9.880136054421769,"end":15.33342403628118},{"text":"The story is about a race between two very different animals.","start":15.33342403628118,"end":19.02562358276644},{"text":"The hare is fast and confident, while the tortoise moves slowly.","start":19.02562358276644,"end":22.810566893424035},{"text":"Because the hare thinks winning will be easy, he stops for a nap.","start":22.810566893424035,"end":26.53092970521542},{"text":"The tortoise keeps going and reaches the finish before him.","start":26.53092970521542,"end":29.993514739229024},{"text":"As a child, I found the ending funny and surprising.","start":29.993514739229024,"end":33.493968253968255},{"text":"At the beginning, I was certain that the hare would win, so I wanted to turn the pages quickly.","start":33.493968253968255,"end":39.10743764172336},{"text":"I also liked the pictures because they helped me understand what was happening without needing an adult to explain every sentence.","start":39.10743764172336,"end":46.34997732426304},{"text":"The lesson has stayed with me: steady effort matters, and being good at something doesn't mean you can stop trying.","start":46.34997732426304,"end":53.086666666666666},{"text":"I think of it when I'm learning a skill and comparing myself with people who improve faster.","start":53.086666666666666,"end":58.202131519274374},{"text":"The story reminds me to focus on my own progress.","start":58.202131519274374,"end":61.52281179138322},{"text":"It's simple, but that's probably why I still remember it after so many years.","start":61.52281179138322,"end":66.12353741496598}],"sha256":"3712ba4746c7f3f0bad3e481296d34d1bc9e7ec8edf341cbfe128028a730ad41"},"audio/daniel-synced-160/8bdf5133802dd9e6.m4a":{"duration":79.93519274376418,"segments":[{"text":"An existing rule I think is useful is Shanghai's household waste sorting rule.","start":0.0,"end":4.53374149659864},{"text":"Shanghai is a city in China, and sorting household rubbish has been legally required there since the first of July, 2019.","start":4.53374149659864,"end":12.789750566893424},{"text":"I'm talking about a local rule in Shanghai, rather than one identical rule for the whole country.","start":12.789750566893424,"end":18.777324263038548},{"text":"The system separates household waste into four categories: recyclables, hazardous waste, wet waste and dry waste.","start":18.777324263038548,"end":26.512108843537415},{"text":"For example, food leftovers belong with wet waste, while materials that can be recycled should go into the appropriate recycling bin.","start":26.512108843537415,"end":34.84285714285714},{"text":"Hazardous items need to be handled separately.","start":34.84285714285714,"end":37.82544217687075},{"text":"I became more aware of this rule during a visit to relatives in Shanghai.","start":37.82544217687075,"end":42.10562358276644},{"text":"In their kitchen, they kept separate containers and checked the labels before throwing things away.","start":42.10562358276644,"end":47.64938775510204},{"text":"At first, I found it a little confusing, especially when an item contained different materials.","start":47.64938775510204,"end":53.924625850340135},{"text":"After a few days, though, the basic routine felt much easier.","start":53.924625850340135,"end":58.42208616780045},{"text":"I support the idea because it encourages people to think about what happens after they throw something away.","start":58.42208616780045,"end":64.47709750566894},{"text":"However, I think clear signs and convenient collection points are essential.","start":64.47709750566894,"end":69.11990929705216},{"text":"People are more likely to follow a rule when they understand it and can fit it into their daily routine.","start":69.11990929705216,"end":74.56761904761905},{"text":"For me, good environmental rules need practical support as well as expectations.","start":74.56761904761905,"end":79.93519274376418}],"sha256":"f8e6ddfcb23dcab0523afef064e28575658ea79426759a3169c96ed5ec51a216"},"audio/daniel-synced-160/f3235dd5a0184aa2.m4a":{"duration":78.22009070294784,"segments":[{"text":"A piece of local news I found encouraging was about improvements to Dubai's bus network.","start":0.0,"end":5.323219954648526},{"text":"I read an RTA announcement in September 2026 after a friend shared the link.","start":5.323219954648526,"end":11.6118820861678},{"text":"The announcement itself was published on the sixth of January, so I was discovering an earlier development rather than reading about something launched that week.","start":11.6118820861678,"end":20.682448979591836},{"text":"According to the announcement, four new public bus routes were scheduled to start operating on the ninth of January.","start":20.682448979591836,"end":27.247936507936508},{"text":"RTA also announced improvements to more than seventy existing internal routes, including changes to route coverage and services during busy periods.","start":27.247936507936508,"end":36.59224489795918},{"text":"The aim was to make everyday travel more convenient.","start":36.59224489795918,"end":39.71850340136054},{"text":"This caught my attention because I live in Dubai and sometimes use public transport.","start":39.71850340136054,"end":44.71120181405896},{"text":"I don't use every route mentioned, so I can't say that the changes directly shortened my own commute.","start":44.71120181405896,"end":50.92},{"text":"Still, better connections could make buses a more practical option for people travelling between neighbourhoods.","start":50.92,"end":57.418185941043085},{"text":"After reading the article, I checked whether any of the routes were relevant to places I visit.","start":57.418185941043085,"end":62.81519274376417},{"text":"I also sent the link back to my friend with a short comment saying that this was the kind of local news I liked: a practical improvement that could affect ordinary daily life.","start":62.81519274376417,"end":72.74861678004535},{"text":"It made me feel positive about the city, and I would like to see the network continue to improve.","start":72.74861678004535,"end":78.22009070294784}],"sha256":"c19d99931b9e1740d9cfdddf5b267341f341a2dc8a8bfd90dc9898b9db0daff5"},"audio/daniel-synced-160/d8d63a948d40e627.m4a":{"duration":67.30585034013606,"segments":[{"text":"I'd like to describe West Lake in Hangzhou, a city in Zhejiang Province in eastern China.","start":0.0,"end":5.520544217687075},{"text":"I visited it with a friend during a short holiday last year.","start":5.520544217687075,"end":9.022539682539682},{"text":"We had a busy few weeks before the trip, so we wanted somewhere we could explore without rushing.","start":9.022539682539682,"end":14.591201814058957},{"text":"We spent an afternoon walking along the paths beside the lake.","start":14.591201814058957,"end":17.997777777777777},{"text":"What I remember most is the space around the water.","start":17.997777777777777,"end":20.82390022675737},{"text":"There were trees beside the path, and we could stop whenever we noticed a view we liked.","start":20.82390022675737,"end":25.528798185941042},{"text":"I took a few photos, but I also put my phone away for part of the walk.","start":25.528798185941042,"end":30.63591836734694},{"text":"At one point, we sat down and watched the light change on the water.","start":30.63591836734694,"end":34.6936507936508},{"text":"We talked about ordinary things and didn't feel that we had to keep moving to another attraction.","start":34.6936507936508,"end":39.83011337868481},{"text":"Afterwards, we found somewhere nearby to have a simple meal.","start":39.83011337868481,"end":43.839954648526074},{"text":"For me, the lake is important because it gives people a place to enjoy being outdoors while visiting a city.","start":43.839954648526074,"end":49.97641723356009},{"text":"I liked the balance between walking, looking around and having time to talk.","start":49.97641723356009,"end":54.87451247165533},{"text":"I'd happily go back, especially with someone who enjoys a slower kind of holiday.","start":54.87451247165533,"end":59.93065759637188},{"text":"Next time, I'd leave more time to explore Hangzhou beyond the lake, rather than trying to fit everything into one afternoon.","start":59.93065759637188,"end":67.30585034013606}],"sha256":"4549fef8d0306e9f5773fb2adaf531ed45a6171cbeebf0b8e439ed451fbe94b5"},"audio/daniel-synced-160/fc14dbbc83758bef.m4a":{"duration":67.74816326530612,"segments":[{"text":"A natural place I enjoy visiting is Sunset Beach in Dubai.","start":0.0,"end":3.6978231292517005},{"text":"I went there with a friend one evening a few months ago, after a week when we had both spent too much time indoors.","start":3.6978231292517005,"end":10.27673469387755},{"text":"We wanted a short break without planning a whole day out.","start":10.27673469387755,"end":13.627891156462585},{"text":"We walked along the sand and then found a place to sit away from the busier part of the beach.","start":13.627891156462585,"end":18.590204081632653},{"text":"It wasn't completely silent, but I could hear the waves more clearly than the conversations around us.","start":18.590204081632653,"end":24.470657596371883},{"text":"There was a light breeze, which made sitting outside comfortable.","start":24.470657596371883,"end":28.470068027210885},{"text":"The most memorable part was the sky.","start":28.470068027210885,"end":30.745804988662133},{"text":"At first, it was quite bright, but later the colours became softer.","start":30.745804988662133,"end":35.23310657596372},{"text":"I noticed shades of orange near the horizon, with a little pink above them.","start":35.23310657596372,"end":39.38557823129252},{"text":"We took a photograph, although it didn't quite capture what we could see.","start":39.38557823129252,"end":44.071927437641726},{"text":"For a while, we stopped talking and simply watched the water.","start":44.071927437641726,"end":47.81673469387755},{"text":"I normally feel that I should be checking a message or finishing something, so it was pleasant to have no particular task.","start":47.81673469387755,"end":54.95560090702948},{"text":"I left feeling calmer.","start":54.95560090702948,"end":56.48421768707483},{"text":"What I liked wasn't an expensive activity or a special event.","start":56.48421768707483,"end":60.35523809523809},{"text":"It was the chance to slow down and pay attention to something outside my usual routine.","start":60.35523809523809,"end":65.35333333333334},{"text":"I'd go back when I needed a similar break.","start":65.35333333333334,"end":67.74816326530612}],"sha256":"36827f830d3d0cb1b03dae6f80b7cc9085281df35d8ddcadbd20d146b8502dec"},"audio/daniel-synced-160/b6d6dc5e464ea6ee.m4a":{"duration":70.83600907029478,"segments":[{"text":"A public building I'd like to describe is Mohammed Bin Rashid Library in Dubai.","start":0.0,"end":4.765941043083901},{"text":"It stands beside Dubai Creek, and its design is inspired by a traditional book rest.","start":4.765941043083901,"end":10.089115646258504},{"text":"The library has seven levels, but what first caught my attention was its unusual shape rather than its height.","start":10.089115646258504,"end":16.642312925170067},{"text":"I visited it one afternoon after a friend suggested going somewhere different from our usual cafés.","start":16.642312925170067,"end":22.53845804988662},{"text":"Before that visit, I had seen photographs of the building, but I wanted to understand what it was like to spend time there.","start":22.53845804988662,"end":29.964943310657596},{"text":"We looked around and then found somewhere to sit and read.","start":29.964943310657596,"end":33.0},{"text":"I chose a book in English and spent some time working through a few pages.","start":33.0,"end":37.18725623582766},{"text":"I didn't understand every word, but the setting helped me stay focused instead of moving between different things on my phone.","start":37.18725623582766,"end":44.687392290249434},{"text":"What I appreciated most was that the visit had a clear purpose without feeling rushed.","start":44.687392290249434,"end":49.4059410430839},{"text":"I could read, notice the building and take a short break from work.","start":49.4059410430839,"end":53.40884353741497},{"text":"It felt different from being in a shopping centre, where I often end up looking at things I don't need.","start":53.40884353741497,"end":59.43124716553288},{"text":"I'd recommend it to someone interested in books or architecture.","start":59.43124716553288,"end":63.036145124716555},{"text":"For me, a useful public building offers more than an interesting photograph.","start":63.036145124716555,"end":67.82585034013606},{"text":"It gives people somewhere to learn and spend their time well.","start":67.82585034013606,"end":70.83600907029478}],"sha256":"c5c5d2e7d9bb090a837b53cd2b6f4d65a92d22d6d52d1b2fe85f10d0cfc67010"},"audio/daniel-synced-160/ca45729b9079bf2a.m4a":{"duration":69.85120181405895,"segments":[{"text":"A home I enjoy visiting is my grandmother's house.","start":0.0,"end":3.140544217687075},{"text":"I used to go there quite often when I was younger, and I still associate it with spending unhurried time with my family.","start":3.140544217687075,"end":9.812380952380952},{"text":"It isn't a large or modern place, but it feels familiar to me.","start":9.812380952380952,"end":13.86108843537415},{"text":"The room I remember best is the living room.","start":13.86108843537415,"end":16.473560090702946},{"text":"There is a comfortable sofa, a small table and some family photographs.","start":16.473560090702946,"end":21.306077097505668},{"text":"My grandmother also looks after a few plants near the house.","start":21.306077097505668,"end":25.096190476190475},{"text":"When I visit, we usually have something to drink and talk about what has happened since we last saw each other.","start":25.096190476190475,"end":31.454331065759636},{"text":"On my last visit, I helped her with a small job and then stayed for lunch.","start":31.454331065759636,"end":36.09251700680272},{"text":"Nothing especially exciting happened, but I enjoyed having time for an ordinary conversation.","start":36.09251700680272,"end":41.87986394557823},{"text":"I didn't feel that I had to keep checking the time.","start":41.87986394557823,"end":45.154013605442174},{"text":"Although I like visiting, I wouldn't choose to live there permanently.","start":45.154013605442174,"end":49.06077097505669},{"text":"It is too far from the places I need to reach for work, and I'd prefer having my own space and routine.","start":49.06077097505669,"end":55.37079365079365},{"text":"As an adult, I moved into an apartment closer to work, which suited my daily life better.","start":55.37079365079365,"end":61.41646258503401},{"text":"So the house is special because of the person and memories connected with it.","start":61.41646258503401,"end":65.54072562358277},{"text":"Enjoying a visit doesn't necessarily mean that it would be the right place for me to live.","start":65.54072562358277,"end":69.85120181405895}],"sha256":"2317f7354beee30ebd4dae4017c4db063116d1e60ca2e6d2b4eb626ad271fb46"},"audio/daniel-synced-160/9674c4841afbdbc3.m4a":{"duration":71.12367346938775,"segments":[{"text":"A long-term goal I'd like to achieve is being able to use English comfortably in work and study.","start":0.0,"end":5.2883900226757365},{"text":"I understand a lot when I read, but I sometimes hesitate when explaining my own ideas.","start":5.2883900226757365,"end":11.019319727891157},{"text":"I want that gap to shrink.","start":11.019319727891157,"end":13.0962358276644},{"text":"This matters because good ideas are less useful if I can't communicate them clearly.","start":13.0962358276644,"end":17.82190476190476},{"text":"I'd like to take part in discussions, ask questions when something is unclear and explain a problem without worrying much about finding the perfect words.","start":17.82190476190476,"end":27.025442176870747},{"text":"I've started with a simple routine.","start":27.025442176870747,"end":29.155873015873016},{"text":"I choose a short question, record an answer and listen back.","start":29.155873015873016,"end":32.98326530612245},{"text":"If a sentence is difficult to say, I try again with simpler language.","start":32.98326530612245,"end":37.52857142857143},{"text":"I also read or listen to something useful and explain the main point in my own words.","start":37.52857142857143,"end":42.832244897959185},{"text":"Some days feel easier than others.","start":42.832244897959185,"end":45.006802721088434},{"text":"I don't expect every recording to be better than the previous one, but I can notice small changes, such as pausing less or giving a clearer example.","start":45.006802721088434,"end":54.01360544217687},{"text":"That helps me continue when progress feels slow.","start":54.01360544217687,"end":57.244081632653064},{"text":"I would consider the goal achieved when I can express what I mean and follow a conversation more confidently.","start":57.244081632653064,"end":63.35863945578231},{"text":"It isn't about using impressive words all the time.","start":63.35863945578231,"end":66.45269841269841},{"text":"For me, it is about being able to communicate naturally and take part more fully.","start":66.45269841269841,"end":71.12367346938775}],"sha256":"bb6450496c58a7c29c9c46b9562ce72ea491b5100a67066e338b23231fdba5d0"},"audio/daniel-synced-160/e23efed32999cb3a.m4a":{"duration":66.51873015873016,"segments":[{"text":"A song that has special meaning for me is Happy Birthday to You.","start":0.0,"end":3.6978231292517005},{"text":"It is a familiar song, but I associate it with being remembered and spending time with people I care about.","start":3.6978231292517005,"end":9.81047619047619},{"text":"The meaning comes from the occasions rather than a recording.","start":9.81047619047619,"end":13.226666666666667},{"text":"One evening that stands out was a birthday dinner we arranged for a friend.","start":13.226666666666667,"end":17.32984126984127},{"text":"We had kept the plan simple and met at a place that was convenient for everyone.","start":17.32984126984127,"end":21.9902947845805},{"text":"Towards the end of the meal, someone brought out a cake and we sang.","start":21.9902947845805,"end":26.08503401360544},{"text":"None of us was a particularly good singer, and we didn't all start at the same moment.","start":26.08503401360544,"end":30.92036281179138},{"text":"However, that made the experience feel relaxed rather than embarrassing.","start":30.92036281179138,"end":35.40063492063492},{"text":"Our friend looked surprised and then started smiling, which made me enjoy the song even more.","start":35.40063492063492,"end":41.156009070294786},{"text":"What I like about the tune is that it is easy to recognise and join in with.","start":41.156009070294786,"end":45.10829931972789},{"text":"I don't need to concentrate on a complicated performance.","start":45.10829931972789,"end":48.67002267573696},{"text":"I can simply take part and pay attention to the people around me.","start":48.67002267573696,"end":52.82512471655329},{"text":"I wouldn't put the song on when I'm working or travelling.","start":52.82512471655329,"end":55.9675283446712},{"text":"Still, hearing it at a celebration brings back warm memories.","start":55.9675283446712,"end":60.02498866213152},{"text":"For me, it shows how even a simple piece of music can become meaningful through the experiences connected with it.","start":60.02498866213152,"end":66.51873015873016}],"sha256":"43bb9ee94e791c78a8f438771892e687eef3177a2d1cf697072eb16af749a5ec"},"audio/daniel-synced-160/1ae689715ef0e538.m4a":{"duration":63.368979591836734,"segments":[{"text":"A piece of art I like is a watercolour painting of Dubai Creek that a friend gave me.","start":0.0,"end":4.719501133786848},{"text":"He enjoys painting in his free time, and he made it after we spent an afternoon walking around the area.","start":4.719501133786848,"end":10.970476190476191},{"text":"The picture shows a boat on the water, with a row of buildings behind it.","start":10.970476190476191,"end":14.91814058956916},{"text":"The walls are painted in warm, pale colours, while the water has different shades of blue.","start":14.91814058956916,"end":20.435736961451248},{"text":"There are a few soft reflections, which make the scene feel calm rather than completely still.","start":20.435736961451248,"end":26.35061224489796},{"text":"What caught my attention was that it didn't include every detail.","start":26.35061224489796,"end":30.01260770975057},{"text":"My friend had left out things that weren't important to the scene.","start":30.01260770975057,"end":33.59378684807256},{"text":"That made it easier to notice the boat, the light and the relationship between the colours.","start":33.59378684807256,"end":38.635238095238094},{"text":"He gave it to me later as a gift.","start":38.635238095238094,"end":40.69238095238095},{"text":"I put it near my desk, where I could see it without it taking up much space.","start":40.69238095238095,"end":45.37891156462585},{"text":"I look at it after a busy day, and it reminds me of our walk and conversation.","start":45.37891156462585,"end":50.532426303854876},{"text":"I like it partly because of the picture itself, but also because someone I know took the time to make it.","start":50.532426303854876,"end":56.681768707482995},{"text":"I wouldn't try to judge its financial value.","start":56.681768707482995,"end":59.47587301587301},{"text":"For me, its value comes from the memory and the thought behind the gift.","start":59.47587301587301,"end":63.368979591836734}],"sha256":"877c628d7bcda3da55764041cbe253424f9fcec7b2dc7cf3920cbb4f81f8e504"},"audio/daniel-synced-160/6cf27fe3725a5c6a.m4a":{"duration":66.9160544217687,"segments":[{"text":"A short journey I don't enjoy is the drive from home to the supermarket when the roads are busy.","start":0.0,"end":5.149070294784581},{"text":"I make it because I need to buy groceries, but it can take much longer than the distance would suggest.","start":5.149070294784581,"end":11.289342403628117},{"text":"One Saturday, I left at a busy time without thinking about the journey.","start":11.289342403628117,"end":15.589886621315193},{"text":"I had things to do afterwards, so I assumed I could get the shopping finished quickly.","start":15.589886621315193,"end":20.85687074829932},{"text":"Instead, the traffic moved slowly, and I spent much longer on the road than I had planned.","start":20.85687074829932,"end":26.47297052154195},{"text":"What bothered me most was the uncertainty.","start":26.47297052154195,"end":29.008798185941043},{"text":"I could see that the supermarket wasn't very far away, but I couldn't tell how long it would take to reach it.","start":29.008798185941043,"end":35.41360544217687},{"text":"I kept thinking about the other tasks waiting for me at home.","start":35.41360544217687,"end":39.37133786848072},{"text":"When I finally arrived, I still had to choose everything and pay, so the whole errand felt less simple than I had expected.","start":39.37133786848072,"end":46.609206349206346},{"text":"Nothing serious happened.","start":46.609206349206346,"end":48.32154195011338},{"text":"It was mainly a frustrating use of time for an ordinary task.","start":48.32154195011338,"end":52.393469387755104},{"text":"Since then, I've tried to go at a quieter time and prepare a list before leaving.","start":52.393469387755104,"end":57.29637188208617},{"text":"That doesn't make the journey exciting, but it makes it easier to manage.","start":57.29637188208617,"end":61.56902494331066},{"text":"I dislike it because a short, necessary trip can sometimes take up too much of my day.","start":61.56902494331066,"end":66.9160544217687}],"sha256":"02cc64e91a5cd8bee329b4f6c719bd531f18fc5c38644210b0d51e240f1dc24b"},"audio/daniel-synced-160/384f2395ca4b0bad.m4a":{"duration":73.81863945578232,"segments":[{"text":"I'd like to talk about my friend Alex, who runs a small coffee shop near a residential area.","start":0.0,"end":5.950113378684807},{"text":"I met him through a mutual friend a few years ago.","start":5.950113378684807,"end":8.896598639455782},{"text":"Since then, I've visited his shop fairly often, usually on a Saturday morning.","start":8.896598639455782,"end":14.0459410430839},{"text":"When he first opened it, the business was difficult.","start":14.0459410430839,"end":17.162267573696145},{"text":"There weren't many customers in the morning, and some food was left unsold at the end of each day.","start":17.162267573696145,"end":22.574920634920634},{"text":"Instead of immediately spending more money on advertising, he asked regular customers what they wanted and checked which items actually sold.","start":22.574920634920634,"end":30.81482993197279},{"text":"He reduced the menu to a few reliable choices, prepared smaller batches and introduced a simple breakfast combination.","start":30.81482993197279,"end":38.02680272108844},{"text":"He also created a quiet corner where customers could read or work.","start":38.02680272108844,"end":42.10408163265306},{"text":"Gradually, people started coming back.","start":42.10408163265306,"end":44.95369614512472},{"text":"What I like most is the service: he remembers regular customers' orders and deals with problems politely.","start":44.95369614512472,"end":51.16988662131519},{"text":"Once, my coffee arrived cold, and he replaced it without making the situation awkward.","start":51.16988662131519,"end":56.91269841269841},{"text":"I'm pleased to see his hard work paying off.","start":56.91269841269841,"end":59.54235827664399},{"text":"I respect him because he looked at the actual problem instead of hoping it would disappear.","start":59.54235827664399,"end":64.37981859410431},{"text":"The shop now has regular visitors, and his experience reminds me that success can come from a series of sensible improvements, rather than one dramatic idea.","start":64.37981859410431,"end":73.81863945578232}],"sha256":"bfa7b385c660f50cf1a6126a86598493a0465336309936e0a3c6863d9682ef5e"},"audio/daniel-synced-160/291d159131878e88.m4a":{"duration":72.34530612244897,"segments":[{"text":"A happy person I know is my colleague Adam.","start":0.0,"end":2.571655328798186},{"text":"We met at work about two years ago and gradually became friends.","start":2.571655328798186,"end":6.547120181405896},{"text":"He isn't excited all the time, but he usually seems comfortable with himself and finds something positive in an ordinary day.","start":6.547120181405896,"end":14.156462585034014},{"text":"He enjoys small things, like having a good conversation or helping someone finish a task.","start":14.156462585034014,"end":19.859138321995466},{"text":"When a plan goes wrong, he tends to focus on what we can try next rather than complain about the whole situation.","start":19.859138321995466,"end":26.69065759637188},{"text":"That makes it pleasant to work with him.","start":26.69065759637188,"end":29.212743764172334},{"text":"A few months ago, I had to explain a new idea to our team.","start":29.212743764172334,"end":33.258866213151926},{"text":"I knew the details, but I couldn't present them clearly.","start":33.258866213151926,"end":36.78575963718821},{"text":"Adam suggested using one simple example instead of showing everything at once.","start":36.78575963718821,"end":41.70263038548753},{"text":"He also helped me practise and pointed out the parts that were difficult to follow.","start":41.70263038548753,"end":46.281768707482996},{"text":"The presentation went much better than I expected.","start":46.281768707482996,"end":49.27755102040816},{"text":"People understood the idea, and I felt more confident afterwards.","start":49.27755102040816,"end":53.5178231292517},{"text":"What I appreciate most is that he helped me learn a useful skill rather than just doing the work for me.","start":53.5178231292517,"end":59.608979591836736},{"text":"I think he is a happy person because he doesn't expect everything to be perfect.","start":59.608979591836736,"end":64.26004535147392},{"text":"He puts effort into things he can change and doesn't spend the whole day worrying about things he can't control.","start":64.26004535147392,"end":70.21814058956916},{"text":"Being around him often improves my mood.","start":70.21814058956916,"end":72.34530612244897}],"sha256":"c91a9435719ef001607316dce5a00940a1a3d0d6112add77d4bc9553ecb23c66"},"audio/daniel-synced-160/59407d95d04064e6.m4a":{"duration":76.47773242630386,"segments":[{"text":"I'd like to describe an interview with Lei Jun, the co-founder of Xiaomi, conducted by Li Xiang.","start":0.0,"end":6.22875283446712},{"text":"The video was released in July 2024, and it looked back at Xiaomi's three-year journey into making electric cars.","start":6.22875283446712,"end":14.146848072562358},{"text":"I watched part of it online at home one evening because I wanted to hear about the decisions behind a new business.","start":14.146848072562358,"end":20.61233560090703},{"text":"I had a personal reason to choose this interview.","start":20.61233560090703,"end":23.361360544217685},{"text":"Lei Jun comes from the same part of China as I do, and we both studied at Wuhan University.","start":23.361360544217685,"end":29.229614512471656},{"text":"I already recognised his name, but those connections made me more interested in the person behind the company.","start":29.229614512471656,"end":35.75233560090703},{"text":"The main subject was the experience of entering the car industry.","start":35.75233560090703,"end":39.59541950113379},{"text":"What interested me was the difference between having an ambitious idea and turning it into something real.","start":39.59541950113379,"end":45.18462585034013},{"text":"Building a new type of product involves learning, working with other people and making difficult decisions.","start":45.18462585034013,"end":51.19192743764172},{"text":"The interview gave me a useful subject to think about, beyond the excitement of a product launch.","start":51.19192743764172,"end":57.290340136054425},{"text":"I found it worth watching because I enjoy hearing about how people approach an unfamiliar challenge.","start":57.290340136054425,"end":63.00952380952381},{"text":"I didn't watch the whole long video in one sitting, but it made me curious enough to come back to it.","start":63.00952380952381,"end":68.7307029478458},{"text":"I'd recommend it to a friend who's interested in technology or entrepreneurship, especially someone who shares our university background.","start":68.7307029478458,"end":76.47773242630386}],"sha256":"2f8fe276874141f73e9c3e0428241249d2bd61c3586485d53ab60bcad85c19b6"},"audio/daniel-synced-160/a6a6b8791db65725.m4a":{"duration":73.78643990929706,"segments":[{"text":"A noisy place I remember visiting is a busy market near Dubai Creek.","start":0.0,"end":4.127392290249433},{"text":"I went there with a friend on a weekend afternoon.","start":4.127392290249433,"end":6.875056689342403},{"text":"We wanted to explore the area, look at the small shops and see something different from our usual surroundings.","start":6.875056689342403,"end":13.465396825396825},{"text":"We started near the creek and spent some time looking at the old buildings and small shops.","start":13.465396825396825,"end":18.45092970521542},{"text":"What I liked was the atmosphere.","start":18.45092970521542,"end":20.47591836734694},{"text":"It felt different from the modern shopping malls I normally see.","start":20.47591836734694,"end":24.022766439909297},{"text":"There were narrow streets, people selling different products, and plenty of small details to notice.","start":24.022766439909297,"end":30.40222222222222},{"text":"The narrow paths were full of shoppers.","start":30.40222222222222,"end":32.703537414965986},{"text":"I could hear sellers calling to customers, groups talking loudly and carts moving between the shops.","start":32.703537414965986,"end":38.67877551020408},{"text":"The sounds overlapped, so my friend and I sometimes had to repeat ourselves.","start":38.67877551020408,"end":43.48825396825397},{"text":"I found it lively at first, but after a while I wanted a break.","start":43.48825396825397,"end":47.79365079365079},{"text":"We also had a simple drink and talked for a while.","start":47.79365079365079,"end":50.828707482993195},{"text":"The outing didn't cost us much, but I enjoyed it more than some expensive activities I've tried.","start":50.828707482993195,"end":56.84575963718821},{"text":"I enjoyed looking around, but I wouldn't want to spend the whole day there.","start":56.84575963718821,"end":61.0330612244898},{"text":"The noise made it difficult to concentrate on a conversation.","start":61.0330612244898,"end":64.52784580498866},{"text":"Moving to the quieter waterfront afterwards helped me appreciate the difference.","start":64.52784580498866,"end":69.03777777777778},{"text":"So it was interesting to visit, even though it wasn't somewhere I could fully relax.","start":69.03777777777778,"end":73.78643990929706}],"sha256":"543014fd7404a20b6fd3bf4327028fba97eed78fceed63e7625a2ae52657d79c"},"audio/daniel-synced-160/9ea7e40b9f0b0490.m4a":{"duration":72.00648526077097,"segments":[{"text":"A person I know who really enjoys photography is my colleague Adam.","start":0.0,"end":3.9300226757369616},{"text":"We met at work about two years ago and became friends.","start":3.9300226757369616,"end":7.417868480725623},{"text":"Outside work, he often takes photos of ordinary streets, small shops and interesting patterns in buildings.","start":7.417868480725623,"end":14.543219954648526},{"text":"He usually uses his phone rather than carrying a lot of equipment.","start":14.543219954648526,"end":18.365079365079364},{"text":"What I like about his photos is that he notices details other people walk past.","start":18.365079365079364,"end":23.23455782312925},{"text":"He might photograph the reflection in a window or the shadow of a tree instead of a famous landmark.","start":23.23455782312925,"end":28.800544217687076},{"text":"Last month, we went for a walk near Dubai Creek.","start":28.800544217687076,"end":32.19582766439909},{"text":"I took a quick photo and thought the scene looked rather ordinary.","start":32.19582766439909,"end":35.94195011337869},{"text":"Adam suggested moving a few steps to the side and waiting until fewer people were in the picture.","start":35.94195011337869,"end":41.183900226757366},{"text":"The result looked much clearer.","start":41.183900226757366,"end":43.195238095238096},{"text":"He also explained that good light matters more than simply having an expensive camera.","start":43.195238095238096,"end":48.096825396825395},{"text":"I enjoyed learning something practical without having to study a long list of technical terms.","start":48.096825396825395,"end":53.52639455782313},{"text":"We compared our pictures afterwards and talked about why they looked different.","start":53.52639455782313,"end":57.876009070294785},{"text":"I appreciate his hobby because it encourages him to pay attention to his surroundings.","start":57.876009070294785,"end":62.74780045351474},{"text":"His example has made me look more carefully when I go for a walk.","start":62.74780045351474,"end":66.6277097505669},{"text":"I still don't take photos as seriously as he does, but I understand why he enjoys it.","start":66.6277097505669,"end":72.00648526077097}],"sha256":"c8c69a260f944b0a228944aaf3799d08313c13fac0b0e9af849d0bcd12e4f17c"},"audio/daniel-synced-160/ad68db0de23746f6.m4a":{"duration":71.33165532879819,"segments":[{"text":"A time I listened to something I wasn't initially interested in was when my grandmother explained how she looked after her plants.","start":0.0,"end":7.25047619047619},{"text":"I visited her one afternoon, and she was excited to show me a plant that had produced new leaves.","start":7.25047619047619,"end":13.425396825396826},{"text":"At first, I didn't really care about the details.","start":13.425396825396826,"end":17.018730158730158},{"text":"I thought she would point out the plant quickly, but she began explaining the light, watering and changes she had noticed over several weeks.","start":17.018730158730158,"end":24.908979591836733},{"text":"I was tempted to change the subject.","start":24.908979591836733,"end":27.496734693877553},{"text":"I kept listening because I knew the hobby mattered to her.","start":27.496734693877553,"end":30.77845804988662},{"text":"She had put time and effort into it, and I didn't want to make her feel that her excitement was unimportant.","start":30.77845804988662,"end":36.79451247165533},{"text":"I put my phone away and asked a couple of simple questions.","start":36.79451247165533,"end":40.74063492063492},{"text":"As the conversation continued, I became more interested.","start":40.74063492063492,"end":44.43845804988662},{"text":"I could see that she enjoyed noticing small changes and solving practical problems.","start":44.43845804988662,"end":49.5081179138322},{"text":"I also learned why giving a plant too much attention could sometimes be less helpful than being patient.","start":49.5081179138322,"end":55.56643990929705},{"text":"I felt glad that I had listened properly.","start":55.56643990929705,"end":58.197369614512475},{"text":"The conversation made her happy and helped me understand her hobby rather than just see it as a collection of pots.","start":58.197369614512475,"end":64.45537414965986},{"text":"It reminded me that showing interest in another person's experience can matter even when the subject isn't one of my favourites.","start":64.45537414965986,"end":71.33165532879819}],"sha256":"d7f0ba1171698da383cb81b0d28a43142218030e2fe6447e6b780c3657c0fefa"},"audio/daniel-synced-160/421068e5a892b42f.m4a":{"duration":71.93428571428572,"segments":[{"text":"The good service I'd like to describe was the help I received in a shop when my headphones stopped working.","start":0.0,"end":5.851655328798186},{"text":"I had bought them a few weeks earlier after saving up.","start":5.851655328798186,"end":8.914104308390023},{"text":"Because I used them often, I was disappointed when one side began to fail.","start":8.914104308390023,"end":13.914195011337869},{"text":"I brought the headphones and the proof of purchase back to the shop.","start":13.914195011337869,"end":17.381632653061224},{"text":"The assistant asked me to explain what had happened and listened without interrupting.","start":17.381632653061224,"end":21.97972789115646},{"text":"He then checked the problem instead of immediately suggesting that I had caused it.","start":21.97972789115646,"end":26.616916099773242},{"text":"He explained the next steps in language I could understand and told me what information the shop needed.","start":26.616916099773242,"end":32.35442176870748},{"text":"After confirming the fault, the staff arranged a replacement.","start":32.35442176870748,"end":36.24213151927437},{"text":"I appreciated knowing what was happening, rather than being passed from one person to another.","start":36.24213151927437,"end":41.78993197278911},{"text":"The assistant also gave me time to ask questions and check the replacement.","start":41.78993197278911,"end":46.2487074829932},{"text":"I had expected the visit to be stressful, but it was straightforward.","start":46.2487074829932,"end":50.377913832199546},{"text":"The most helpful part was his calm attitude, which made me feel that the problem was being taken seriously.","start":50.377913832199546,"end":57.10290249433107},{"text":"That experience made the purchase more memorable.","start":57.10290249433107,"end":59.98244897959184},{"text":"I appreciated both the product and the way the problem was handled.","start":59.98244897959184,"end":63.600362811791385},{"text":"For me, the value wasn't just the price or the brand.","start":63.600362811791385,"end":67.00848072562358},{"text":"It was having something useful and knowing that I could get help when it didn't work as expected.","start":67.00848072562358,"end":71.93428571428572}],"sha256":"15dd27680c6706d6e2b99d7d195c85e1d66477fbfa7f1d1fcfd5ba4a4e34680b"},"audio/daniel-synced-160/67c06156d6567dfc.m4a":{"duration":70.03342403628118,"segments":[{"text":"A person I know who is good at making things by hand is my grandmother.","start":0.0,"end":4.069342403628118},{"text":"When I was a child, I often visited her home and watched her repair clothes or make small useful items.","start":4.069342403628118,"end":10.355192743764173},{"text":"She enjoyed the process and didn't rush through it.","start":10.355192743764173,"end":13.204353741496599},{"text":"One summer, when I was about ten, she helped me make a simple cloth bag.","start":13.204353741496599,"end":17.98090702947846},{"text":"We chose some spare material and decided on a size that I could use for a few books.","start":17.98090702947846,"end":22.76907029478458},{"text":"She showed me how to measure it and join the pieces carefully.","start":22.76907029478458,"end":26.28},{"text":"My first attempt was uneven, and I wanted to start again.","start":26.28,"end":30.139773242630387},{"text":"She explained that we could undo one small section and fix it instead.","start":30.139773242630387,"end":34.22857142857143},{"text":"That made the task feel less intimidating.","start":34.22857142857143,"end":36.96879818594104},{"text":"I slowly began to understand that a mistake didn't mean the whole item was ruined.","start":36.96879818594104,"end":41.71528344671202},{"text":"When we finished, the bag wasn't perfect, but it was useful.","start":41.71528344671202,"end":45.725578231292516},{"text":"I felt proud that I had helped make something rather than just buy it.","start":45.725578231292516,"end":49.72648526077098},{"text":"I used it afterwards, which made the experience more memorable.","start":49.72648526077098,"end":54.04412698412698},{"text":"I admire her patience and practical skills.","start":54.04412698412698,"end":56.93061224489796},{"text":"She could turn simple materials into something that solved a small everyday problem.","start":56.93061224489796,"end":61.59990929705216},{"text":"I don't make many things by hand now, but the lesson has stayed with me: work carefully, notice mistakes and improve one part at a time.","start":61.59990929705216,"end":70.03342403628118}],"sha256":"d762dedd83764f25bdde0694246051e949c248f47f1f727a2d28ce22451cd658"},"audio/daniel-synced-160/ea69a9a36c035b24.m4a":{"duration":65.60725623582766,"segments":[{"text":"One enjoyable evening was when a friend and I explored an older part of Dubai and then sat down for a drink near the creek.","start":0.0,"end":6.552879818594104},{"text":"It happened on a weekend a few months ago.","start":6.552879818594104,"end":9.031609977324264},{"text":"Neither of us wanted a big event; we just wanted time to talk.","start":9.031609977324264,"end":13.31219954648526},{"text":"We started near the creek and spent some time looking at the old buildings and small shops.","start":13.31219954648526,"end":18.297732426303856},{"text":"What I liked was the atmosphere.","start":18.297732426303856,"end":20.322721088435372},{"text":"It felt different from the modern shopping malls I normally see.","start":20.322721088435372,"end":23.86956916099773},{"text":"There were narrow streets, people selling different products, and plenty of small details to notice.","start":23.86956916099773,"end":30.24902494331066},{"text":"As it became darker, the area felt calmer.","start":30.24902494331066,"end":33.21546485260771},{"text":"We walked past the shops, took a few photos and then chose somewhere comfortable to sit.","start":33.21546485260771,"end":38.526167800453514},{"text":"We talked about things that had happened that week, shared a few funny stories and stopped checking our phones for a while.","start":38.526167800453514,"end":45.58095238095238},{"text":"We also had a simple drink and talked for a while.","start":45.58095238095238,"end":48.61600907029479},{"text":"The outing didn't cost us much, but I enjoyed it more than some expensive activities I've tried.","start":48.61600907029479,"end":54.63306122448979},{"text":"I remember feeling relaxed afterwards.","start":54.63306122448979,"end":57.24140589569161},{"text":"It reminded me that I don't always need a complicated plan to have a good day.","start":57.24140589569161,"end":61.78671201814059},{"text":"Sometimes a walk, a friend and a change of surroundings are enough.","start":61.78671201814059,"end":65.60725623582766}],"sha256":"7fcdc0e8a64019c6e351a806069e6720011f4a6770873b08c20576a872008d55"},"audio/daniel-synced-160/d3f733a06385b4a0.m4a":{"duration":74.21410430839002,"segments":[{"text":"An activity I regularly do that I consider a waste of time is scrolling through short posts on my phone.","start":0.0,"end":6.077913832199546},{"text":"It often happens after work.","start":6.077913832199546,"end":8.103854875283446},{"text":"I tell myself that I'll look for a few minutes, but the activity can take up much more of the evening than I intended.","start":8.103854875283446,"end":15.068526077097506},{"text":"The problem was that I didn't feel rested afterwards.","start":15.068526077097506,"end":18.31972789115646},{"text":"I was still tired, and sometimes I went to bed later than I had planned.","start":18.31972789115646,"end":22.775419501133786},{"text":"So I decided to replace part of that screen time with a short walk.","start":22.775419501133786,"end":26.937233560090704},{"text":"I started with just ten minutes because I knew I wouldn't stick to an ambitious exercise plan.","start":26.937233560090704,"end":32.37768707482993},{"text":"When the weather was comfortable, I walked outside.","start":32.37768707482993,"end":35.57519274376417},{"text":"On other days, I found somewhere indoors where I could move around.","start":35.57519274376417,"end":39.77219954648526},{"text":"I usually left my phone in my pocket and paid attention to my surroundings.","start":39.77219954648526,"end":44.46136054421769},{"text":"After a while, a friend began joining me.","start":44.46136054421769,"end":47.51655328798186},{"text":"That made the habit easier to maintain because we could chat and remind each other to go.","start":47.51655328798186,"end":52.21886621315193},{"text":"We weren't trying to become athletes.","start":52.21886621315193,"end":54.39487528344671},{"text":"We just wanted to do something more active after sitting for most of the day.","start":54.39487528344671,"end":58.9534693877551},{"text":"I consider it a waste of time because I usually haven't chosen a clear purpose and I remember very little afterwards.","start":58.9534693877551,"end":65.70657596371882},{"text":"A few useful posts do appear, but they don't justify all the time I spend.","start":65.70657596371882,"end":70.57700680272109},{"text":"I'm trying to keep a limit and choose a more deliberate way to relax.","start":70.57700680272109,"end":74.21410430839002}],"sha256":"74167b9badbad983a8cb78390f0354ee8df577029f29d270d32bd1b67f6d740e"},"audio/daniel-synced-160/38e6c6601b3533d8.m4a":{"duration":68.99909297052154,"segments":[{"text":"A crowded place I've visited is a market near Dubai Creek.","start":0.0,"end":3.454013605442177},{"text":"I went there with a friend on a weekend afternoon.","start":3.454013605442177,"end":6.201678004535148},{"text":"We wanted to explore the small shops and take a few photos, but there were more people than we had expected.","start":6.201678004535148,"end":12.466938775510204},{"text":"We started near the creek and spent some time looking at the old buildings and small shops.","start":12.466938775510204,"end":17.452471655328797},{"text":"What I liked was the atmosphere.","start":17.452471655328797,"end":19.477460317460316},{"text":"It felt different from the modern shopping malls I normally see.","start":19.477460317460316,"end":23.024308390022675},{"text":"There were narrow streets, people selling different products, and plenty of small details to notice.","start":23.024308390022675,"end":29.403764172335602},{"text":"At some points, the path was so busy that we had to wait before moving forward.","start":29.403764172335602,"end":34.14648526077097},{"text":"People stopped to look at products while others tried to pass them.","start":34.14648526077097,"end":37.77142857142857},{"text":"I kept my bag close and paid attention to where my friend was, because it would have been easy to lose each other.","start":37.77142857142857,"end":44.20204081632653},{"text":"We also had a simple drink and talked for a while.","start":44.20204081632653,"end":47.237097505668935},{"text":"The outing didn't cost us much, but I enjoyed it more than some expensive activities I've tried.","start":47.237097505668935,"end":53.25414965986395},{"text":"The crowd gave the market an energetic atmosphere, but it also made simple things take longer.","start":53.25414965986395,"end":58.829478458049884},{"text":"I was glad we eventually found a quiet place to sit.","start":58.829478458049884,"end":62.16925170068027},{"text":"If I go again, I'll choose a less busy time so that I can enjoy the shops without constantly moving around other people.","start":62.16925170068027,"end":68.99909297052154}],"sha256":"a932d2c0f593aacf1a3b98f7a15c89bd0f22c5007f4798639171ec207a839695"},"audio/daniel-synced-160/69eaa4d2fc6a999d.m4a":{"duration":65.42344671201813,"segments":[{"text":"I'd like to talk about Ben, a childhood friend who learns about history in his free time.","start":0.0,"end":5.57859410430839},{"text":"We grew up in the same neighbourhood, and we still talk regularly.","start":5.57859410430839,"end":9.263854875283446},{"text":"His interest has made me look at familiar places differently.","start":9.263854875283446,"end":12.937414965986395},{"text":"His interest started with a box of his grandfather's old photographs.","start":12.937414965986395,"end":17.09596371882086},{"text":"Ben wanted to know who the people were and why the streets looked different.","start":17.09596371882086,"end":20.93219954648526},{"text":"He asked his grandfather about them and put the pictures in an album with short descriptions.","start":20.93219954648526,"end":25.93827664399093},{"text":"It became a record of his family's life as well as the town's history.","start":25.93827664399093,"end":30.103083900226757},{"text":"When we visited a local museum, he showed me an old railway map and explained how trains had helped the town develop.","start":30.103083900226757,"end":36.957687074829934},{"text":"He didn't just repeat dates from the labels.","start":36.957687074829934,"end":39.59532879818594},{"text":"He connected the railway with local shops, jobs and travel, which made the explanation easy to follow.","start":39.59532879818594,"end":46.07850340136054},{"text":"He also takes photographs of interesting museum displays and looks up unfamiliar details afterwards.","start":46.07850340136054,"end":52.1875283446712},{"text":"I used to think history was mostly about remembering facts for school, but his enthusiasm changed my mind.","start":52.1875283446712,"end":58.847755102040814},{"text":"Through him, I've realised that it can explain ordinary places and help us understand how people lived before us.","start":58.847755102040814,"end":65.42344671201813}],"sha256":"4e969b96c45b35acb0be60dd0301e6f97e94d235c1d951c526ecc551f78fe19b"},"audio/daniel-synced-160/5600ea75015f8bef.m4a":{"duration":73.95473922902494,"segments":[{"text":"The person I'd like to describe is my colleague Adam, who taught me how to present a complicated idea clearly.","start":0.0,"end":6.457777777777777},{"text":"We met at work about two years ago, and he is a few years older than me.","start":6.457777777777777,"end":11.002131519274377},{"text":"Before he helped me, I often included too many details when explaining something.","start":11.002131519274377,"end":16.39687074829932},{"text":"What stands out about him is how organised he is.","start":16.39687074829932,"end":19.292607709750566},{"text":"Before starting a task, he writes down the main steps and decides what needs to be done first.","start":19.292607709750566,"end":25.091156462585033},{"text":"He doesn't make things complicated.","start":25.091156462585033,"end":27.392108843537414},{"text":"In fact, he's usually the person who makes a confusing situation easier to understand.","start":27.392108843537414,"end":33.13587301587302},{"text":"A few months ago, I had to explain a new idea to our team.","start":33.13587301587302,"end":37.181995464852605},{"text":"I knew the details, but I couldn't present them clearly.","start":37.181995464852605,"end":40.708888888888886},{"text":"Adam suggested using one simple example instead of showing everything at once.","start":40.708888888888886,"end":45.62575963718821},{"text":"He also helped me practise and pointed out the parts that were difficult to follow.","start":45.62575963718821,"end":50.204897959183675},{"text":"The presentation went much better than I expected.","start":50.204897959183675,"end":53.20068027210884},{"text":"People understood the idea, and I felt more confident afterwards.","start":53.20068027210884,"end":57.44095238095238},{"text":"What I appreciate most is that he helped me learn a useful skill rather than just doing the work for me.","start":57.44095238095238,"end":63.532108843537415},{"text":"Since then, I've tried to follow his approach.","start":63.532108843537415,"end":66.65868480725624},{"text":"Whenever a task feels overwhelming, I break it into smaller steps.","start":66.65868480725624,"end":71.0172335600907},{"text":"So he's had a positive influence on the way I work.","start":71.0172335600907,"end":73.95473922902494}],"sha256":"4327754f48844ad811107160bc65f8fc7b65742c59087da9db955ceca3c252f1"},"audio/daniel-synced-160/3082418a5f20caa8.m4a":{"duration":73.28077097505668,"segments":[{"text":"The film I'd choose is The Martian.","start":0.0,"end":1.99718820861678},{"text":"I watched it at home a few months ago after reading the novel by Andy Weir.","start":1.99718820861678,"end":6.219319727891157},{"text":"Because I had enjoyed the book, I expected the film to give me the same sense of involvement, but some parts disappointed me.","start":6.219319727891157,"end":13.994195011337869},{"text":"The story follows an astronaut called Mark Watney who is accidentally left behind on Mars.","start":13.994195011337869,"end":19.462721088435373},{"text":"He has to work out how to survive and contact Earth.","start":19.462721088435373,"end":22.541541950113377},{"text":"The main idea is interesting, and I liked the fact that science and practical thinking were important to the story.","start":22.541541950113377,"end":29.048299319727892},{"text":"My disappointment was mainly about the pace of the problem-solving.","start":29.048299319727892,"end":32.780362811791385},{"text":"In the book, I could spend time following his thoughts and understanding why a particular solution might work.","start":32.780362811791385,"end":38.99750566893424},{"text":"In the film, some of those steps felt rushed, so I was less involved in the decisions.","start":38.99750566893424,"end":44.868979591836734},{"text":"The visuals were impressive, and the acting was enjoyable, but I sometimes felt that a difficult problem had been solved before I fully understood it.","start":44.868979591836734,"end":53.23102040816327},{"text":"I watched it with a friend, and we discussed that difference afterwards.","start":53.23102040816327,"end":57.583492063492066},{"text":"I wouldn't describe it as a terrible film.","start":57.583492063492066,"end":60.19183673469388},{"text":"My expectations were simply too closely connected to the book.","start":60.19183673469388,"end":63.912290249433106},{"text":"I learned that an adaptation can tell the same story while creating a different experience.","start":63.912290249433106,"end":69.16766439909297},{"text":"If I watched it again, I'd probably judge it more on its own terms.","start":69.16766439909297,"end":73.28077097505668}],"sha256":"8a913772b44dccc6acf029ad7ff48f8706cff4b17c5906de13e0c6b0dc0f3aa9"},"audio/daniel-synced-160/7d30cb63ef8cacda.m4a":{"duration":74.64199546485261,"segments":[{"text":"A popular person I know is my colleague Adam.","start":0.0,"end":2.6877551020408164},{"text":"We met at work about two years ago and gradually became friends.","start":2.6877551020408164,"end":6.663219954648526},{"text":"Many people in our team enjoy working with him because he is approachable and takes other people's questions seriously.","start":6.663219954648526,"end":13.288843537414966},{"text":"He remembers small things about people and is willing to help without making a big show of it.","start":13.288843537414966,"end":18.143990929705215},{"text":"For example, if someone is new to the team, he explains the basic information and checks whether they are comfortable asking questions.","start":18.143990929705215,"end":26.323809523809523},{"text":"That makes people feel included.","start":26.323809523809523,"end":28.579047619047618},{"text":"A few months ago, I had to explain a new idea to our team.","start":28.579047619047618,"end":32.62517006802721},{"text":"I knew the details, but I couldn't present them clearly.","start":32.62517006802721,"end":36.15206349206349},{"text":"Adam suggested using one simple example instead of showing everything at once.","start":36.15206349206349,"end":41.068934240362815},{"text":"He also helped me practise and pointed out the parts that were difficult to follow.","start":41.068934240362815,"end":45.64807256235828},{"text":"The presentation went much better than I expected.","start":45.64807256235828,"end":48.643854875283445},{"text":"People understood the idea, and I felt more confident afterwards.","start":48.643854875283445,"end":52.884126984126986},{"text":"What I appreciate most is that he helped me learn a useful skill rather than just doing the work for me.","start":52.884126984126986,"end":58.97528344671202},{"text":"I think he is popular because people feel respected around him.","start":58.97528344671202,"end":62.86009070294784},{"text":"He doesn't need to dominate a conversation or impress everyone.","start":62.86009070294784,"end":66.6471201814059},{"text":"His friendliness and willingness to help are enough.","start":66.6471201814059,"end":69.33120181405896},{"text":"I enjoy his company for the same reasons, and I try to learn from the way he treats others.","start":69.33120181405896,"end":74.64199546485261}],"sha256":"bb65bf8a7a65f13552e997bed39d11c4e1a5f9c7ccb190d6b4b3367a18a23109"},"audio/daniel-synced-160/3a33caf871504f9c.m4a":{"duration":72.59614512471656,"segments":[{"text":"A person whose fitness I helped improve is a friend called Sam.","start":0.0,"end":3.813922902494331},{"text":"Like me, he spent most of his working day sitting down.","start":3.813922902494331,"end":7.522675736961451},{"text":"He wanted to be more active, but he found it difficult to start an exercise routine that he could continue.","start":7.522675736961451,"end":13.773650793650793},{"text":"A few months ago, I suggested that we begin with a short walk after work.","start":13.773650793650793,"end":18.49315192743764},{"text":"I didn't give him complicated fitness advice.","start":18.49315192743764,"end":21.5324716553288},{"text":"I simply thought doing something together would make the first step easier.","start":21.5324716553288,"end":25.521678004535147},{"text":"We agreed to try ten minutes rather than set an ambitious target.","start":25.521678004535147,"end":29.639092970521542},{"text":"When the weather was comfortable, we walked outside.","start":29.639092970521542,"end":32.80176870748299},{"text":"Otherwise, we found somewhere suitable indoors.","start":32.80176870748299,"end":36.070022675736965},{"text":"I checked in with him before the walk and tried to make the plan convenient.","start":36.070022675736965,"end":40.00185941043084},{"text":"On days when one of us felt tired, we still did a shorter version instead of cancelling everything.","start":40.00185941043084,"end":46.093922902494334},{"text":"After a few weeks, he said the routine had become easier to maintain.","start":46.093922902494334,"end":50.484263038548754},{"text":"He also enjoyed having a break between work and the rest of the evening.","start":50.484263038548754,"end":54.37578231292517},{"text":"I can't claim that it transformed his health, but it did help him spend more time moving regularly.","start":54.37578231292517,"end":60.34199546485261},{"text":"The hardest part was getting started and keeping the plan simple.","start":60.34199546485261,"end":64.04566893424037},{"text":"I'm pleased that I could support him without putting pressure on him.","start":64.04566893424037,"end":67.65056689342404},{"text":"Helping with a small habit was more practical than telling him to make a huge change overnight.","start":67.65056689342404,"end":72.59614512471656}],"sha256":"76751ea7734894f09c78c70dacfaefa074648260409dfd1045ca7868136e7292"},"audio/daniel-synced-160/518ac28610b21497.m4a":{"duration":66.44172335600906,"segments":[{"text":"A tall building I'd like to describe is the Burj Khalifa in Dubai.","start":0.0,"end":3.9300226757369616},{"text":"It is 828 metres high, and I saw it up close during an afternoon out with a friend.","start":3.9300226757369616,"end":9.729206349206349},{"text":"I had seen plenty of photographs before, but standing near it gave me a much stronger impression of its size.","start":9.729206349206349,"end":16.612607709750566},{"text":"What I noticed first was how far I had to look up.","start":16.612607709750566,"end":19.682494331065758},{"text":"From the ground, the upper part seemed very distant, and it was difficult to fit the whole building into one photograph.","start":19.682494331065758,"end":26.79487528344671},{"text":"We walked around the nearby area and stopped where we could see it more clearly.","start":26.79487528344671,"end":31.15609977324263},{"text":"I haven't visited an observation deck inside it, so I can't describe that experience.","start":31.15609977324263,"end":36.70172335600907},{"text":"What I'm describing is seeing it from outside.","start":36.70172335600907,"end":39.37687074829932},{"text":"I enjoyed noticing how the appearance changed as we moved and looked from different angles.","start":39.37687074829932,"end":44.61170068027211},{"text":"I don't usually take a strong interest in tall buildings, but this one made me curious about how such a large structure is designed and built.","start":44.61170068027211,"end":52.78258503401361},{"text":"I'd like to learn a little more about that process before another visit.","start":52.78258503401361,"end":56.796462585034014},{"text":"It stayed in my mind because the real experience felt different from seeing an image on a screen.","start":56.796462585034014,"end":62.235736961451245},{"text":"I'd like to go back at a different time of day to notice the light on its surface.","start":62.235736961451245,"end":66.44172335600906}],"sha256":"09b1b48f51eea66b54fec44d77ffe584e9b055c70da43328521a7d6194741061"},"audio/daniel-synced-160/8335f137585359f7.m4a":{"duration":73.39573696145125,"segments":[{"text":"An interesting video I watched was a recording of Roger Federer's 2024 commencement speech at Dartmouth.","start":0.0,"end":6.786077097505669},{"text":"A friend recommended it to me a few months ago.","start":6.786077097505669,"end":9.578321995464853},{"text":"I knew him as a tennis player, so I was curious about what he would say to graduating students.","start":9.578321995464853,"end":15.486485260770975},{"text":"I watched it at home when I had some time in the evening.","start":15.486485260770975,"end":18.71015873015873},{"text":"He shared lessons from tennis, but the part that stayed with me was the idea that a performance which looks effortless can actually require a great deal of work.","start":18.71015873015873,"end":27.677868480725625},{"text":"That caught my attention because I sometimes compare my own speaking with people who sound very confident.","start":27.677868480725625,"end":33.79659863945578},{"text":"I notice the result, but I don't always think about the practice behind it.","start":33.79659863945578,"end":38.343764172335604},{"text":"His explanation helped me look at that difference in a more useful way.","start":38.343764172335604,"end":42.55138321995465},{"text":"I also enjoyed the way he mixed personal experiences with a relaxed style.","start":42.55138321995465,"end":47.353197278911566},{"text":"The video didn't feel like a list of instructions I had to memorise.","start":47.353197278911566,"end":51.521179138322},{"text":"I could understand the main idea and connect it with something I was trying to improve myself.","start":51.521179138322,"end":57.02303854875284},{"text":"Afterwards, I thought about my English practice.","start":57.02303854875284,"end":60.44975056689342},{"text":"Instead of expecting every answer to sound natural immediately, I felt more willing to repeat it and make small changes.","start":60.44975056689342,"end":67.58408163265307},{"text":"I found the video interesting because advice from a different field could still be useful in my everyday life.","start":67.58408163265307,"end":73.39573696145125}],"sha256":"f98b139dc7d248ac27af4f2484f2f7d5756529f64761358aef402f9b66976af4"},"audio/daniel-synced-160/38ee9d004af7ab41.m4a":{"duration":68.3637641723356,"segments":[{"text":"A place I found boring was the waiting room of a customer-service centre.","start":0.0,"end":4.231882086167801},{"text":"I went there a while ago to update some account details, and I expected the visit to be fairly quick.","start":4.231882086167801,"end":10.27673469387755},{"text":"However, I needed to wait for my number to be called.","start":10.27673469387755,"end":13.78439909297052},{"text":"The room had rows of chairs and a few information posters on the walls.","start":13.78439909297052,"end":17.790068027210886},{"text":"There wasn't much to look at, and most people were sitting quietly.","start":17.790068027210886,"end":21.809977324263038},{"text":"I found a seat and checked the papers I had brought, but that only took a few minutes.","start":21.809977324263038,"end":26.951292517006802},{"text":"After that, I kept looking at the time and the number being shown.","start":26.951292517006802,"end":30.912063492063492},{"text":"I hadn't brought a book because I didn't expect to wait long.","start":30.912063492063492,"end":34.63492063492063},{"text":"I tried reading the information posters, although most of it wasn't connected with the reason I was there.","start":34.63492063492063,"end":40.68240362811791},{"text":"What made the place boring was having very little to do while not knowing exactly how long I would be waiting.","start":40.68240362811791,"end":46.503854875283444},{"text":"I couldn't simply leave, because I still needed to get the account issue sorted out.","start":46.503854875283444,"end":51.43419501133787},{"text":"The visit took around forty minutes before someone could help me.","start":51.43419501133787,"end":55.32616780045351},{"text":"The staff dealt with the task once it was my turn, so I wouldn't describe the whole service as bad.","start":55.32616780045351,"end":61.26140589569161},{"text":"It was mainly the waiting room experience that I disliked.","start":61.26140589569161,"end":64.76181405895692},{"text":"Next time, I'd bring something to read and allow more time.","start":64.76181405895692,"end":68.3637641723356}],"sha256":"e9634275ca13d061336182e9d4703d3ffb2f75495bdf6a03940462fb71157ebe"},"audio/daniel-synced-160/fc9e58c61d38ab2d.m4a":{"duration":65.02902494331066,"segments":[{"text":"A time I got up earlier than usual was one Saturday when I arranged to meet a friend for a morning walk.","start":0.0,"end":5.880544217687075},{"text":"We wanted to go out before the day became too hot, so we agreed to meet shortly after sunrise.","start":5.880544217687075,"end":12.122585034013605},{"text":"I'm not normally someone who wakes up very early on a day off.","start":12.122585034013605,"end":15.739092970521542},{"text":"To make it easier, I prepared my clothes and set an alarm the night before.","start":15.739092970521542,"end":20.16734693877551},{"text":"I also went to bed a little earlier instead of staying on my phone.","start":20.16734693877551,"end":24.333242630385488},{"text":"When the alarm rang, I wanted to go back to sleep.","start":24.333242630385488,"end":27.67015873015873},{"text":"However, I knew my friend was expecting me, so I got ready and left.","start":27.67015873015873,"end":32.59160997732426},{"text":"Once I was outside, I began to feel more awake.","start":32.59160997732426,"end":36.10267573696145},{"text":"The streets were quieter than usual, and the air felt more comfortable.","start":36.10267573696145,"end":40.63573696145125},{"text":"We walked for a while and then had breakfast together.","start":40.63573696145125,"end":43.496643990929705},{"text":"I enjoyed having time to talk without feeling rushed.","start":43.496643990929705,"end":46.7087074829932},{"text":"By the time I got home, I had already done something pleasant, and there was still most of the day left.","start":46.7087074829932,"end":53.12503401360544},{"text":"I was glad I had made the effort.","start":53.12503401360544,"end":55.22253968253968},{"text":"I wouldn't want to wake up at that time every weekend, but it showed me why some people enjoy an early start.","start":55.22253968253968,"end":61.30222222222222},{"text":"Planning one enjoyable activity made getting out of bed much easier.","start":61.30222222222222,"end":65.02902494331066}],"sha256":"05a38418f598c6e67541674d794a743e8e8e2c41f4e6e6ef22d4eb9f8ac0096b"},"audio/daniel-synced-160/5584a871df24e440.m4a":{"duration":78.52462585034013,"segments":[{"text":"A new rule I'd like to introduce more widely in China, my home country, would require large residential buildings to provide convenient recycling points and clear instructions.","start":0.0,"end":10.594149659863946},{"text":"Some places already have useful systems, but I'd like residents in more communities to have easy access to them.","start":10.594149659863946,"end":17.343038548752833},{"text":"The focus would be on making recycling a simple part of everyday life.","start":17.343038548752833,"end":21.7346485260771},{"text":"For example, each building could have an accessible collection area for paper, plastic bottles and metal cans.","start":21.7346485260771,"end":28.77668934240363},{"text":"The signs could use simple pictures and several languages, so new residents would understand what belongs in each container.","start":28.77668934240363,"end":35.86131519274377},{"text":"Building managers would also need to arrange regular collection.","start":35.86131519274377,"end":39.60734693877551},{"text":"I started thinking about this while sorting packaging at home.","start":39.60734693877551,"end":43.271473922902494},{"text":"Sometimes I have a few empty bottles or delivery boxes, and I want to deal with them properly without making a separate trip across the city.","start":43.271473922902494,"end":51.22780045351474},{"text":"A reliable collection point close to home would make the routine much simpler.","start":51.22780045351474,"end":55.77578231292517},{"text":"I'd prefer a gradual introduction, with clear guidance before penalties.","start":55.77578231292517,"end":60.32108843537415},{"text":"If people misunderstand the system, helping them correct the mistake would be more useful than immediately punishing them.","start":60.32108843537415,"end":67.13297052154195},{"text":"The main reason I support this idea is that convenience affects behaviour.","start":67.13297052154195,"end":71.56816326530613},{"text":"When the easier choice is also the environmentally responsible choice, more people are likely to follow it consistently.","start":71.56816326530613,"end":78.52462585034013}],"sha256":"ea2a648699d07486b4e65e68731dd390bea682d33286f3268c906a362d16f84b"},"audio/daniel-synced-160/58450a8d86d5ea0d.m4a":{"duration":68.85764172335601,"segments":[{"text":"I'd like to talk about my childhood friend Ben.","start":0.0,"end":2.9895691609977324},{"text":"We grew up in the same neighbourhood and became friends when we were about ten.","start":2.9895691609977324,"end":6.9766439909297056},{"text":"We used to ride our bikes after school, and although we now live in different cities, we still talk regularly.","start":6.9766439909297056,"end":13.601814058956917},{"text":"My clearest memory of Ben is from a school sports day.","start":13.601814058956917,"end":16.89269841269841},{"text":"I fell off my bike on the way home and felt embarrassed because other children were watching.","start":16.89269841269841,"end":21.706303854875284},{"text":"He stayed with me, checked that I was all right and walked his own bike beside mine.","start":21.706303854875284,"end":26.398911564625852},{"text":"It was a small gesture, but it showed me that I could count on him.","start":26.398911564625852,"end":30.552108843537415},{"text":"We were both quite curious as children.","start":30.552108843537415,"end":32.925442176870746},{"text":"We built small things from cardboard, borrowed books from the library and argued about which bike route was faster.","start":32.925442176870746,"end":39.3390022675737},{"text":"These days, we have different interests and live in different cities, but we still exchange messages.","start":39.3390022675737,"end":45.44848072562358},{"text":"He sometimes practises Chinese with me, and I ask him about his latest history project.","start":45.44848072562358,"end":51.28149659863946},{"text":"What makes the friendship valuable is that we can speak honestly without trying to impress each other.","start":51.28149659863946,"end":56.452834467120184},{"text":"He remembers what I was like before I started working, and that makes talking to him feel comfortable.","start":56.452834467120184,"end":62.34126984126984},{"text":"I'm glad we've stayed in touch because a friendship like that has grown through years of ordinary, shared experiences.","start":62.34126984126984,"end":68.85764172335601}],"sha256":"93467e361ce516fb339f8274592dd2d246cbde2c0e616de529b15504a5306618"},"audio/daniel-synced-160/9ac0f64de895dbd4.m4a":{"duration":75.06843537414966,"segments":[{"text":"One time I changed a plan was when I was organising a birthday gathering for a friend.","start":0.0,"end":5.148072562358276},{"text":"My original idea was to have a small picnic outdoors.","start":5.148072562358276,"end":8.589886621315193},{"text":"A few of us would bring food, sit together and keep the afternoon simple and inexpensive.","start":8.589886621315193,"end":13.985396825396826},{"text":"However, on the morning of the gathering, the weather looked windy, and the forecast suggested that rain was possible.","start":13.985396825396826,"end":20.567074829931972},{"text":"I realised that the food and decorations would be difficult to manage outside.","start":20.567074829931972,"end":24.893696145124718},{"text":"I also didn't want everyone to arrive and then feel uncomfortable.","start":24.893696145124718,"end":29.106031746031746},{"text":"I checked with the group and suggested meeting at a restaurant instead.","start":29.106031746031746,"end":32.91015873015873},{"text":"I found somewhere within our budget, confirmed that there was room for us and sent everyone the new address and time.","start":32.91015873015873,"end":39.37238095238095},{"text":"Another friend contacted the person bringing the cake so that it went to the right place.","start":39.37238095238095,"end":44.33832199546485},{"text":"The change meant that we no longer needed to prepare picnic food or carry everything outdoors.","start":44.33832199546485,"end":49.48176870748299},{"text":"We could simply meet, order a meal and enjoy the evening.","start":49.48176870748299,"end":52.888344671201814},{"text":"The birthday friend seemed pleased, and the atmosphere was relaxed because nobody was worrying about the weather.","start":52.888344671201814,"end":59.17460317460318},{"text":"I was happy with the decision because the important part of the plan was spending time together.","start":59.17460317460318,"end":64.22104308390023},{"text":"Although the setting changed, we still achieved that.","start":64.22104308390023,"end":67.47759637188209},{"text":"The experience taught me to keep the purpose of an event in mind and make a practical adjustment when the original arrangement becomes difficult.","start":67.47759637188209,"end":75.06843537414966}],"sha256":"760b917afcdf9edba8da00775219f4c23e7702e940c2b952bbf2cb2c4dce647f"},"audio/daniel-synced-160/e0a10c7be0dbf7bd.m4a":{"duration":74.85224489795918,"segments":[{"text":"A time I worked in a group was when a few colleagues and I built a small tool for a repeated task at work.","start":0.0,"end":5.9733786848072565},{"text":"We wanted to reduce the amount of manual checking.","start":5.9733786848072565,"end":8.915555555555555},{"text":"Each person understood a different part of the problem, so working together was important.","start":8.915555555555555,"end":14.223945578231293},{"text":"At first, I thought we should create a complete system with lots of features.","start":14.223945578231293,"end":18.931836734693878},{"text":"However, a colleague suggested starting with a simple version.","start":18.931836734693878,"end":22.727120181405894},{"text":"I wasn't fully convinced because I worried it would look unfinished, but we discussed the idea and agreed to test it.","start":22.727120181405894,"end":29.506031746031745},{"text":"We divided the work between us and focused on the most common problem.","start":29.506031746031745,"end":33.41183673469388},{"text":"I worked on the main function, while another person tested it with a few examples.","start":33.41183673469388,"end":38.400226757369616},{"text":"Our first attempt didn't work properly because we had misunderstood part of the information.","start":38.400226757369616,"end":43.676961451247166},{"text":"We checked the issue together and corrected it.","start":43.676961451247166,"end":46.43600907029479},{"text":"Eventually, the tool handled the basic task well.","start":46.43600907029479,"end":49.80875283446712},{"text":"It wasn't perfect, but it saved us time and helped us understand what to improve next.","start":49.80875283446712,"end":55.17836734693878},{"text":"Seeing it work was a satisfying moment for me.","start":55.17836734693878,"end":58.39986394557823},{"text":"I was happy with the decision because we learned something useful without spending weeks on an idea that might not work.","start":58.39986394557823,"end":64.65374149659864},{"text":"The experience changed my opinion about planning.","start":64.65374149659864,"end":67.81219954648526},{"text":"I still think planning matters, but now I prefer to try a small, practical solution before making a bigger commitment.","start":67.81219954648526,"end":74.85224489795918}],"sha256":"c170230ed1986b37a0fc88a50b86a65e6db2c9d7709dbfb55d874883b75d3c9b"},"audio/daniel-synced-160/6c6c318f591c5757.m4a":{"duration":66.5087074829932,"segments":[{"text":"A live sporting event I enjoyed was the men's final at the Dubai Duty Free Tennis Championships on the first of March, 2025.","start":0.0,"end":8.597233560090704},{"text":"I went with a friend to the Dubai Duty Free Tennis Stadium.","start":8.597233560090704,"end":12.087936507936508},{"text":"The match was between Stefanos Tsitsipas and Felix Auger-Aliassime, and Tsitsipas won six-three, six-three.","start":12.087936507936508,"end":19.84857142857143},{"text":"We arrived before the match and had time to find our seats and look around.","start":19.84857142857143,"end":24.009795918367345},{"text":"I'd watched tennis at home before, but being there felt different.","start":24.009795918367345,"end":27.904943310657597},{"text":"I could hear the ball striking the rackets, and the players seemed much faster when I saw them with my own eyes.","start":27.904943310657597,"end":34.463310657596374},{"text":"The crowd became quiet before each point, then reacted together when a rally ended.","start":34.463310657596374,"end":39.43492063492064},{"text":"I found myself paying more attention than I normally would in front of a television.","start":39.43492063492064,"end":44.23691609977324},{"text":"Even when I didn't fully understand a tactical decision, the tension was easy to feel.","start":44.23691609977324,"end":49.84716553287982},{"text":"Afterwards, my friend and I discussed the match on our way home.","start":49.84716553287982,"end":53.97047619047619},{"text":"I enjoyed both the sport and the feeling of sharing an evening with so many other spectators.","start":53.97047619047619,"end":58.993696145124716},{"text":"The result was part of the experience, but what I remember most is the atmosphere.","start":58.993696145124716,"end":63.97455782312925},{"text":"It made me want to attend another tennis event.","start":63.97455782312925,"end":66.5087074829932}],"sha256":"c5d27309c0fd3e68d192ee75a7eeb243202196c52eb45f5fdc94da9ba228aef5"},"audio/daniel-synced-160/9124bc438fd5f812.m4a":{"duration":70.46072562358276,"segments":[{"text":"A food that people often eat on a special occasion is birthday cake.","start":0.0,"end":3.8951927437641722},{"text":"In my experience, it is usually brought out near the end of a birthday meal and shared with friends or family.","start":3.8951927437641722,"end":10.170385487528344},{"text":"The style depends on what the person likes.","start":10.170385487528344,"end":12.996780045351475},{"text":"One example I remember is a chocolate cake at a friend's birthday dinner.","start":12.996780045351475,"end":17.030294784580498},{"text":"It had a small decoration connected to his hobby.","start":17.030294784580498,"end":19.950204081632652},{"text":"We had arranged the dinner simply, but the cake made the evening feel more like a celebration.","start":19.950204081632652,"end":25.33315192743764},{"text":"A basic cake is made by preparing a mixture, baking it and then adding some decoration or a topping.","start":25.33315192743764,"end":31.167210884353743},{"text":"I don't think the recipe has to be complicated.","start":31.167210884353743,"end":34.17170068027211},{"text":"The important thing is that everyone can share it and that it suits the person whose birthday it is.","start":34.17170068027211,"end":39.70122448979592},{"text":"When we brought out my friend's cake, we gathered around, sang and took a few photos.","start":39.70122448979592,"end":45.00022675736962},{"text":"He hadn't expected the personal decoration, so his reaction was the most memorable part.","start":45.00022675736962,"end":50.56358276643991},{"text":"Afterwards, we cut the cake and continued talking.","start":50.56358276643991,"end":54.213514739229026},{"text":"I associate this food with making time for other people.","start":54.213514739229026,"end":57.494739229024944},{"text":"It gives a group a small shared moment, rather than just another item to eat.","start":57.494739229024944,"end":62.02843537414966},{"text":"That's why even a simple birthday cake can feel special.","start":62.02843537414966,"end":65.55814058956916},{"text":"If the question required a traditional festival food, I'd choose a different example.","start":65.55814058956916,"end":70.46072562358276}],"sha256":"20f802b261768f372edeb58a56ba169a8cfaa05b467ef552b4df63c208b4cf6a"},"audio/daniel-synced-160/60eaaf8c9ad3c1d2.m4a":{"duration":77.95396825396826,"segments":[{"text":"Someone I know who's good at learning languages is my childhood friend Ben.","start":0.0,"end":4.287573696145125},{"text":"We became friends when we were about ten, and we still practise together through voice messages even though we now live in different cities.","start":4.287573696145125,"end":12.015691609977324},{"text":"One thing I admire about him is the way he learns languages.","start":12.015691609977324,"end":15.735736961451247},{"text":"He studies English by watching short videos with subtitles, noting useful expressions and recording himself using them.","start":15.735736961451247,"end":23.12185941043084},{"text":"He also learns Chinese, and we practise together through voice messages.","start":23.12185941043084,"end":27.663537414965987},{"text":"Rather than memorising long lists, he uses new words in simple conversations.","start":27.663537414965987,"end":32.99791383219954},{"text":"Recently, he managed to order a meal in Chinese and ask the waiter about the ingredients without switching to English.","start":32.99791383219954,"end":39.85578231292517},{"text":"What impresses me most is how confidently Ben uses the languages he learns.","start":39.85578231292517,"end":44.65560090702948},{"text":"When we practise Chinese, he asks me to correct one or two mistakes at a time.","start":44.65560090702948,"end":49.652743764172335},{"text":"The following week, those mistakes have usually disappeared.","start":49.652743764172335,"end":53.24312925170068},{"text":"He also records the same English story twice and compares the recordings, so he can hear whether his speech is becoming clearer.","start":53.24312925170068,"end":60.68993197278912},{"text":"I admire his patience as much as his progress.","start":60.68993197278912,"end":63.750566893424036},{"text":"When I make a mistake, he corrects me gently and adds a funny example, so the conversation doesn't become stressful.","start":63.750566893424036,"end":70.91877551020409},{"text":"He has shown me that improving a language can come from small daily habits, rather than waiting until you feel ready to speak.","start":70.91877551020409,"end":77.95396825396826}],"sha256":"bf75e7f059682883781d3643da4736756cf7aab6c6419b375fa8b52be335e0b2"},"audio/daniel-synced-160/48f780b0dd6b2466.m4a":{"duration":74.36054421768708,"segments":[{"text":"A challenging technical problem I faced was getting a small tool to read information correctly.","start":0.0,"end":5.4044897959183675},{"text":"I was working on it with a team at work.","start":5.4044897959183675,"end":7.78063492063492},{"text":"The aim was to reduce manual checking, but our first attempt produced results we couldn't rely on.","start":7.78063492063492,"end":13.867437641723356},{"text":"At first, I thought the main function was wrong.","start":13.867437641723356,"end":17.066031746031747},{"text":"However, after comparing a few examples, we realised that some of the information was written in a different format.","start":17.066031746031747,"end":24.13532879818594},{"text":"The tool was treating those examples as if they followed the same pattern as the others.","start":24.13532879818594,"end":29.014331065759638},{"text":"We divided the work between us and focused on the most common problem.","start":29.014331065759638,"end":32.92013605442177},{"text":"I worked on the main function, while another person tested it with a few examples.","start":32.92013605442177,"end":37.908526077097505},{"text":"Our first attempt didn't work properly because we had misunderstood part of the information.","start":37.908526077097505,"end":43.185260770975056},{"text":"We checked the issue together and corrected it.","start":43.185260770975056,"end":45.94430839002268},{"text":"Eventually, the tool handled the basic task well.","start":45.94430839002268,"end":49.31705215419501},{"text":"It wasn't perfect, but it saved us time and helped us understand what to improve next.","start":49.31705215419501,"end":54.68666666666667},{"text":"Seeing it work was a satisfying moment for me.","start":54.68666666666667,"end":57.90816326530612},{"text":"I was happy with the decision because we learned something useful without spending weeks on an idea that might not work.","start":57.90816326530612,"end":64.16204081632652},{"text":"The experience changed my opinion about planning.","start":64.16204081632652,"end":67.32049886621316},{"text":"I still think planning matters, but now I prefer to try a small, practical solution before making a bigger commitment.","start":67.32049886621316,"end":74.36054421768708}],"sha256":"efa810e6f157a944ffc4ba9dff8e4efbcabb1ec0d724081adfa6ab200c757433"},"audio/daniel-synced-160/bb437f40e69e2116.m4a":{"duration":71.04253968253968,"segments":[{"text":"I'd like to describe a Xiaomi Mi 11 advertisement featuring Lei Jun, the company's co-founder.","start":0.0,"end":6.147482993197279},{"text":"It was a promotional poster from a campaign announced in early 2021.","start":6.147482993197279,"end":11.052698412698414},{"text":"I saw a picture of the poster online while reading about Xiaomi.","start":11.052698412698414,"end":14.856145124716553},{"text":"What caught my attention was that the founder himself was advertising a product from his own company.","start":14.856145124716553,"end":20.645396825396826},{"text":"Lei Jun isn't a film star or a professional model, so I found that choice interesting.","start":20.645396825396826,"end":26.072471655328798},{"text":"The campaign connected the phone with a person many customers already recognised.","start":26.072471655328798,"end":30.71668934240363},{"text":"Instead of remembering only the product name, I could associate it with the person behind the brand.","start":30.71668934240363,"end":36.553333333333335},{"text":"It also stood out to me for a personal reason.","start":36.553333333333335,"end":39.32231292517007},{"text":"We come from the same part of China, and we both studied at Wuhan University.","start":39.32231292517007,"end":44.08725623582767},{"text":"That doesn't tell me whether a phone is right for me, but it explains why I paid more attention to this poster than to a typical advertisement.","start":44.08725623582767,"end":52.309931972789116},{"text":"I found the advertisement memorable because it gave the company a human face.","start":52.309931972789116,"end":56.90294784580499},{"text":"It didn't make me buy the phone, but it made me more curious about the business.","start":56.90294784580499,"end":61.49469387755102},{"text":"I think a familiar person can help an advertisement attract attention, while the final buying decision should still depend on the product's quality, usefulness and price.","start":61.49469387755102,"end":71.04253968253968}],"sha256":"43e23b3195948300c5d01604aa184788d29abd970aadb6b7e8ce5e58228cd3b7"},"audio/daniel-synced-160/a35ddbff9e8577d8.m4a":{"duration":71.03541950113379,"segments":[{"text":"A home I enjoy visiting but wouldn't want to live in is my grandmother's house.","start":0.0,"end":4.324761904761905},{"text":"I used to go there quite often when I was younger, and I still associate it with spending unhurried time with my family.","start":4.324761904761905,"end":10.996598639455783},{"text":"It isn't a large or modern place, but it feels familiar to me.","start":10.996598639455783,"end":15.045306122448979},{"text":"The room I remember best is the living room.","start":15.045306122448979,"end":17.657777777777778},{"text":"There is a comfortable sofa, a small table and some family photographs.","start":17.657777777777778,"end":22.4902947845805},{"text":"My grandmother also looks after a few plants near the house.","start":22.4902947845805,"end":26.280408163265307},{"text":"When I visit, we usually have something to drink and talk about what has happened since we last saw each other.","start":26.280408163265307,"end":32.63854875283447},{"text":"On my last visit, I helped her with a small job and then stayed for lunch.","start":32.63854875283447,"end":37.27673469387755},{"text":"Nothing especially exciting happened, but I enjoyed having time for an ordinary conversation.","start":37.27673469387755,"end":43.064081632653064},{"text":"I didn't feel that I had to keep checking the time.","start":43.064081632653064,"end":46.33823129251701},{"text":"Although I like visiting, I wouldn't choose to live there permanently.","start":46.33823129251701,"end":50.24498866213152},{"text":"It is too far from the places I need to reach for work, and I'd prefer having my own space and routine.","start":50.24498866213152,"end":56.55501133786848},{"text":"As an adult, I moved into an apartment closer to work, which suited my daily life better.","start":56.55501133786848,"end":62.600680272108846},{"text":"So the house is special because of the person and memories connected with it.","start":62.600680272108846,"end":66.7249433106576},{"text":"Enjoying a visit doesn't necessarily mean that it would be the right place for me to live.","start":66.7249433106576,"end":71.03541950113379}],"sha256":"1004d2848ccceffc961d0afa6ec694259a49c6ac96f5cf1d763c79b39c4d1ef4"},"audio/daniel-synced-160/fd39899183957ff1.m4a":{"duration":67.01528344671202,"segments":[{"text":"A time I waited a long time for a reply was when I contacted a shop about a problem with my headphones.","start":0.0,"end":6.240453514739229},{"text":"One side had stopped working, and I wanted to know what I needed to bring in for a replacement.","start":6.240453514739229,"end":11.936825396825396},{"text":"I sent a short message with the purchase details and a description of the fault.","start":11.936825396825396,"end":16.297551020408164},{"text":"I thought I would hear back fairly quickly, but after several days there was still no reply.","start":16.297551020408164,"end":21.529115646258504},{"text":"I checked that I had used the correct contact information before sending a polite follow-up.","start":21.529115646258504,"end":26.775510204081634},{"text":"The wait was frustrating mainly because I didn't know what to do next.","start":26.775510204081634,"end":30.897278911564626},{"text":"I was unsure whether the message had been received, whether the shop needed more information or whether I should visit in person.","start":30.897278911564626,"end":37.499410430839},{"text":"I didn't want to make an unnecessary trip.","start":37.499410430839,"end":40.32077097505669},{"text":"In the end, I went to the shop with the headphones and the proof of purchase.","start":40.32077097505669,"end":44.56421768707483},{"text":"An assistant checked the problem and explained the process.","start":44.56421768707483,"end":47.84412698412699},{"text":"Once I had that information, I felt much more relaxed.","start":47.84412698412699,"end":51.86866213151927},{"text":"The experience reminded me that even a brief response can be helpful.","start":51.86866213151927,"end":56.06040816326531},{"text":"It doesn't have to solve a problem immediately, but it should let the customer know what is happening.","start":56.06040816326531,"end":61.58095238095238},{"text":"Since then, I've tried to acknowledge messages when I can't give a complete answer straight away.","start":61.58095238095238,"end":67.01528344671202}],"sha256":"be43d6088400e0850a4ce00e5bf7ed61a68ee252778e3a0692835538849d424a"},"audio/daniel-synced-160/4eb44cdcad7830f7.m4a":{"duration":73.66412698412698,"segments":[{"text":"An opinion I changed was my belief that a new idea should be fully developed before anyone tried it.","start":0.0,"end":5.613469387755102},{"text":"I changed my mind during a small project at work.","start":5.613469387755102,"end":8.918412698412698},{"text":"We wanted to build a tool that would make a repeated manual task easier.","start":8.918412698412698,"end":13.035827664399093},{"text":"At first, I thought we should create a complete system with lots of features.","start":13.035827664399093,"end":17.743718820861677},{"text":"However, a colleague suggested starting with a simple version.","start":17.743718820861677,"end":21.539002267573697},{"text":"I wasn't fully convinced because I worried it would look unfinished, but we discussed the idea and agreed to test it.","start":21.539002267573697,"end":28.317913832199547},{"text":"We divided the work between us and focused on the most common problem.","start":28.317913832199547,"end":32.22371882086168},{"text":"I worked on the main function, while another person tested it with a few examples.","start":32.22371882086168,"end":37.212108843537415},{"text":"Our first attempt didn't work properly because we had misunderstood part of the information.","start":37.212108843537415,"end":42.488843537414965},{"text":"We checked the issue together and corrected it.","start":42.488843537414965,"end":45.247891156462586},{"text":"Eventually, the tool handled the basic task well.","start":45.247891156462586,"end":48.62063492063492},{"text":"It wasn't perfect, but it saved us time and helped us understand what to improve next.","start":48.62063492063492,"end":53.99024943310658},{"text":"Seeing it work was a satisfying moment for me.","start":53.99024943310658,"end":57.21174603174603},{"text":"I was happy with the decision because we learned something useful without spending weeks on an idea that might not work.","start":57.21174603174603,"end":63.46562358276644},{"text":"The experience changed my opinion about planning.","start":63.46562358276644,"end":66.62408163265306},{"text":"I still think planning matters, but now I prefer to try a small, practical solution before making a bigger commitment.","start":66.62408163265306,"end":73.66412698412698}],"sha256":"d475251b14498ac3001d35026d107fd79ff0032b9016c732e2bd205d0454dd55"},"audio/daniel-synced-160/4614a5ea7297214c.m4a":{"duration":72.29836734693878,"segments":[{"text":"A person I know about who overcame difficulties and became successful is Lei Jun, the co-founder of Xiaomi.","start":0.0,"end":6.75124716553288},{"text":"We come from the same part of China, and we both studied at Wuhan University.","start":6.75124716553288,"end":11.516190476190475},{"text":"That gives me a personal reason to pay attention to him, beyond simply recognising his name.","start":11.516190476190475,"end":17.39374149659864},{"text":"One difficulty he described was an early business he started with others while he was at university.","start":17.39374149659864,"end":22.831746031746032},{"text":"It eventually closed.","start":22.831746031746032,"end":24.370068027210884},{"text":"In his public account, he explained that the team lacked business experience and hadn't clearly agreed who was responsible or what the company should focus on.","start":24.370068027210884,"end":33.62004535147392},{"text":"What interests me is what happened afterwards.","start":33.62004535147392,"end":36.341632653061225},{"text":"He treated that experience as a lesson about running a business, rather than a reason to stop trying.","start":36.341632653061225,"end":42.21845804988662},{"text":"He later worked at Kingsoft and co-founded Xiaomi in 2010.","start":42.21845804988662,"end":46.620816326530615},{"text":"His career reminds me that being good at technology and being good at managing a company are different skills.","start":46.620816326530615,"end":52.70925170068027},{"text":"I admire his willingness to learn from a disappointing experience.","start":52.70925170068027,"end":56.4897052154195},{"text":"Because we're from the same home region and share a university background, the story feels quite personal to me.","start":56.4897052154195,"end":63.13578231292517},{"text":"When an unfamiliar task doesn't go well, it helps to ask what I can improve instead of assuming I can't do it.","start":63.13578231292517,"end":69.85111111111111},{"text":"That's the lesson I take from his success.","start":69.85111111111111,"end":72.29836734693878}],"sha256":"48a0bf8f0792e682ad46c0c45e8df28fb223338e198b0ed6a80e832d8a5f0470"},"audio/daniel-synced-160/90497dd34f101634.m4a":{"duration":72.20167800453515,"segments":[{"text":"A problem I had with an electronic device was when one side of my headphones stopped working.","start":0.0,"end":5.218730158730159},{"text":"I had bought them a few weeks earlier and was using them regularly for work and English recordings.","start":5.218730158730159,"end":10.532108843537415},{"text":"At first, I thought the recording or connection might be the problem.","start":10.532108843537415,"end":14.627301587301588},{"text":"I tried a different recording and connected the headphones again.","start":14.627301587301588,"end":18.118004535147392},{"text":"The same side still wasn't working, so I decided to stop guessing and contact the shop.","start":18.118004535147392,"end":23.61206349206349},{"text":"I found the proof of purchase and explained when the fault had started.","start":23.61206349206349,"end":27.836190476190477},{"text":"The shop assistant checked the headphones and confirmed that they weren't working properly.","start":27.836190476190477,"end":32.37591836734694},{"text":"He explained the replacement process clearly.","start":32.37591836734694,"end":35.10643990929705},{"text":"I was relieved that I didn't have to understand the internal parts of the device in order to get help.","start":35.10643990929705,"end":40.736009070294784},{"text":"A few weeks later, one side stopped working properly.","start":40.736009070294784,"end":44.29451247165533},{"text":"I took them back to the shop, expecting a long argument.","start":44.29451247165533,"end":47.80843537414966},{"text":"Instead, the assistant listened carefully, checked the problem and explained the next steps.","start":47.80843537414966,"end":53.387074829931976},{"text":"After confirming the fault, the shop arranged a replacement.","start":53.387074829931976,"end":57.3702947845805},{"text":"That experience made the purchase more memorable.","start":57.3702947845805,"end":60.24984126984127},{"text":"I appreciated both the product and the way the problem was handled.","start":60.24984126984127,"end":63.86775510204082},{"text":"For me, the value wasn't just the price or the brand.","start":63.86775510204082,"end":67.27587301587302},{"text":"It was having something useful and knowing that I could get help when it didn't work as expected.","start":67.27587301587302,"end":72.20167800453515}],"sha256":"8e75c1b7f6afdcccf4d51196b282968294f2ef858349a8b896b431c9f158510b"},"audio/daniel-synced-160/6a56547966ce241e.m4a":{"duration":68.97287981859411,"segments":[{"text":"I'd like to describe my colleague Adam, who helped solve a problem in a simple but clever way.","start":0.0,"end":5.508934240362811},{"text":"We met at work about two years ago.","start":5.508934240362811,"end":7.893832199546485},{"text":"I often ask him for advice because he can identify what is actually making a task difficult.","start":7.893832199546485,"end":13.662222222222223},{"text":"The problem was that I had too much information in a presentation.","start":13.662222222222223,"end":17.377823129251702},{"text":"My first reaction was to add even more explanation.","start":17.377823129251702,"end":20.703537414965986},{"text":"Adam suggested doing the opposite: remove the unnecessary details and show one example that people could easily understand.","start":20.703537414965986,"end":28.154013605442177},{"text":"A few months ago, I had to explain a new idea to our team.","start":28.154013605442177,"end":32.20013605442177},{"text":"I knew the details, but I couldn't present them clearly.","start":32.20013605442177,"end":35.72702947845805},{"text":"Adam suggested using one simple example instead of showing everything at once.","start":35.72702947845805,"end":40.64390022675737},{"text":"He also helped me practise and pointed out the parts that were difficult to follow.","start":40.64390022675737,"end":45.22303854875283},{"text":"The presentation went much better than I expected.","start":45.22303854875283,"end":48.218820861678005},{"text":"People understood the idea, and I felt more confident afterwards.","start":48.218820861678005,"end":52.45909297052154},{"text":"What I appreciate most is that he helped me learn a useful skill rather than just doing the work for me.","start":52.45909297052154,"end":58.55024943310658},{"text":"Since then, I've tried to follow his approach.","start":58.55024943310658,"end":61.6768253968254},{"text":"Whenever a task feels overwhelming, I break it into smaller steps.","start":61.6768253968254,"end":66.03537414965986},{"text":"So he's had a positive influence on the way I work.","start":66.03537414965986,"end":68.97287981859411}],"sha256":"5d853d8e9d3191067204362386cef5ea4b38df3b136e0f27be96bee3449a7955"},"audio/daniel-synced-160/5d02ea0e267f8567.m4a":{"duration":64.00671201814059,"segments":[{"text":"A city I'd like to visit again is Hangzhou, in eastern China.","start":0.0,"end":3.9068027210884355},{"text":"I went there with a friend during a short holiday last year, but the trip felt too short.","start":3.9068027210884355,"end":8.988027210884354},{"text":"What I enjoyed most was being able to slow down and spend time outdoors.","start":8.988027210884354,"end":13.535056689342404},{"text":"We spent an afternoon walking beside West Lake.","start":13.535056689342404,"end":16.372743764172334},{"text":"There were trees along the path, and we stopped several times to look at the water.","start":16.372743764172334,"end":20.97315192743764},{"text":"We also sat down for a while and talked, without feeling that we had to move straight to another attraction.","start":20.97315192743764,"end":27.0178231292517},{"text":"Away from the lake, we walked through some nearby streets and found a place to eat.","start":27.0178231292517,"end":31.539954648526077},{"text":"I enjoyed noticing ordinary parts of the city as well as the view by the water.","start":31.539954648526077,"end":36.087165532879816},{"text":"However, we didn't have much time to explore further.","start":36.087165532879816,"end":39.69931972789116},{"text":"On a second visit, I'd stay for a few days.","start":39.69931972789116,"end":42.81659863945578},{"text":"I'd leave one morning for the lake and spend another afternoon looking around a different neighbourhood.","start":42.81659863945578,"end":47.7566439909297},{"text":"I'd also allow time for a meal with anyone I knew in the area.","start":47.7566439909297,"end":51.654421768707486},{"text":"I'd like to return because I already know one part I enjoy, but still feel curious about the rest.","start":51.654421768707486,"end":57.83673469387755},{"text":"I prefer that kind of trip to a packed schedule where I spend most of the day checking what I need to do next.","start":57.83673469387755,"end":64.00671201814059}],"sha256":"b9460ea63f0e93ca434a8d733a8f6393ab3421fc53119a68fa463a58325a2f6f"},"audio/daniel-synced-160/0af724a19d1a4d06.m4a":{"duration":70.56358276643991,"segments":[{"text":"A person I only met once but would like to know better is a man called Adam.","start":0.0,"end":4.278321995464853},{"text":"I met him at a small photography workshop last month.","start":4.278321995464853,"end":7.735646258503401},{"text":"We spoke for about twenty minutes while practising how to take pictures of the street outside.","start":7.735646258503401,"end":13.234648526077098},{"text":"I noticed him because he was using a basic phone but still taking interesting photos.","start":13.234648526077098,"end":18.292698412698414},{"text":"He didn't seem concerned about having the most expensive equipment.","start":18.292698412698414,"end":22.277097505668934},{"text":"Instead, he paid attention to the light, the background and the position of the people in the picture.","start":22.277097505668934,"end":28.044126984126983},{"text":"When I asked how he made an ordinary scene look so good, he showed me a simple example.","start":28.044126984126983,"end":33.366303854875284},{"text":"He moved a little to one side, waited for a person to walk past and then took the photo.","start":33.366303854875284,"end":38.62780045351474},{"text":"That small change made the picture much more balanced.","start":38.62780045351474,"end":41.846666666666664},{"text":"He explained the idea patiently and asked me to try it myself.","start":41.846666666666664,"end":45.92394557823129},{"text":"I liked the fact that he was willing to share what he knew without making me feel inexperienced.","start":45.92394557823129,"end":51.016780045351474},{"text":"Before we left, he mentioned that he enjoyed photographing different cities.","start":51.016780045351474,"end":55.76136054421769},{"text":"I'd like to know more about his travels and see some of those photographs.","start":55.76136054421769,"end":59.981587301587304},{"text":"He seemed observant, friendly and easy to talk to.","start":59.981587301587304,"end":63.39709750566893},{"text":"Although our conversation was short, I came away with a useful idea and the feeling that we could have an interesting conversation again.","start":63.39709750566893,"end":70.56358276643991}],"sha256":"43394876c0ae392a265603a71422189afaab913f1b0c5f48c168d4dcc89a75f2"},"audio/daniel-synced-160/16e0f3649250bd70.m4a":{"duration":68.81238095238095,"segments":[{"text":"A gift I'd like to buy for a friend is a pair of comfortable headphones.","start":0.0,"end":4.2667120181405895},{"text":"My friend Sam enjoys listening to music and is also trying to improve his English.","start":4.2667120181405895,"end":9.043673469387755},{"text":"We've known each other for a few years, so I have a fairly good idea of what he would use.","start":9.043673469387755,"end":14.438185941043084},{"text":"He sometimes listens through his phone's speaker, which isn't very convenient when other people are nearby.","start":14.438185941043084,"end":20.1524716553288},{"text":"I think headphones would let him enjoy recordings and practise listening without disturbing anyone.","start":20.1524716553288,"end":25.453696145124717},{"text":"They could also be useful when he wants to concentrate.","start":25.453696145124717,"end":28.88126984126984},{"text":"I wouldn't choose the most expensive pair automatically.","start":28.88126984126984,"end":32.26748299319728},{"text":"I'd compare comfort, sound quality and how easy they are to use.","start":32.26748299319728,"end":36.42965986394558},{"text":"If possible, I'd ask him about his preferences without immediately revealing that I was thinking about a gift.","start":36.42965986394558,"end":42.75392290249433},{"text":"I'd probably give them to him on his birthday.","start":42.75392290249433,"end":45.27909297052154},{"text":"I would include a short note explaining why I chose them, because I think that personal detail matters.","start":45.27909297052154,"end":51.35877551020408},{"text":"I might also suggest an English podcast we could both listen to and discuss afterwards.","start":51.35877551020408,"end":56.60517006802721},{"text":"I'd choose this gift because it connects with his actual interests.","start":56.60517006802721,"end":60.33777777777778},{"text":"A useful present can show that someone has paid attention to you.","start":60.33777777777778,"end":64.1865306122449},{"text":"I hope he would enjoy it regularly, rather than put it away after the first day.","start":64.1865306122449,"end":68.81238095238095}],"sha256":"989079c511c6d6794329b5515a20fa6008ecbb1bbf2eb98dbbe17ff908442021"},"audio/daniel-synced-160/3cfefd8546d1f41f.m4a":{"duration":67.13573696145124,"segments":[{"text":"A city I'd like to visit in the future is Suzhou, in eastern China.","start":0.0,"end":4.104172335600907},{"text":"I haven't been there yet, but photographs of its canals have made me curious about it.","start":4.104172335600907,"end":9.185442176870747},{"text":"I'd like to go with a friend who enjoys walking and a slower kind of holiday.","start":9.185442176870747,"end":13.663718820861678},{"text":"The place I'd most like to see is one of the canals.","start":13.663718820861678,"end":16.82204081632653},{"text":"I'd spend a morning exploring the paths beside the water, stopping when we found somewhere pleasant to sit.","start":16.82204081632653,"end":22.841814058956917},{"text":"I wouldn't want the whole visit to become a list of photographs I needed to take.","start":22.841814058956917,"end":27.438095238095237},{"text":"I'd also leave time to explore another part of the city.","start":27.438095238095237,"end":30.799183673469386},{"text":"We could look around some streets, find somewhere to eat and choose one other activity according to what interested us.","start":30.799183673469386,"end":37.43333333333333},{"text":"I'd rather make a realistic plan than try to see everything in a day.","start":37.43333333333333,"end":41.64458049886621},{"text":"Before booking, I'd check the weather, transport and accommodation costs.","start":41.64458049886621,"end":46.31687074829932},{"text":"I would also look for recent practical information so that I understood how to get between the places we wanted to visit.","start":46.31687074829932,"end":53.409297052154194},{"text":"What attracts me is the possibility of combining a city visit with time by the water.","start":53.409297052154194,"end":58.19750566893424},{"text":"I spend a lot of time indoors, so that balance sounds appealing.","start":58.19750566893424,"end":62.29120181405896},{"text":"I'd hope to come home with a clearer impression of the place and a few memories shared with a friend.","start":62.29120181405896,"end":67.13573696145124}],"sha256":"681c6302341050b9139d9f3882d3876b829e00cd7abf709aba3a8bb59107058d"},"audio/daniel-synced-160/aed6f20b51ceae42.m4a":{"duration":68.5275283446712,"segments":[{"text":"A special cake I received was one my friends gave me on my birthday a few months ago.","start":0.0,"end":5.218730158730159},{"text":"I hadn't planned a large celebration, so I was surprised when they invited me to a simple dinner and brought out the cake afterwards.","start":5.218730158730159,"end":13.112199546485261},{"text":"It was a chocolate cake with a small decoration connected to one of my hobbies.","start":13.112199546485261,"end":17.587845804988664},{"text":"It wasn't especially large or expensive, but the detail showed that they had thought about me.","start":17.587845804988664,"end":23.061950113378686},{"text":"They had arranged it without telling me, which made the surprise work.","start":23.061950113378686,"end":27.36281179138322},{"text":"We sat together, talked about things that had happened that week and took a few photos.","start":27.36281179138322,"end":32.42965986394558},{"text":"When the cake arrived, everyone smiled and sang.","start":32.42965986394558,"end":35.731746031746034},{"text":"I felt slightly embarrassed by the attention at first, but it was a very warm moment.","start":35.731746031746034,"end":41.16331065759637},{"text":"We shared the cake after the meal.","start":41.16331065759637,"end":43.21156462585034},{"text":"What I remember most isn't the exact taste, although I enjoyed it.","start":43.21156462585034,"end":47.24503401360544},{"text":"It's the feeling of spending time with people who had made an effort to celebrate with me.","start":47.24503401360544,"end":51.92965986394558},{"text":"I also kept a photo of the cake as a reminder.","start":51.92965986394558,"end":55.155147392290246},{"text":"The cake was special because it felt personal.","start":55.155147392290246,"end":57.91859410430839},{"text":"A simple gift can mean a lot when it reflects something about the person receiving it.","start":57.91859410430839,"end":62.661315192743764},{"text":"I'd like to do something similar for a friend rather than assume that a more expensive present is always better.","start":62.661315192743764,"end":68.5275283446712}],"sha256":"bf785dbb3d79c5f35ea0dae3784170df4c1cb03f6e266be3386b6de496652a23"},"audio/daniel-synced-160/77f601f6522a017f.m4a":{"duration":70.76308390022676,"segments":[{"text":"One thing I did to improve my English was start recording myself answering a short question each day.","start":0.0,"end":5.995600907029479},{"text":"I began a few months ago because I realised that reading and listening alone weren't giving me enough practice in expressing my own ideas.","start":5.995600907029479,"end":13.773015873015874},{"text":"I usually chose a topic connected with my daily life, such as a recent outing or something I had learned at work.","start":13.773015873015874,"end":20.59578231292517},{"text":"That meant I could concentrate on explaining my meaning instead of trying to invent an interesting story at the same time.","start":20.59578231292517,"end":27.564671201814058},{"text":"After recording, I listened back and noticed the places where I hesitated.","start":27.564671201814058,"end":32.280090702947845},{"text":"Sometimes the problem was a word I couldn't remember.","start":32.280090702947845,"end":35.22090702947846},{"text":"More often, I was trying to make a sentence too complicated.","start":35.22090702947846,"end":39.196780045351474},{"text":"I then answered the same question again using simpler language.","start":39.196780045351474,"end":43.23578231292517},{"text":"Occasionally, I asked a friend whether my example was clear.","start":43.23578231292517,"end":47.03809523809524},{"text":"I found that more useful than only asking whether the answer sounded good.","start":47.03809523809524,"end":50.98095238095238},{"text":"If the meaning was difficult to follow, I changed the order or added one concrete detail.","start":50.98095238095238,"end":56.457687074829934},{"text":"The routine didn't solve everything, but it made speaking feel less unfamiliar.","start":56.457687074829934,"end":61.32489795918367},{"text":"I could notice small improvements, and it was easy enough to continue on a busy day.","start":61.32489795918367,"end":66.19718820861678},{"text":"I'd keep using it because it gives me practice and a clear way to check my progress.","start":66.19718820861678,"end":70.76308390022676}],"sha256":"623a751ad925be4d83b32bb5a8f179dd43dda3cdcd1191075ce7f02c90bce71b"},"audio/daniel-synced-160/abd5cffe22694b1b.m4a":{"duration":70.28285714285714,"segments":[{"text":"An important lake in China that I'd like to describe is West Lake in Hangzhou, in Zhejiang Province.","start":0.0,"end":6.019818594104309},{"text":"I visited it with a friend during a short holiday last year.","start":6.019818594104309,"end":9.521814058956917},{"text":"We had a busy few weeks before the trip, so we wanted somewhere we could explore without rushing.","start":9.521814058956917,"end":15.09047619047619},{"text":"We spent an afternoon walking along the paths beside the lake.","start":15.09047619047619,"end":18.49705215419501},{"text":"What I remember most is the space around the water.","start":18.49705215419501,"end":21.323174603174603},{"text":"There were trees beside the path, and we could stop whenever we noticed a view we liked.","start":21.323174603174603,"end":26.028072562358275},{"text":"I took a few photos, but I also put my phone away for part of the walk.","start":26.028072562358275,"end":31.135192743764172},{"text":"At one point, we sat down and watched the light change on the water.","start":31.135192743764172,"end":35.19292517006803},{"text":"We talked about ordinary things and didn't feel that we had to keep moving to another attraction.","start":35.19292517006803,"end":40.32938775510204},{"text":"Afterwards, we found somewhere nearby to have a simple meal.","start":40.32938775510204,"end":44.33922902494331},{"text":"For me, the lake is important because it gives people a place to enjoy being outdoors while visiting a city.","start":44.33922902494331,"end":50.475691609977325},{"text":"I liked the balance between walking, looking around and having time to talk.","start":50.475691609977325,"end":55.37378684807256},{"text":"I'd happily go back, especially with someone who enjoys walking and spending time outdoors.","start":55.37378684807256,"end":60.998820861678006},{"text":"I'd leave enough time to enjoy the lake properly instead of trying to fit several activities into one afternoon.","start":60.998820861678006,"end":67.30884353741497},{"text":"To me, that is what makes a place worth visiting.","start":67.30884353741497,"end":70.28285714285714}],"sha256":"9ba37e0cfc98c35978859f93666d2715b797a2464e440a7d8bdc7957d3dd65b6"},"audio/daniel-synced-160/bb017ab71855aac4.m4a":{"duration":73.89609977324263,"segments":[{"text":"A day out that cost me very little was an afternoon exploring an older part of Dubai with a friend.","start":0.0,"end":5.462539682539682},{"text":"We chose it because we wanted to do something enjoyable without spending much.","start":5.462539682539682,"end":9.763083900226757},{"text":"Most of the plan involved walking around, looking at the shops and taking photos.","start":9.763083900226757,"end":14.948979591836734},{"text":"We started near the creek and spent some time looking at the old buildings and small shops.","start":14.948979591836734,"end":19.934512471655328},{"text":"What I liked was the atmosphere.","start":19.934512471655328,"end":21.959501133786848},{"text":"It felt different from the modern shopping malls I normally see.","start":21.959501133786848,"end":25.506349206349206},{"text":"There were narrow streets, people selling different products, and plenty of small details to notice.","start":25.506349206349206,"end":31.88580498866213},{"text":"At one point, we walked through a busy market.","start":31.88580498866213,"end":34.96829931972789},{"text":"It was quite crowded, and I could hear people talking and calling out to customers.","start":34.96829931972789,"end":39.81546485260771},{"text":"Later, we moved to a quieter spot by the water and took a few photos.","start":39.81546485260771,"end":44.40698412698413},{"text":"The light was softer by then, which made the area look especially nice.","start":44.40698412698413,"end":49.021632653061225},{"text":"We only spent money on transport and a simple drink.","start":49.021632653061225,"end":52.300498866213154},{"text":"We didn't book an expensive activity or buy things just because they were available.","start":52.300498866213154,"end":56.96095238095238},{"text":"Sitting by the water and talking was one of the best parts, and that didn't require a large budget.","start":56.96095238095238,"end":62.92190476190476},{"text":"I remember feeling relaxed afterwards.","start":62.92190476190476,"end":65.53024943310658},{"text":"It reminded me that I don't always need a complicated plan to have a good day.","start":65.53024943310658,"end":70.07555555555555},{"text":"Sometimes a walk, a friend and a change of surroundings are enough.","start":70.07555555555555,"end":73.89609977324263}],"sha256":"2fc3f4b7d39c03ab470cf27b0b300b56c2776bb60ca60c73c8af1d7b6ddf3bde"},"audio/daniel-synced-160/a38278abe838a09b.m4a":{"duration":71.2669387755102,"segments":[{"text":"A course that impressed me was a short course on giving presentations.","start":0.0,"end":4.046122448979592},{"text":"I took it a while ago because I often needed to explain ideas at work, but I found it difficult to decide what to include and what to leave out.","start":4.046122448979592,"end":12.26204081632653},{"text":"It was held in a training room at my workplace in Dubai.","start":12.26204081632653,"end":15.765079365079366},{"text":"The teacher asked us to begin with one main message and support it with a simple example.","start":15.765079365079366,"end":20.687891156462584},{"text":"That sounded easy, but during the first exercise I realised that I was adding details which didn't help the audience understand my point.","start":20.687891156462584,"end":29.017233560090702},{"text":"We practised in small groups and gave each other feedback.","start":29.017233560090702,"end":32.400589569161},{"text":"I tried again with fewer slides and a clearer order.","start":32.400589569161,"end":35.39206349206349},{"text":"The teacher also asked us to explain our ideas without reading whole sentences from the screen, which made the exercise feel more practical.","start":35.39206349206349,"end":43.93981859410431},{"text":"After the course, I used the method in a team presentation.","start":43.93981859410431,"end":47.79609977324263},{"text":"I began with the problem and one example before explaining the details.","start":47.79609977324263,"end":52.04145124716553},{"text":"People understood the idea more quickly, and their questions helped us have a useful discussion.","start":52.04145124716553,"end":57.72399092970522},{"text":"What impressed me most was the chance to practise rather than simply listen to advice.","start":57.72399092970522,"end":62.66312925170068},{"text":"I left with a method I could use straight away.","start":62.66312925170068,"end":65.37732426303855},{"text":"I still need preparation before a presentation, but I now have a clearer way to organise my thoughts.","start":65.37732426303855,"end":71.2669387755102}],"sha256":"c2e667e289772ce6399fa12d7704a56c491c3a068d26e88f71c86b3ee5572db6"},"audio/daniel-synced-160/66b53fd32e664ed4.m4a":{"duration":66.00947845804988,"segments":[{"text":"A café close to nature that I'd like to describe is a small beachside cafe, near Sunset Beach in Dubai.","start":0.0,"end":6.553877551020408},{"text":"I went there with a friend one evening after we had spent some time walking beside the sea.","start":6.553877551020408,"end":11.414557823129252},{"text":"We wanted somewhere to sit and have a drink.","start":11.414557823129252,"end":14.069115646258503},{"text":"We chose a table where we could see the water.","start":14.069115646258503,"end":16.674603174603174},{"text":"The view was the main reason I liked the place.","start":16.674603174603174,"end":19.35655328798186},{"text":"I could notice the light changing outside while sitting comfortably, which felt different from spending another evening inside a shopping centre.","start":19.35655328798186,"end":27.389387755102042},{"text":"I ordered a cold drink, and we stayed for about half an hour.","start":27.389387755102042,"end":31.16984126984127},{"text":"We talked about our week and a few things we hoped to do at the weekend.","start":31.16984126984127,"end":35.122086167800454},{"text":"The conversation felt relaxed because neither of us was trying to get to another activity immediately.","start":35.122086167800454,"end":41.08086167800454},{"text":"I remember putting my phone away for most of the visit.","start":41.08086167800454,"end":44.30453514739229},{"text":"There was enough to look at outside, and I didn't feel that I needed something else to keep me interested.","start":44.30453514739229,"end":50.053877551020406},{"text":"The drink was pleasant, but it wasn't the most memorable part.","start":50.053877551020406,"end":53.86748299319728},{"text":"I'd go back for the setting and the chance to spend quiet time with a friend.","start":53.86748299319728,"end":58.029659863945575},{"text":"For me, a café near nature can turn an ordinary break into something more refreshing, as long as it is comfortable and doesn't feel rushed.","start":58.029659863945575,"end":66.00947845804988}],"sha256":"0905d70741c4007acb05326f8ad794e790f6312a2531121ddd2a0622f7e65ef8"},"audio/daniel-synced-160/71d91c81a85aba37.m4a":{"duration":70.19056689342403,"segments":[{"text":"One time I was stuck in traffic was on the way to the supermarket on a Saturday.","start":0.0,"end":4.555963718820862},{"text":"I had left home at a busy hour and expected a quick journey, because the distance wasn't very long.","start":4.555963718820862,"end":10.577551020408164},{"text":"I also had several other things planned for that afternoon.","start":10.577551020408164,"end":14.20938775510204},{"text":"After a few minutes, the cars began moving very slowly.","start":14.20938775510204,"end":17.96938775510204},{"text":"I spent about half an hour on a journey that was usually much shorter.","start":17.96938775510204,"end":21.946984126984127},{"text":"I couldn't see a clear reason for the delay, so I didn't know when the traffic would improve.","start":21.946984126984127,"end":27.251428571428573},{"text":"I was driving, which meant I needed to keep paying attention to the road.","start":27.251428571428573,"end":31.509750566893423},{"text":"I tried to stay patient, but I kept thinking about the time I was losing.","start":31.509750566893423,"end":36.2659410430839},{"text":"I was especially annoyed because I had assumed that buying a few groceries would be a simple errand.","start":36.2659410430839,"end":41.81641723356009},{"text":"When I reached the supermarket, I decided to change my plan for the rest of the afternoon.","start":41.81641723356009,"end":47.3940589569161},{"text":"I bought the things I needed most and left the less urgent tasks for another day.","start":47.3940589569161,"end":51.964399092970524},{"text":"That helped me stop feeling that everything had to happen at once.","start":51.964399092970524,"end":56.03079365079365},{"text":"The experience wasn't dangerous or dramatic, but it was frustrating.","start":56.03079365079365,"end":60.570839002267576},{"text":"Since then, I've tried to go shopping at a quieter time and leave a little more room in my schedule.","start":60.570839002267576,"end":66.27482993197279},{"text":"It reminded me that a short distance doesn't always mean a short journey.","start":66.27482993197279,"end":70.19056689342403}],"sha256":"10990ee5ea747a4113bc7eb2b11d83825c00a4473ab05351469971923d007c15"},"audio/daniel-synced-160/8b4801236fde1183.m4a":{"duration":74.75573696145125,"segments":[{"text":"Something I waited for was a package containing replacement headphones.","start":0.0,"end":4.2411337868480725},{"text":"My original pair had developed a fault, and the shop had agreed to send another pair after checking the problem.","start":4.2411337868480725,"end":10.515736961451248},{"text":"I used the headphones for listening practice and work, so I wanted them back quite quickly.","start":10.515736961451248,"end":16.017596371882085},{"text":"I expected the package by the end of that week, but it took about ten days to arrive.","start":16.017596371882085,"end":21.063990929705216},{"text":"During the wait, I used an older pair which wasn't as comfortable.","start":21.063990929705216,"end":25.05142857142857},{"text":"That wasn't a serious problem, but it reminded me of the replacement whenever I needed to listen to something.","start":25.05142857142857,"end":31.381678004535146},{"text":"At first, I checked the tracking information several times a day.","start":31.381678004535146,"end":35.601950113378685},{"text":"However, seeing the same update didn't make the delivery any faster.","start":35.601950113378685,"end":39.79197278911565},{"text":"I eventually contacted the shop once, asked for a clearer estimate and then tried to stop checking so often.","start":39.79197278911565,"end":46.62893424036281},{"text":"When the package arrived, I opened it and tested both sides of the headphones.","start":46.62893424036281,"end":51.312607709750566},{"text":"I was pleased that they worked properly, and I could finally return to my usual listening routine.","start":51.312607709750566,"end":56.881451247165536},{"text":"I also felt relieved that I didn't need another conversation about the fault.","start":56.881451247165536,"end":61.56979591836735},{"text":"What made the wait frustrating was not knowing exactly when it would end.","start":61.56979591836735,"end":65.5104761904762},{"text":"The experience taught me that a useful update can matter almost as much as a quick delivery.","start":65.5104761904762,"end":70.92126984126985},{"text":"It helped me manage my expectations and spend less time checking.","start":70.92126984126985,"end":74.75573696145125}],"sha256":"a3ce9a9bded28c40549446ccea7221ca4719add8ff644f5ffb2658a1d0082c59"},"audio/daniel-synced-160/6dae6b490a62bf7c.m4a":{"duration":73.02757369614513,"segments":[{"text":"A time I helped someone solve a problem was when a colleague had to check the same information repeatedly.","start":0.0,"end":5.868888888888889},{"text":"It was taking up too much of his day.","start":5.868888888888889,"end":8.16185941043084},{"text":"I asked which part was most difficult and suggested building a simple tool to handle the repeated steps.","start":8.16185941043084,"end":14.278231292517006},{"text":"At first, I thought we should create a complete system with lots of features.","start":14.278231292517006,"end":18.986122448979593},{"text":"However, a colleague suggested starting with a simple version.","start":18.986122448979593,"end":22.78140589569161},{"text":"I wasn't fully convinced because I worried it would look unfinished, but we discussed the idea and agreed to test it.","start":22.78140589569161,"end":29.56031746031746},{"text":"We divided the work between us and focused on the most common problem.","start":29.56031746031746,"end":33.46612244897959},{"text":"I worked on the main function, while another person tested it with a few examples.","start":33.46612244897959,"end":38.45451247165533},{"text":"Our first attempt didn't work properly because we had misunderstood part of the information.","start":38.45451247165533,"end":43.73124716553288},{"text":"We checked the issue together and corrected it.","start":43.73124716553288,"end":46.4902947845805},{"text":"Eventually, the tool handled the basic task well.","start":46.4902947845805,"end":49.86303854875283},{"text":"It wasn't perfect, but it saved us time and helped us understand what to improve next.","start":49.86303854875283,"end":55.23265306122449},{"text":"Seeing it work was a satisfying moment for me.","start":55.23265306122449,"end":58.454149659863944},{"text":"I was pleased that I could help with a problem that affected his everyday work.","start":58.454149659863944,"end":62.59501133786848},{"text":"The tool didn't remove the need for all checks, but it made the process easier.","start":62.59501133786848,"end":67.05578231292517},{"text":"I also learned that asking careful questions is useful before deciding what kind of help someone needs.","start":67.05578231292517,"end":73.02757369614513}],"sha256":"a2864f07ee80b0c23301f07eaa0faf9a83ce9f0c7e1559145268f32328466c5e"},"audio/daniel-synced-160/47a22e37626c06a1.m4a":{"duration":70.24843537414966,"segments":[{"text":"One time I lost something was during a visit to a market in the older part of Dubai.","start":0.0,"end":4.730113378684807},{"text":"I was there with a friend, looking around the small shops and taking a few photographs.","start":4.730113378684807,"end":9.869433106575963},{"text":"The item I lost was my set of keys.","start":9.869433106575963,"end":12.554512471655329},{"text":"I noticed they were missing when we were about to leave.","start":12.554512471655329,"end":15.278956916099773},{"text":"At first, I thought they must be in another pocket, so I checked my clothes and bag carefully.","start":15.278956916099773,"end":20.99691609977324},{"text":"When I still couldn't find them, I began feeling worried because I needed them to get into my home.","start":20.99691609977324,"end":27.064807256235827},{"text":"My friend helped me think through where we had been.","start":27.064807256235827,"end":29.833242630385488},{"text":"I remembered taking the keys out while looking for my wallet in one shop.","start":29.833242630385488,"end":33.76512471655329},{"text":"We walked back along the same route and asked a member of staff whether anyone had found them.","start":33.76512471655329,"end":38.962267573696145},{"text":"Fortunately, someone had noticed the keys on the counter and kept them safely.","start":38.962267573696145,"end":43.4849433106576},{"text":"I described the key ring before the staff member returned them to me.","start":43.4849433106576,"end":47.27886621315193},{"text":"I felt relieved and thanked him, because a small mistake could have caused a much more inconvenient evening.","start":47.27886621315193,"end":53.604399092970525},{"text":"Afterwards, I put the keys in one specific pocket instead of moving them between my bag and clothes.","start":53.604399092970525,"end":60.14258503401361},{"text":"I also tried to check them before leaving a place.","start":60.14258503401361,"end":63.21487528344671},{"text":"The experience was stressful at the time, but it reminded me that a simple habit can help me avoid the same problem again.","start":63.21487528344671,"end":70.24843537414966}],"sha256":"e6fc628684e7690a90ea03cdf2dc9966fb7dfb55e9e19b7fe46c748131c93f9b"},"audio/daniel-synced-160/05cf9f9245e9b0d8.m4a":{"duration":76.09959183673469,"segments":[{"text":"A change that helped save time was using a simple tool for a repeated task at work.","start":0.0,"end":5.044580498866213},{"text":"Before that, my team checked the information manually each time.","start":5.044580498866213,"end":9.043492063492064},{"text":"We still needed to look at the results, but we wanted to avoid repeating every basic step ourselves.","start":9.043492063492064,"end":15.471292517006802},{"text":"At first, I thought we should create a complete system with lots of features.","start":15.471292517006802,"end":20.17918367346939},{"text":"However, a colleague suggested starting with a simple version.","start":20.17918367346939,"end":23.974467120181405},{"text":"I wasn't fully convinced because I worried it would look unfinished, but we discussed the idea and agreed to test it.","start":23.974467120181405,"end":30.753378684807256},{"text":"We divided the work between us and focused on the most common problem.","start":30.753378684807256,"end":34.659183673469386},{"text":"I worked on the main function, while another person tested it with a few examples.","start":34.659183673469386,"end":39.64757369614512},{"text":"Our first attempt didn't work properly because we had misunderstood part of the information.","start":39.64757369614512,"end":44.924308390022674},{"text":"We checked the issue together and corrected it.","start":44.924308390022674,"end":47.683356009070295},{"text":"Eventually, the tool handled the basic task well.","start":47.683356009070295,"end":51.05609977324263},{"text":"It wasn't perfect, but it saved us time and helped us understand what to improve next.","start":51.05609977324263,"end":56.425714285714285},{"text":"Seeing it work was a satisfying moment for me.","start":56.425714285714285,"end":59.64721088435374},{"text":"I was happy with the decision because we learned something useful without spending weeks on an idea that might not work.","start":59.64721088435374,"end":65.90108843537415},{"text":"The experience changed my opinion about planning.","start":65.90108843537415,"end":69.05954648526077},{"text":"I still think planning matters, but now I prefer to try a small, practical solution before making a bigger commitment.","start":69.05954648526077,"end":76.09959183673469}],"sha256":"cddd742522f85fa67ed4cb2652cf3542f029146cdb77bb08c59a63aa608b3fd3"},"audio/daniel-synced-160/a1f81f467de4e652.m4a":{"duration":72.4314739229025,"segments":[{"text":"A reading experience that made me happy was finishing an illustrated version of The Tortoise and the Hare by myself in primary school.","start":0.0,"end":7.122766439909297},{"text":"My father had told me the story before, but reading it without help felt different.","start":7.122766439909297,"end":12.16671201814059},{"text":"I remember sitting beside him and explaining the ending in my own words.","start":12.16671201814059,"end":16.272743764172336},{"text":"He listened patiently, and I felt that I was finally becoming a more independent reader.","start":16.272743764172336,"end":21.641360544217687},{"text":"The story is about a race between two very different animals.","start":21.641360544217687,"end":25.33356009070295},{"text":"The hare is fast and confident, while the tortoise moves slowly.","start":25.33356009070295,"end":29.118503401360545},{"text":"Because the hare thinks winning will be easy, he stops for a nap.","start":29.118503401360545,"end":32.838866213151924},{"text":"The tortoise keeps going and reaches the finish before him.","start":32.838866213151924,"end":36.30145124716553},{"text":"As a child, I found the ending funny and surprising.","start":36.30145124716553,"end":39.801904761904765},{"text":"At the beginning, I was certain that the hare would win, so I wanted to turn the pages quickly.","start":39.801904761904765,"end":45.41537414965986},{"text":"I also liked the pictures because they helped me understand what was happening without needing an adult to explain every sentence.","start":45.41537414965986,"end":52.65791383219955},{"text":"The lesson has stayed with me: steady effort matters, and being good at something doesn't mean you can stop trying.","start":52.65791383219955,"end":59.394603174603176},{"text":"I think of it when I'm learning a skill and comparing myself with people who improve faster.","start":59.394603174603176,"end":64.51006802721088},{"text":"The story reminds me to focus on my own progress.","start":64.51006802721088,"end":67.83074829931972},{"text":"It's simple, but that's probably why I still remember it after so many years.","start":67.83074829931972,"end":72.4314739229025}],"sha256":"79258a4cdd3dfbf3e6112382d3eafa79e80944713ea3b73cefba5579a9658235"},"audio/daniel-synced-160/4bf724db8153881a.m4a":{"duration":76.31097505668934,"segments":[{"text":"I'd like to talk about Adam, a colleague who works for a successful software company.","start":0.0,"end":5.369614512471656},{"text":"I've known him for about two years.","start":5.369614512471656,"end":7.604535147392291},{"text":"The company has developed a practical product that helps its customers handle repeated tasks, and Adam works on making the product easier to use.","start":7.604535147392291,"end":16.433378684807256},{"text":"I think the company has done well because it understands what its customers actually need.","start":16.433378684807256,"end":21.4443537414966},{"text":"It doesn't try to add every possible feature at once.","start":21.4443537414966,"end":24.8518820861678},{"text":"Adam follows the same approach in his own work: he sets a clear goal and keeps the solution simple.","start":24.8518820861678,"end":30.955600907029478},{"text":"A few months ago, I had to explain a new idea to our team.","start":30.955600907029478,"end":35.00172335600907},{"text":"I knew the details, but I couldn't present them clearly.","start":35.00172335600907,"end":38.528616780045354},{"text":"Adam suggested using one simple example instead of showing everything at once.","start":38.528616780045354,"end":43.44548752834467},{"text":"He also helped me practise and pointed out the parts that were difficult to follow.","start":43.44548752834467,"end":48.024625850340136},{"text":"The presentation went much better than I expected.","start":48.024625850340136,"end":51.02040816326531},{"text":"People understood the idea, and I felt more confident afterwards.","start":51.02040816326531,"end":55.26068027210884},{"text":"What I appreciate most is that he helped me learn a useful skill rather than just doing the work for me.","start":55.26068027210884,"end":61.351836734693876},{"text":"Talking to Adam has helped me understand that a successful company needs useful products and people who communicate clearly.","start":61.351836734693876,"end":68.36489795918368},{"text":"I admire his contribution because he pays attention to the person using the product.","start":68.36489795918368,"end":73.25990929705216},{"text":"That is a quality I'd like to develop in my own work.","start":73.25990929705216,"end":76.31097505668934}],"sha256":"c48d0601f22775e014223b88cb36ace090d383e766bd3fb77ace0eab0f0ed237"},"audio/daniel-synced-160/c50a49bcb04e4c12.m4a":{"duration":76.33818594104308,"segments":[{"text":"A famous person from my home region I'd like to describe is Lei Jun, the co-founder of Xiaomi.","start":0.0,"end":6.066258503401361},{"text":"We come from the same part of China, and we both studied at Wuhan University.","start":6.066258503401361,"end":10.831201814058957},{"text":"That gives me a personal reason to pay attention to him, beyond simply recognising his name.","start":10.831201814058957,"end":16.70875283446712},{"text":"He's well known for building a technology company whose products reach people far beyond our home region.","start":16.70875283446712,"end":22.655238095238094},{"text":"Although I now live in Dubai, I still feel connected to where I come from.","start":22.655238095238094,"end":27.316598639455783},{"text":"Hearing about someone from the same area doing something significant makes his story feel closer to my own life.","start":27.316598639455783,"end":34.14825396825397},{"text":"The university connection matters to me as well.","start":34.14825396825397,"end":37.00439909297052},{"text":"We both studied at Wuhan University, although at different times.","start":37.00439909297052,"end":41.29333333333334},{"text":"I enjoy learning about what he did as a student and how those experiences influenced his later career.","start":41.29333333333334,"end":47.094421768707484},{"text":"It makes me think about how much a person can develop after leaving university.","start":47.094421768707484,"end":52.118367346938776},{"text":"I admire him because he turned his interest in technology into a successful business and built considerable wealth.","start":52.118367346938776,"end":58.55750566893424},{"text":"I don't know him personally, but I'd be interested in meeting him.","start":58.55750566893424,"end":62.4675283446712},{"text":"I'd ask how he made his first significant amount of money and which business decision contributed most to his financial success.","start":62.4675283446712,"end":69.96176870748299},{"text":"Because we share a home region and university background, I'd feel comfortable asking him those questions.","start":69.96176870748299,"end":76.33818594104308}],"sha256":"665434b37708260f64b03ba3cc8daa514f8fcb327aa109c27b134b4c52ecc59b"},"audio/daniel-synced-160/0925703942de34c8.m4a":{"duration":70.92802721088435,"segments":[{"text":"A piece of technology I'd like to buy is a better pair of headphones.","start":0.0,"end":4.046122448979592},{"text":"I already use a basic pair, but I would like something more comfortable that could reduce distracting background noise.","start":4.046122448979592,"end":11.053832199546486},{"text":"It isn't a phone, and it would serve a clear purpose in my routine.","start":11.053832199546486,"end":15.20702947845805},{"text":"I often need to concentrate on work or listen to English recordings.","start":15.20702947845805,"end":19.30095238095238},{"text":"When the surroundings are noisy, I find myself repeating the same section because I've missed something.","start":19.30095238095238,"end":25.34299319727891},{"text":"A better pair could make those activities easier, especially in a shared space.","start":25.34299319727891,"end":30.26249433106576},{"text":"Before buying anything, I would compare a few models and read about their comfort and everyday use.","start":30.26249433106576,"end":35.95655328798186},{"text":"I'd prefer to try them in a shop if possible.","start":35.95655328798186,"end":38.574603174603176},{"text":"The most expensive option wouldn't necessarily be the best one for me.","start":38.574603174603176,"end":42.83827664399093},{"text":"I plan to save a little money each month instead of buying them immediately.","start":42.83827664399093,"end":47.03718820861678},{"text":"I would also check what help is available if they stop working.","start":47.03718820861678,"end":50.69043083900227},{"text":"My experience with electronic products has taught me that service matters as well as the product itself.","start":50.69043083900227,"end":57.002539682539684},{"text":"I want them because I expect to use them often, not just because they are new.","start":57.002539682539684,"end":61.689024943310656},{"text":"If they help me work and study with fewer interruptions, I would consider the purchase worthwhile.","start":61.689024943310656,"end":67.47659863945579},{"text":"Until then, I can continue using what I already have.","start":67.47659863945579,"end":70.92802721088435}],"sha256":"50aa3f2782b9a356506ff90c6bb7d6f70729b9aea1176cba2fcfb208bcb5e212"},"audio/daniel-synced-160/9a8a0268e1a88938.m4a":{"duration":74.05229024943311,"segments":[{"text":"A useful app I use at work is a small internal program that our team developed.","start":0.0,"end":4.765941043083901},{"text":"It brings requests into one shared list, so we can see what needs attention without searching through several different conversations.","start":4.765941043083901,"end":12.562040816326531},{"text":"I helped work on an early version of it.","start":12.562040816326531,"end":15.114965986394559},{"text":"Before we had the program, requests were spread across messages and emails.","start":15.114965986394559,"end":19.8221768707483},{"text":"It was easy to miss an update or forget who was handling something.","start":19.8221768707483,"end":23.554784580498865},{"text":"Even a simple question could involve looking through old conversations before finding the information we needed.","start":23.554784580498865,"end":29.726485260770975},{"text":"We started with a basic version instead of trying to build a complete system.","start":29.726485260770975,"end":34.085079365079366},{"text":"The main features were a list of requests, the person responsible for each one and its current status.","start":34.085079365079366,"end":40.298956916099776},{"text":"We tested it with a few examples and corrected the parts that were unclear.","start":40.298956916099776,"end":44.567301587301586},{"text":"I now use it to check my tasks and update their progress.","start":44.567301587301586,"end":48.16249433106576},{"text":"During team discussions, we can look at the same information rather than explain everything again from memory.","start":48.16249433106576,"end":54.62281179138322},{"text":"It doesn't do the work for us, but it helps us keep track of it.","start":54.62281179138322,"end":58.82244897959184},{"text":"What I like most is that it solves a problem I actually have.","start":58.82244897959184,"end":62.38},{"text":"The interface is simple, and I don't need a long explanation each time I open it.","start":62.38,"end":67.33795918367348},{"text":"For me, useful software makes an ordinary task easier to manage, rather than adding features I rarely need.","start":67.33795918367348,"end":74.05229024943311}],"sha256":"008de4db7b73d892e46cd55343385fa60a9bd9d4f33d56955c233960a52a3cc9"},"audio/daniel-synced-160/064de85bc47f69c3.m4a":{"duration":69.61854875283447,"segments":[{"text":"Something I find difficult to do without is my pair of headphones.","start":0.0,"end":3.9741043083900225},{"text":"They aren't a phone or a computer, but I use them almost every day.","start":3.9741043083900225,"end":7.875147392290249},{"text":"They help me concentrate in places with background noise and listen to English recordings without disturbing other people.","start":7.875147392290249,"end":14.495873015873016},{"text":"I chose a comfortable pair because I knew I would wear them for a while.","start":14.495873015873016,"end":18.555419501133787},{"text":"Before buying them, I compared a few options and saved a little money each month.","start":18.555419501133787,"end":23.262539682539682},{"text":"I wanted something useful, rather than simply buying the most fashionable brand.","start":23.262539682539682,"end":28.41609977324263},{"text":"When I finally bought them, I was pleased because I had made a deliberate choice rather than buying something on impulse.","start":28.41609977324263,"end":35.15473922902494},{"text":"I started using them regularly for work and language practice.","start":35.15473922902494,"end":39.15818594104309},{"text":"A few weeks later, one side stopped working properly.","start":39.15818594104309,"end":42.716689342403626},{"text":"I took them back to the shop, expecting a long argument.","start":42.716689342403626,"end":46.23061224489796},{"text":"Instead, the assistant listened carefully, checked the problem and explained the next steps.","start":46.23061224489796,"end":51.80925170068027},{"text":"After confirming the fault, the shop arranged a replacement.","start":51.80925170068027,"end":55.7924716553288},{"text":"When I couldn't use them, I realised how much they were part of my routine.","start":55.7924716553288,"end":60.278775510204085},{"text":"I could still work and study, but I found it harder to focus and practise listening in a shared space.","start":60.278775510204085,"end":66.21918367346939},{"text":"That's why I think of them as a small but important everyday item.","start":66.21918367346939,"end":69.61854875283447}],"sha256":"6bec5df0d6dcf0f5dcd46a10f326f29e34ef918e19cb6f61680c053d72f1f8a7"},"audio/daniel-synced-160/a521da2ebdd8964c.m4a":{"duration":67.36380952380952,"segments":[{"text":"The place where I like to relax at home is a small corner of my living room.","start":0.0,"end":4.481859410430839},{"text":"I have a comfortable chair there, with a lamp and a little space beside it for a drink or a book.","start":4.481859410430839,"end":9.772063492063491},{"text":"It isn't a large or impressive area.","start":9.772063492063491,"end":12.230204081632653},{"text":"I usually sit there after work, once I've finished the things I need to do around the apartment.","start":12.230204081632653,"end":17.880362811791382},{"text":"Sometimes I read a few pages, and sometimes I just sit quietly for a while.","start":17.880362811791382,"end":23.059274376417232},{"text":"I like having an activity that doesn't involve another screen.","start":23.059274376417232,"end":26.970521541950113},{"text":"I try to keep my work laptop away from that corner.","start":26.970521541950113,"end":30.217414965986393},{"text":"Otherwise, a short break can turn into checking messages and thinking about unfinished tasks.","start":30.217414965986393,"end":36.155963718820864},{"text":"On some evenings, I also leave my phone in another room so that I can properly rest.","start":36.155963718820864,"end":41.67913832199547},{"text":"One weekend, I spent part of an afternoon there reading a novel.","start":41.67913832199547,"end":45.5269387755102},{"text":"I wasn't following a schedule or trying to finish a certain number of pages.","start":45.5269387755102,"end":49.96965986394558},{"text":"I simply enjoyed being comfortable and having enough time to stay with the story.","start":49.96965986394558,"end":54.64648526077097},{"text":"What I enjoy most is the feeling of having no urgent task.","start":54.64648526077097,"end":58.204036281179135},{"text":"The space suits the way I relax, even though it is quite simple.","start":58.204036281179135,"end":62.13074829931973},{"text":"Twenty quiet minutes there can make the rest of my evening feel calmer and more separate from work.","start":62.13074829931973,"end":67.36380952380952}],"sha256":"3958f31a74d4cab9e8a70ecb875c3b5f7c10ea55c7afce75d6a59f1948eb4567"},"audio/daniel-synced-160/32957cce69237247.m4a":{"duration":74.90226757369615,"segments":[{"text":"A place I visit regularly but don't particularly like is the supermarket near my flat in Dubai.","start":0.0,"end":5.601904761904762},{"text":"I go there about once a week to buy groceries.","start":5.601904761904762,"end":8.61795918367347},{"text":"It's convenient, which is why I keep using it, but the experience is usually quite tiring.","start":8.61795918367347,"end":14.74485260770975},{"text":"I normally go after work, when quite a few other people have the same idea.","start":14.74485260770975,"end":19.338503401360544},{"text":"The aisles can feel crowded, and there is often a queue at the checkout.","start":19.338503401360544,"end":23.30965986394558},{"text":"I only need a few basic things, but finding them sometimes takes longer than I expect.","start":23.30965986394558,"end":29.00702947845805},{"text":"The layout is another reason I don't enjoy it.","start":29.00702947845805,"end":31.64267573696145},{"text":"Items occasionally move to a different shelf, so I walk around looking for something I bought easily the previous week.","start":31.64267573696145,"end":38.54621315192744},{"text":"There is also background music and a lot of activity, which makes it hard to relax after a busy day.","start":38.54621315192744,"end":44.97183673469388},{"text":"I remember one evening when I went in just to buy vegetables, bread and milk.","start":44.97183673469388,"end":49.79768707482993},{"text":"I spent more time waiting to pay than choosing the food.","start":49.79768707482993,"end":52.962766439909295},{"text":"By the time I got home, I felt that a small everyday task had taken up most of my evening.","start":52.962766439909295,"end":58.96113378684807},{"text":"I still shop there because it is nearby and the prices are reasonable.","start":58.96113378684807,"end":62.66009070294785},{"text":"However, I try to go at quieter times and make a list before I leave.","start":62.66009070294785,"end":67.05909297052155},{"text":"I don't dislike shopping in general; I just prefer an experience where I can find what I need and get home without too much waiting.","start":67.05909297052155,"end":74.90226757369615}],"sha256":"8bfcdd2c4f7f9b256afb6922766d42d076eb40b0198345522c8e3e71152d1883"},"audio/daniel-synced-160/1718a3022c036307.m4a":{"duration":66.11532879818594,"segments":[{"text":"One time I paid close attention to the sky was during an evening visit to Sunset Beach in Dubai.","start":0.0,"end":5.600861678004535},{"text":"I was there with a friend a few months ago, after a week when we had both spent too much time indoors.","start":5.600861678004535,"end":11.741224489795918},{"text":"We walked along the sand and found somewhere to sit away from the busier area.","start":11.741224489795918,"end":15.960498866213152},{"text":"At first, we were talking about work, but then we noticed the light beginning to change.","start":15.960498866213152,"end":21.411428571428573},{"text":"We stopped our conversation for a while and looked towards the horizon.","start":21.411428571428573,"end":25.366303854875284},{"text":"The sky had been quite bright when we arrived.","start":25.366303854875284,"end":27.96947845804989},{"text":"Later, there was orange near the horizon and a little pink above it.","start":27.96947845804989,"end":31.585759637188207},{"text":"The colours were softer than before, and the water reflected some of the light.","start":31.585759637188207,"end":35.802721088435376},{"text":"I liked noticing that change gradually rather than looking up only for a moment.","start":35.802721088435376,"end":40.46861678004535},{"text":"I took a photograph, but it didn't quite capture what I could see.","start":40.46861678004535,"end":44.84167800453515},{"text":"So I put my phone away and watched for a few more minutes.","start":44.84167800453515,"end":48.350702947845804},{"text":"My friend did the same, and neither of us felt that we needed to speak constantly.","start":48.350702947845804,"end":53.52503401360544},{"text":"I remember the experience because it was simple and relaxing.","start":53.52503401360544,"end":57.1550566893424},{"text":"It made me realise how often I ignore my surroundings when I'm busy.","start":57.1550566893424,"end":61.18952380952381},{"text":"I'd like to make more time for moments like that, even when I only have a short break.","start":61.18952380952381,"end":66.11532879818594}],"sha256":"7590bf9ee8918e0f8b954df20aee486426030f36af3c57a37cde6a55b58c99d3"},"audio/daniel-synced-160/2cefa1a7acc64ba6.m4a":{"duration":66.08090702947845,"segments":[{"text":"A moment when I felt extremely happy was near the end of a birthday dinner I organised for my friend Ben.","start":0.0,"end":6.043083900226757},{"text":"It happened a few months ago at a small restaurant in Dubai.","start":6.043083900226757,"end":9.508662131519275},{"text":"When he saw the cake and heard everyone singing, he looked completely surprised.","start":9.508662131519275,"end":14.485034013605443},{"text":"I checked when everyone was available and chose a place that was easy for us to reach.","start":14.485034013605443,"end":19.310839002267574},{"text":"Another friend arranged the cake, while I made the reservation and confirmed the time.","start":19.310839002267574,"end":24.06517006802721},{"text":"We also asked him what food he liked so that he would enjoy the meal.","start":24.06517006802721,"end":28.101315192743765},{"text":"On the evening itself, we arrived a little early and made sure everything was ready.","start":28.101315192743765,"end":32.97170068027211},{"text":"The atmosphere was relaxed.","start":32.97170068027211,"end":34.88789115646259},{"text":"We talked about work, shared some funny stories and took a few photos together.","start":34.88789115646259,"end":40.05024943310658},{"text":"The most memorable moment was when the cake came out.","start":40.05024943310658,"end":43.057414965986396},{"text":"It was quite simple, but it had a small decoration connected to one of his hobbies.","start":43.057414965986396,"end":47.92780045351474},{"text":"He hadn't expected it, and his reaction made the effort feel worthwhile.","start":47.92780045351474,"end":52.66947845804989},{"text":"I was pleased that the plan worked and that everyone had a good time.","start":52.66947845804989,"end":56.41560090702948},{"text":"It reminded me that a successful celebration doesn't depend on spending a lot of money.","start":56.41560090702948,"end":61.43691609977324},{"text":"Paying attention to the person and making time for each other can be much more important.","start":61.43691609977324,"end":66.08090702947845}],"sha256":"800f61cce18ca80d93b41785db6e75556948088a97d622a234a0f88dc2d5dab4"},"audio/daniel-synced-160/9a660ff8792196c9.m4a":{"duration":68.53056689342404,"segments":[{"text":"An important lesson I learned as a child was to keep practising instead of comparing myself with other people.","start":0.0,"end":6.193968253968254},{"text":"My father helped me understand this when I was learning to ride a bicycle in primary school.","start":6.193968253968254,"end":11.458548752834467},{"text":"At the time, I thought I was unusually slow at learning.","start":11.458548752834467,"end":15.2518820861678},{"text":"Some of my friends could already ride without help, while I kept losing my balance.","start":15.2518820861678,"end":20.31732426303855},{"text":"I became frustrated and wanted to stop trying.","start":20.31732426303855,"end":23.320408163265306},{"text":"My father reminded me of The Tortoise and the Hare, a story he'd told me before.","start":23.320408163265306,"end":28.155374149659863},{"text":"In it, the slow tortoise keeps going and wins while the confident hare takes a nap.","start":28.155374149659863,"end":32.99356009070295},{"text":"The connection was simple: I didn't have to be the fastest learner to make progress.","start":32.99356009070295,"end":37.860997732426306},{"text":"We practised for a short time each evening on a quiet part of our street.","start":37.860997732426306,"end":42.0918820861678},{"text":"He stayed beside me, and I gradually became more comfortable balancing and turning.","start":42.0918820861678,"end":47.216689342403626},{"text":"Eventually, I managed to ride a short distance on my own.","start":47.216689342403626,"end":51.13510204081633},{"text":"I was excited, but the bigger change was in how I understood learning.","start":51.13510204081633,"end":55.230884353741494},{"text":"I realised that progress could be slow without being a failure.","start":55.230884353741494,"end":58.709977324263036},{"text":"I still find that lesson useful when I'm studying something difficult or picking up a new skill.","start":58.709977324263036,"end":64.1736507936508},{"text":"It helps me focus on small improvements rather than other people's results.","start":64.1736507936508,"end":68.53056689342404}],"sha256":"3de0466f83e552c1bd183f4a63e050c696c242e202487b9b6bf0e2e794170841"},"audio/daniel-synced-160/adebea3fc893bed4.m4a":{"duration":74.85011337868481,"segments":[{"text":"A moment when I felt confident was after explaining a new idea to my team in English.","start":0.0,"end":5.218730158730159},{"text":"It happened a few months ago, during a meeting about a small work project.","start":5.218730158730159,"end":9.729206349206349},{"text":"Before the meeting, I was worried that I would lose my words or confuse people.","start":9.729206349206349,"end":14.450566893424035},{"text":"I prepared by choosing one main message and a simple example.","start":14.450566893424035,"end":18.208299319727892},{"text":"I also practised saying it aloud, because an explanation that looks clear on a page can still be difficult to say.","start":18.208299319727892,"end":25.017596371882085},{"text":"A colleague helped me notice where I was adding unnecessary details.","start":25.017596371882085,"end":29.42625850340136},{"text":"When the meeting started, I spoke a little more slowly than usual.","start":29.42625850340136,"end":33.54104308390023},{"text":"I explained the problem first, then used the example to show how the idea could help.","start":33.54104308390023,"end":38.86612244897959},{"text":"I didn't remember every sentence I had practised, but I could still get the main point across.","start":38.86612244897959,"end":44.856961451247166},{"text":"The change in my confidence came when people began asking useful questions.","start":44.856961451247166,"end":49.52439909297052},{"text":"Their questions showed that they understood the idea, and I could answer without restarting my whole explanation.","start":49.52439909297052,"end":55.689297052154195},{"text":"One colleague also said that the example had made things clearer.","start":55.689297052154195,"end":59.586122448979594},{"text":"I felt pleased because I had managed something I had been nervous about.","start":59.586122448979594,"end":63.74956916099773},{"text":"The experience didn't mean that speaking English was suddenly easy, but it gave me evidence that preparation and clear language could help me communicate.","start":63.74956916099773,"end":72.10929705215419},{"text":"Since then, I've felt more willing to speak up.","start":72.10929705215419,"end":74.85011337868481}],"sha256":"52d51e2af31c64ff4cb834f4ab91ba3c4017576007b9feee0ae03801cc3c1923"},"audio/daniel-synced-160/10c97b65751c868a.m4a":{"duration":71.94181405895692,"segments":[{"text":"A change I made to my evening routine was spending less time on my phone before bed.","start":0.0,"end":4.777551020408163},{"text":"I used to tell myself I was having a short break, but I often kept scrolling until late.","start":4.777551020408163,"end":10.323219954648525},{"text":"The next morning, I sometimes felt rushed and tired.","start":10.323219954648525,"end":13.881451247165533},{"text":"I decided to make the change small enough to maintain.","start":13.881451247165533,"end":17.16453514739229},{"text":"I chose a time to stop looking at messages and social media, usually about half an hour before I wanted to sleep.","start":17.16453514739229,"end":24.033696145124715},{"text":"I put my phone away from the bed so that it was less tempting to pick it up again.","start":24.033696145124715,"end":28.885396825396825},{"text":"During that time, I did a few things, such as preparing my clothes for the next day or reading a few pages of a book.","start":28.885396825396825,"end":36.146848072562356},{"text":"I wasn't trying to follow a complicated routine.","start":36.146848072562356,"end":39.27764172335601},{"text":"I mainly wanted the evening to feel as though it was coming to an end.","start":39.27764172335601,"end":43.21224489795918},{"text":"After a while, I noticed that I was getting into bed earlier more often.","start":43.21224489795918,"end":47.707074829931976},{"text":"On some mornings, I felt more awake and had enough time for breakfast.","start":47.707074829931976,"end":52.217551020408166},{"text":"Those mornings felt less hurried, which made the change feel worthwhile.","start":52.217551020408166,"end":56.91043083900227},{"text":"I don't manage it perfectly every night, especially when I have something urgent to finish.","start":56.91043083900227,"end":62.31814058956916},{"text":"Still, having a simple stopping point helps me control my time.","start":62.31814058956916,"end":66.619410430839},{"text":"I like the routine because it gives me a calmer end to the day and a less hurried start the next morning.","start":66.619410430839,"end":71.94181405895692}],"sha256":"85b97811d8005cc1abfa931b4c0945dbf99a800d2d8f9acd26c4c41b7a9da6a5"},"audio/daniel-synced-160/485e0012dc779992.m4a":{"duration":73.07201814058956,"segments":[{"text":"A book that influenced the way I think is The Martian by Andy Weir.","start":0.0,"end":3.6397732426303855},{"text":"It is a science-fiction novel about an astronaut called Mark Watney who is left on Mars and has to find a way to survive.","start":3.6397732426303855,"end":10.518684807256236},{"text":"I read it when I wanted something entertaining after work.","start":10.518684807256236,"end":14.244126984126984},{"text":"The main character is an astronaut called Mark Watney, who is accidentally left behind on Mars.","start":14.244126984126984,"end":20.156145124716552},{"text":"He has to find ways to stay alive and contact people on Earth.","start":20.156145124716552,"end":23.943174603174604},{"text":"The situation sounds hopeless, but he doesn't give up.","start":23.943174603174604,"end":27.35904761904762},{"text":"He deals with one problem at a time, using whatever resources he has.","start":27.35904761904762,"end":31.984625850340137},{"text":"What I enjoyed most was the way he thought through his difficulties.","start":31.984625850340137,"end":35.727936507936505},{"text":"The book made me feel as if I was following his attempts step by step.","start":35.727936507936505,"end":39.84988662131519},{"text":"Some parts were tense, but his sense of humour made the story enjoyable as well.","start":39.84988662131519,"end":44.94117913832199},{"text":"I read a little in the evening, and I often continued longer than I had planned because I wanted to know what would happen next.","start":44.94117913832199,"end":52.04253968253968},{"text":"I felt relieved whenever one of his ideas worked.","start":52.04253968253968,"end":55.233378684807256},{"text":"What influenced me most was his habit of breaking a huge problem into smaller tasks.","start":55.233378684807256,"end":60.27700680272109},{"text":"I sometimes feel overwhelmed by a difficult project, and the story reminds me to work out what I can do next.","start":60.27700680272109,"end":67.00517006802721},{"text":"I don't pretend my problems are as serious as his, but that practical way of thinking has stayed with me.","start":67.00517006802721,"end":73.07201814058956}],"sha256":"9c0699c75abcae980b09e52cee6282eed863ee477584e12de51cb3038f900e12"},"audio/daniel-synced-160/8aa0cb3656cd9037.m4a":{"duration":66.25256235827665,"segments":[{"text":"A change that made my daily life easier was moving into an apartment closer to work.","start":0.0,"end":4.905260770975056},{"text":"It happened a while ago, when I realised that the time I spent travelling was affecting the rest of my day.","start":4.905260770975056,"end":11.017913832199547},{"text":"I often got home feeling tired.","start":11.017913832199547,"end":13.361360544217687},{"text":"I compared a few places and tried to think beyond the first impression.","start":13.361360544217687,"end":17.37451247165533},{"text":"The location mattered, but I also needed somewhere within my budget and with enough room for the things I used regularly.","start":17.37451247165533,"end":23.867210884353742},{"text":"I didn't need a particularly large apartment.","start":23.867210884353742,"end":26.874331065759637},{"text":"Once I had chosen a place, I made a simple plan for moving.","start":26.874331065759637,"end":30.8962358276644},{"text":"I packed the things I didn't use every day first and kept the important items together.","start":30.8962358276644,"end":35.826575963718824},{"text":"A friend helped me carry a few things, which made the day less stressful.","start":35.826575963718824,"end":40.35133786848073},{"text":"On the first weekend, I unpacked what I needed most and arranged a small place to read.","start":40.35133786848073,"end":45.674512471655326},{"text":"It took a little time before the apartment felt familiar, but I enjoyed deciding how to use the space.","start":45.674512471655326,"end":51.940725623582765},{"text":"The biggest improvement was having more time in the evening.","start":51.940725623582765,"end":55.1687074829932},{"text":"I could prepare a meal, take a short walk or relax instead of feeling that the whole day had disappeared into work and travel.","start":55.1687074829932,"end":62.154013605442174},{"text":"The move involved some effort, but it suited the routine I wanted to have.","start":62.154013605442174,"end":66.25256235827665}],"sha256":"341a6f133e0cfaf82ff93295eb44145370869eb21ddcab522d8e10654933dc8b"},"audio/daniel-synced-160/e65bf539ae003921.m4a":{"duration":76.17301587301587,"segments":[{"text":"A place with a sense of history that I'd like to describe is Al Fahidi Historical Neighbourhood in old Dubai.","start":0.0,"end":6.10108843537415},{"text":"I visited it with my friend Adam a few months ago.","start":6.10108843537415,"end":9.150294784580499},{"text":"We wanted a quiet walk somewhere that felt different from the city's newer areas.","start":9.150294784580499,"end":13.987528344671201},{"text":"The narrow lanes and traditional buildings immediately caught my attention.","start":13.987528344671201,"end":17.993197278911566},{"text":"Instead of rushing between large modern buildings, we could walk slowly and look at small courtyards and the details around us.","start":17.993197278911566,"end":25.069478458049886},{"text":"I liked the feeling of discovering a place one corner at a time.","start":25.069478458049886,"end":29.015555555555554},{"text":"We spent some time looking around and stopped for a drink at a small cafe.","start":29.015555555555554,"end":33.35092970521542},{"text":"Adam took a few photographs, while I was more interested in how the streets connected.","start":33.35092970521542,"end":38.56965986394558},{"text":"Afterwards, we continued towards the creek and watched the boats crossing the water.","start":38.56965986394558,"end":43.50829931972789},{"text":"What made the visit enjoyable was the contrast within the same city.","start":43.50829931972789,"end":47.40253968253968},{"text":"I usually associate Dubai with busy roads and tall buildings, but that afternoon gave me a different impression.","start":47.40253968253968,"end":53.79573696145125},{"text":"We didn't need a strict schedule, so there was time to notice things we would normally walk past.","start":53.79573696145125,"end":59.56181405895692},{"text":"I would like to go back and learn more about the area's history before visiting.","start":59.56181405895692,"end":63.95809523809524},{"text":"I don't know every detail about the buildings, but the neighbourhood made me curious.","start":63.95809523809524,"end":68.66920634920635},{"text":"For me, a historical place is interesting when it helps me imagine how everyday life used to be, rather than simply looking old.","start":68.66920634920635,"end":76.17301587301587}],"sha256":"eca42089b160c135d13ca50bec7cca041e2f048480bebc4ce6d0317474d738d6"},"audio/daniel-synced-160/e12d04dbe5f8db24.m4a":{"duration":62.61605442176871,"segments":[{"text":"A journey I made by public transport was a trip to the area around Dubai Creek with a friend.","start":0.0,"end":5.334829931972789},{"text":"We used a train for part of the journey and walked the final section.","start":5.334829931972789,"end":9.054965986394558},{"text":"During the outing, we also crossed the creek in a small boat.","start":9.054965986394558,"end":13.010204081632653},{"text":"I enjoyed being a passenger because I could look around rather than concentrate on driving.","start":13.010204081632653,"end":18.091473922902495},{"text":"We checked the direction before getting on and kept the plan fairly simple.","start":18.091473922902495,"end":22.124988662131518},{"text":"Travelling together made the journey feel like part of the outing, instead of just a way to reach the destination.","start":22.124988662131518,"end":28.76907029478458},{"text":"The boat crossing was the most memorable part.","start":28.76907029478458,"end":31.36997732426304},{"text":"It was a short journey, but being close to the water gave me a different view of the buildings and the people on the shore.","start":31.36997732426304,"end":37.656780045351475},{"text":"I took a few pictures while my friend pointed out places we could explore next.","start":37.656780045351475,"end":42.58975056689342},{"text":"We also had a simple drink and talked for a while.","start":42.58975056689342,"end":45.624807256235826},{"text":"The outing didn't cost us much, but I enjoyed it more than some expensive activities I've tried.","start":45.624807256235826,"end":51.64185941043084},{"text":"I remember feeling relaxed afterwards.","start":51.64185941043084,"end":54.25020408163265},{"text":"It reminded me that I don't always need a complicated plan to have a good day.","start":54.25020408163265,"end":58.79551020408163},{"text":"Sometimes a walk, a friend and a change of surroundings are enough.","start":58.79551020408163,"end":62.61605442176871}],"sha256":"b616f657170aba37d7f91c19da4a6280d5d5efb54f7fad3f754f90d25b2efa20"},"audio/daniel-synced-160/07721c8310f388d5.m4a":{"duration":78.56979591836735,"segments":[{"text":"An open-minded person I know is my colleague Adam.","start":0.0,"end":2.9547845804988664},{"text":"We've worked together for two years, and I appreciate the way he listens when people suggest a different approach.","start":2.9547845804988664,"end":9.530929705215419},{"text":"He doesn't seem to feel that he needs to defend his first idea immediately.","start":9.530929705215419,"end":14.052018140589569},{"text":"One example was a discussion about a small tool our team wanted to build.","start":14.052018140589569,"end":18.294512471655327},{"text":"I was in favour of creating a complete system, while another colleague suggested testing a simple version first.","start":18.294512471655327,"end":24.966303854875285},{"text":"At the beginning, Adam also seemed interested in planning more features in advance.","start":24.966303854875285,"end":30.10639455782313},{"text":"However, he asked the colleague to explain what we could learn from a small prototype.","start":30.10639455782313,"end":35.00462585034013},{"text":"He listened carefully and asked practical questions about the time involved and how we would check the result.","start":35.00462585034013,"end":40.84662131519274},{"text":"He also made sure that I had a chance to explain my concerns.","start":40.84662131519274,"end":45.18195011337868},{"text":"After the discussion, he supported trying the smaller version.","start":45.18195011337868,"end":49.0},{"text":"We agreed on one basic task, tested it with a few examples and used the results to decide what to do next.","start":49.0,"end":55.634195011337866},{"text":"The approach gave us useful information before we committed more time to the project.","start":55.634195011337866,"end":60.60643990929705},{"text":"What impressed me was that Adam changed his view after considering the explanation.","start":60.60643990929705,"end":65.24371882086167},{"text":"He didn't simply agree to avoid an argument.","start":65.24371882086167,"end":67.85814058956916},{"text":"His questions showed that he was thinking seriously about the idea.","start":67.85814058956916,"end":71.68},{"text":"I enjoy working with him because different opinions can become something useful instead of making the conversation uncomfortable.","start":71.68,"end":78.56979591836735}],"sha256":"494223141f5365a6edf5641bfc9ad9f6cfb76de689753b0b06c96f288fc984d5"},"audio/daniel-synced-160/b49bc18244f4e716.m4a":{"duration":64.70947845804989,"segments":[{"text":"A public place I like in my hometown is the area around West Lake in Hangzhou.","start":0.0,"end":4.765941043083901},{"text":"When I am there, I enjoy walking along the paths beside the lake, especially when I want a break from a busy routine.","start":4.765941043083901,"end":11.99482993197279},{"text":"We spent an afternoon walking along the paths beside the lake.","start":11.99482993197279,"end":15.40140589569161},{"text":"What I remember most is the space around the water.","start":15.40140589569161,"end":18.227528344671203},{"text":"There were trees beside the path, and we could stop whenever we noticed a view we liked.","start":18.227528344671203,"end":22.932426303854875},{"text":"I took a few photos, but I also put my phone away for part of the walk.","start":22.932426303854875,"end":28.03954648526077},{"text":"At one point, we sat down and watched the light change on the water.","start":28.03954648526077,"end":32.09727891156463},{"text":"We talked about ordinary things and didn't feel that we had to keep moving to another attraction.","start":32.09727891156463,"end":37.23374149659864},{"text":"Afterwards, we found somewhere nearby to have a simple meal.","start":37.23374149659864,"end":41.24358276643991},{"text":"For me, the lake is important because it gives people a place to enjoy being outdoors while visiting a city.","start":41.24358276643991,"end":47.380045351473925},{"text":"I liked the balance between walking, looking around and having time to talk.","start":47.380045351473925,"end":52.27814058956916},{"text":"I'd happily go back, especially with someone who enjoys a slower kind of holiday.","start":52.27814058956916,"end":57.33428571428571},{"text":"Next time, I'd leave more time to explore Hangzhou beyond the lake, rather than trying to fit everything into one afternoon.","start":57.33428571428571,"end":64.70947845804989}],"sha256":"9810966f5f804adf0da7bceca5f59a673f3e8e2f068ffc486b3b0d628cb97f3c"},"audio/daniel-synced-160/ccaeca71d83c1f3b.m4a":{"duration":74.63446712018141,"segments":[{"text":"I'd like to talk about a film called The Martian.","start":0.0,"end":2.885079365079365},{"text":"I watched it at home with a friend a few months ago.","start":2.885079365079365,"end":5.84172335600907},{"text":"Matt Damon plays an astronaut who is accidentally left behind on Mars.","start":5.84172335600907,"end":10.154285714285715},{"text":"The mixture of an unusual setting and practical problem-solving appealed to me.","start":10.154285714285715,"end":14.893968253968254},{"text":"The main character is an astronaut called Mark Watney, who is accidentally left behind on Mars.","start":14.893968253968254,"end":20.805986394557824},{"text":"He has to find ways to stay alive and contact people on Earth.","start":20.805986394557824,"end":24.593015873015872},{"text":"The situation sounds hopeless, but he doesn't give up.","start":24.593015873015872,"end":28.00888888888889},{"text":"He deals with one problem at a time, using whatever resources he has.","start":28.00888888888889,"end":32.634467120181405},{"text":"What I enjoyed most was seeing how the character responded to each new difficulty.","start":32.634467120181405,"end":37.329795918367346},{"text":"The film made me feel as if I was following his attempts step by step.","start":37.329795918367346,"end":41.54462585034014},{"text":"Some parts were tense, but his sense of humour made the experience enjoyable as well.","start":41.54462585034014,"end":46.98421768707483},{"text":"I particularly liked the landscape and the way the acting conveyed his loneliness.","start":46.98421768707483,"end":51.39206349206349},{"text":"My friend and I kept wondering how we would behave in that situation.","start":51.39206349206349,"end":55.27505668934241},{"text":"Afterwards, we talked about which part of the story had made us feel most nervous.","start":55.27505668934241,"end":60.6897052154195},{"text":"The story also gave me a useful reminder: a big problem becomes less frightening when you focus on the next small action.","start":60.6897052154195,"end":67.96009070294785},{"text":"I think that's why it stayed with me.","start":67.96009070294785,"end":70.11501133786848},{"text":"I'd recommend it to someone who enjoys a hopeful story with a clever main character.","start":70.11501133786848,"end":74.63446712018141}],"sha256":"c80edadd8b4788800ca18db99636a14f847e96c1b2372cc125491482e7a30898"},"audio/daniel-synced-160/4cad7a13bc110bde.m4a":{"duration":32.42798185941043,"segments":[{"text":"What takes up most of your time at work?","start":0.0,"end":3.235918367346939},{"text":"I'm a software developer, and most of my time goes into building business applications.","start":3.235918367346939,"end":8.686802721088435},{"text":"I enjoy solving practical problems with my team, especially when a small change makes somebody's daily work easier.","start":8.686802721088435,"end":17.083673469387755},{"text":"What would you like to learn alongside your job?","start":17.083673469387755,"end":20.215011337868482},{"text":"I'd like to improve my spoken English and learn more about designing useful products.","start":20.215011337868482,"end":25.155056689342402},{"text":"I can already explain technical details, but I want to communicate my ideas more clearly to people outside my field.","start":25.155056689342402,"end":32.42798185941043}],"sha256":"589735a99678417ccfeb0660d3af727799604b465e5d473ad6eb93f1a44e9a15"},"audio/daniel-synced-160/a3adbf8f6c2b68c8.m4a":{"duration":26.31877551020408,"segments":[{"text":"Which part of your home do you use the most?","start":0.0,"end":3.22421768707483},{"text":"I spend a lot of time in my living room because it's where I read, watch films and occasionally work on my laptop.","start":3.22421768707483,"end":10.068480725623584},{"text":"I keep a comfortable chair by the window.","start":10.068480725623584,"end":13.97233560090703},{"text":"What would you change about your home if you could?","start":13.97233560090703,"end":17.09206349206349},{"text":"I'd add a little more storage near the entrance.","start":17.09206349206349,"end":19.814603174603175},{"text":"My shoes and bags sometimes end up on the floor, so a simple cabinet would make the apartment easier to keep tidy.","start":19.814603174603175,"end":26.31877551020408}],"sha256":"0dbabf41a936f512e3d15c7264aa4d164ca448b0e0065f43e830ad83ca8ea34a"},"audio/daniel-synced-160/9a28031c0cfd3c02.m4a":{"duration":28.66281179138322,"segments":[{"text":"What would you show a visitor in your hometown?","start":0.0,"end":3.270657596371882},{"text":"My hometown is Hangzhou, and I'd take a visitor for a walk near West Lake.","start":3.270657596371882,"end":7.931519274376417},{"text":"It's a pleasant way to see the city, especially if we stop for tea afterwards.","start":7.931519274376417,"end":14.341224489795918},{"text":"Which memory makes you feel connected to your hometown?","start":14.341224489795918,"end":18.180680272108845},{"text":"I remember riding my bike around the neighbourhood with my childhood friend Ben.","start":18.180680272108845,"end":22.379591836734694},{"text":"We often stopped at a small shop for snacks, and those ordinary afternoons still make the place feel familiar.","start":22.379591836734694,"end":28.66281179138322}],"sha256":"b0bfbb9c2cfb816003681ba1d26645935905082aebeb9f33f29e7099eb71cd45"},"audio/daniel-synced-160/05170f19f16038e6.m4a":{"duration":27.347709750566892,"segments":[{"text":"What makes your neighbourhood convenient for you?","start":0.0,"end":3.293877551020408},{"text":"There are a supermarket and a small coffee shop within walking distance of my apartment.","start":3.293877551020408,"end":8.135192743764172},{"text":"I can buy groceries or meet a friend without arranging a long trip, which saves time.","start":8.135192743764172,"end":14.593242630385488},{"text":"Where do you go when you want a break nearby?","start":14.593242630385488,"end":17.86390022675737},{"text":"I usually walk to a quiet spot near my building or visit a local coffee shop.","start":17.86390022675737,"end":22.434331065759636},{"text":"Getting outside for half an hour helps me relax after spending most of the day indoors.","start":22.434331065759636,"end":27.347709750566892}],"sha256":"aac729acf30e966b808fd1c8aebff2c731d66380369abd74cd01e5629cc964d3"},"audio/daniel-synced-160/01a59dbf97cb6e40.m4a":{"duration":30.67528344671202,"segments":[{"text":"What do you enjoy about living in Dubai?","start":0.0,"end":3.212607709750567},{"text":"I enjoy meeting people from different backgrounds.","start":3.212607709750567,"end":6.343401360544218},{"text":"At work and in everyday life, I hear several languages and encounter different habits, so a normal conversation can teach me something new.","start":6.343401360544218,"end":16.1897052154195},{"text":"How has living in Dubai changed your routine?","start":16.1897052154195,"end":19.637460317460317},{"text":"I've become more careful about when I go outside.","start":19.637460317460317,"end":22.696689342403626},{"text":"During hot weather, I prefer walking early in the morning or after sunset, and I plan longer outdoor activities around cooler days.","start":22.696689342403626,"end":30.67528344671202}],"sha256":"5fedc10aad09b45696ab494fa79e8531ba10fe232d5fa473d1032fac80607cbe"},"audio/daniel-synced-160/b4882754d3d343d0.m4a":{"duration":29.58625850340136,"segments":[{"text":"What sort of trip would you choose for a short holiday?","start":0.0,"end":3.6886167800453515},{"text":"I'd choose somewhere with interesting streets, good food and a few quiet places to walk.","start":3.6886167800453515,"end":8.744761904761905},{"text":"I don't need a packed schedule; I'd rather explore one area properly than rush between attractions.","start":8.744761904761905,"end":16.225850340136056},{"text":"What helps you enjoy a long journey?","start":16.225850340136056,"end":19.020544217687075},{"text":"I download a few podcasts and bring comfortable headphones.","start":19.020544217687075,"end":22.814467120181405},{"text":"If I'm travelling with a friend, we also talk about the places we'd like to visit, which makes the journey feel shorter.","start":22.814467120181405,"end":29.58625850340136}],"sha256":"a79b06a2e7f0bc4e0c9becd1836a06f27ede30824062004a6d62a1257df50e27"},"audio/daniel-synced-160/460ec1006bf48ac4.m4a":{"duration":30.985532879818596,"segments":[{"text":"Which things do you try to recycle at home?","start":0.0,"end":3.572426303854875},{"text":"I try to separate cardboard boxes and plastic bottles from other rubbish.","start":3.572426303854875,"end":8.026757369614513},{"text":"Online shopping creates quite a lot of packaging, so I flatten the boxes first to keep the recycling area tidy.","start":8.026757369614513,"end":16.549478458049887},{"text":"What makes recycling difficult in daily life?","start":16.549478458049887,"end":20.20326530612245},{"text":"The main problem is knowing what each collection point accepts.","start":20.20326530612245,"end":23.767709750566894},{"text":"If the instructions are unclear, I hesitate.","start":23.767709750566894,"end":26.76888888888889},{"text":"Clear labels near the bins would help me sort things correctly and make it a habit.","start":26.76888888888889,"end":30.985532879818596}],"sha256":"1c6cc13f9dbf4d071d7c5f7e0603b78db9bd1f5211e1e2957a744ae6a10fbb0b"},"audio/daniel-synced-160/692ae5c354446ab2.m4a":{"duration":29.22875283446712,"segments":[{"text":"When do you tend to feel mentally tired?","start":0.0,"end":3.1196825396825396},{"text":"I feel mentally tired after several meetings followed by detailed coding work.","start":3.1196825396825396,"end":7.898458049886622},{"text":"Even if I haven't moved much, concentrating for hours can wear me out, so I take a short walk afterwards.","start":7.898458049886622,"end":16.461814058956914},{"text":"What helps you recover after a tiring day?","start":16.461814058956914,"end":19.906621315192744},{"text":"A simple dinner and a quiet evening usually help.","start":19.906621315192744,"end":22.82657596371882},{"text":"I put my phone aside, listen to music and try to sleep at a sensible time instead of staying online late.","start":22.82657596371882,"end":29.22875283446712}],"sha256":"f9e7d3b478139c22e1a3ea9db9653c170592081c16c2b4431c4f955dc125b9a3"},"audio/daniel-synced-160/d4d3f97ea8e4b348.m4a":{"duration":29.792789115646258,"segments":[{"text":"What matters most when you choose a pair of shoes?","start":0.0,"end":3.595736961451247},{"text":"Comfort matters most because I often walk when running errands.","start":3.595736961451247,"end":7.395918367346939},{"text":"I prefer simple trainers that match different clothes, and I try them on properly instead of choosing only by appearance.","start":7.395918367346939,"end":15.920498866213151},{"text":"Have your preferences in shoes changed over time?","start":15.920498866213151,"end":19.649569160997732},{"text":"When I was younger, I paid more attention to the style.","start":19.649569160997732,"end":23.172244897959185},{"text":"Now I think about how my feet feel after a long day, so I usually choose lighter, more comfortable shoes.","start":23.172244897959185,"end":29.792789115646258}],"sha256":"8a09320f45050e347de56c672aa751b10f0a04cea504220540c297fb8626f42f"},"audio/daniel-synced-160/7aff8303be1b3853.m4a":{"duration":31.371201814058956,"segments":[{"text":"What does being polite look like in your daily life?","start":0.0,"end":3.781496598639456},{"text":"For me, it means listening without interrupting, saying thank you and being considerate in shared spaces.","start":3.781496598639456,"end":10.138548752834467},{"text":"Small things, like lowering my voice in a café, can make other people more comfortable.","start":10.138548752834467,"end":17.219319727891158},{"text":"Who helped you develop polite habits as a child?","start":17.219319727891158,"end":20.940272108843537},{"text":"My parents taught me to greet people and thank them when they helped me.","start":20.940272108843537,"end":24.811655328798185},{"text":"They also reminded me to return borrowed things promptly, which made politeness feel practical rather than formal.","start":24.811655328798185,"end":31.371201814058956}],"sha256":"5c170afa82ec66f551a86e6f0af6c973f8c9a7a431157926f4f5181177014573"},"audio/daniel-synced-160/cb511762d1307a29.m4a":{"duration":28.368526077097506,"segments":[{"text":"How do you fit fruit and vegetables into your meals?","start":0.0,"end":3.8889342403628118},{"text":"I usually add vegetables to dinner and keep easy snacks like apples or bananas at home.","start":3.8889342403628118,"end":9.144353741496598},{"text":"If they're already washed and ready, I'm much more likely to eat them during a busy day.","start":9.144353741496598,"end":15.275419501133786},{"text":"Were there vegetables you avoided when you were younger?","start":15.275419501133786,"end":18.650566893424035},{"text":"I disliked carrots when I was a child, especially when they were boiled.","start":18.650566893424035,"end":23.02498866213152},{"text":"Later, I tried them roasted and found the taste much better, so I eat them more often now.","start":23.02498866213152,"end":28.368526077097506}],"sha256":"96f11b1ee77535674f31df129af23bbd5c9d6596da8ab2aac4400adc70cc7722"},"audio/daniel-synced-160/2061687c6aba9c49.m4a":{"duration":31.39832199546485,"segments":[{"text":"What kind of advertisement is likely to catch your attention?","start":0.0,"end":4.2575056689342405},{"text":"I notice advertisements that show a clear use for a product.","start":4.2575056689342405,"end":7.736598639455782},{"text":"A short demonstration of how something works is more interesting to me than a famous face with no explanation.","start":7.736598639455782,"end":15.272562358276645},{"text":"How do you react when the same advertisement keeps appearing?","start":15.272562358276645,"end":19.451746031746033},{"text":"I usually stop paying attention after a while.","start":19.451746031746033,"end":22.46643990929705},{"text":"If it interrupts a video repeatedly, I may skip it immediately, even when the product itself seems useful.","start":22.46643990929705,"end":29.29891156462585},{"text":"Too much repetition becomes annoying.","start":29.29891156462585,"end":31.39832199546485}],"sha256":"86c0e1c669c2274a15c514c007b9d1f413ea28922fa4d85f2f91d2833f43eef4"},"audio/daniel-synced-160/1c360b46c06276d1.m4a":{"duration":29.703038548752833,"segments":[{"text":"When do you still find paper useful?","start":0.0,"end":3.0965079365079364},{"text":"I find paper useful when I'm planning something complicated.","start":3.0965079365079364,"end":6.934875283446712},{"text":"Drawing a rough diagram or making a short list helps me see the whole idea without switching between different windows on a screen.","start":6.934875283446712,"end":15.468390022675736},{"text":"What did you enjoy making with paper as a child?","start":15.468390022675736,"end":19.145396825396826},{"text":"I used to make paper planes with Ben after school.","start":19.145396825396826,"end":22.160090702947844},{"text":"We tried different shapes and compared how far they flew.","start":22.160090702947844,"end":25.439002267573695},{"text":"It was a cheap activity, but we took the competition quite seriously.","start":25.439002267573695,"end":29.703038548752833}],"sha256":"ba3e5be6373a337c0ae5d98186fd17cc5f6c6d0605517131000b6813df9e2d3a"},"audio/daniel-synced-160/09fed7186fdc623f.m4a":{"duration":30.915873015873014,"segments":[{"text":"Which part of secondary school do you remember most clearly?","start":0.0,"end":4.106530612244898},{"text":"I remember the lunch breaks because they gave us time to talk without worrying about lessons.","start":4.106530612244898,"end":9.385170068027211},{"text":"Ben and I often discussed films or planned what we'd do together after school.","start":9.385170068027211,"end":15.213514739229025},{"text":"Was there a school subject that became easier with practice?","start":15.213514739229025,"end":19.343310657596373},{"text":"English became easier once I started reading short articles outside class.","start":19.343310657596373,"end":24.10920634920635},{"text":"At first, I looked up almost every unfamiliar word, but gradually I could follow the meaning without stopping so often.","start":24.10920634920635,"end":30.915873015873014}],"sha256":"41b4b443940f83529a2d25d82e2e3ecd13dee666b4ab0dad085d6930e036820a"},"audio/daniel-synced-160/c2ee54d172a972ee.m4a":{"duration":28.71174603174603,"segments":[{"text":"What do you like about the name you use in English?","start":0.0,"end":3.5028571428571427},{"text":"I use the English name Marshall.","start":3.5028571428571427,"end":5.461043083900226},{"text":"I like that it's easy to introduce myself with it in international settings.","start":5.461043083900226,"end":9.926938775510203},{"text":"It also feels familiar now because colleagues and friends use it regularly.","start":9.926938775510203,"end":15.547165532879818},{"text":"How do you remember the name of someone you've just met?","start":15.547165532879818,"end":19.308390022675738},{"text":"I try to use the person's name once during the conversation and connect it with something we discussed.","start":19.308390022675738,"end":24.80761904761905},{"text":"If I'm unsure later, I'd rather ask politely than keep guessing.","start":24.80761904761905,"end":28.71174603174603}],"sha256":"8e31317cadd3b0a925cfadf95fa3e5d41e882962677ed3e1abf3ffe1b6b185ec"},"audio/daniel-synced-160/6889345c7825bff7.m4a":{"duration":30.987573696145123,"segments":[{"text":"What kind of music suits your usual working day?","start":0.0,"end":3.8047619047619046},{"text":"I like quiet instrumental music when I'm doing routine work.","start":3.8047619047619046,"end":7.771428571428571},{"text":"Songs with strong lyrics can distract me, so I save those for travelling or relaxing when I can pay more attention.","start":7.771428571428571,"end":16.268616780045352},{"text":"Has a song ever reminded you of a particular time?","start":16.268616780045352,"end":19.927619047619046},{"text":"Yes, some songs remind me of journeys with friends.","start":19.927619047619046,"end":23.671065759637187},{"text":"When I hear them again, I remember the conversations and places we visited, even if I haven't thought about that trip for months.","start":23.671065759637187,"end":30.987573696145123}],"sha256":"a496b23d51ec6e796707d86a68768b565b6eb344280b506913c8e38a68e5b934"},"audio/daniel-synced-160/1533c371e9319d44.m4a":{"duration":33.0746485260771,"segments":[{"text":"What made a teacher memorable to you?","start":0.0,"end":2.8294784580498864},{"text":"My secondary-school English teacher made lessons feel manageable.","start":2.8294784580498864,"end":6.666031746031746},{"text":"She asked us to describe real experiences instead of only memorising rules, and she corrected mistakes in a way that didn't embarrass anyone.","start":6.666031746031746,"end":16.682721088435375},{"text":"Would you enjoy being a teacher yourself?","start":16.682721088435375,"end":19.837278911564624},{"text":"I'd enjoy teaching a practical skill, such as basic coding, because I like explaining how things work.","start":19.837278911564624,"end":26.669750566893423},{"text":"However, managing a full classroom every day would require more patience and experience than I currently have.","start":26.669750566893423,"end":33.0746485260771}],"sha256":"53cce553bf5bca523b452483d60dfcab902dadb1adb90e1eca6092894a450160"},"audio/daniel-synced-160/4726abb54aae6c77.m4a":{"duration":29.077551020408162,"segments":[{"text":"What do you mainly use social media for?","start":0.0,"end":3.4215873015873015},{"text":"I mainly use it to keep up with friends and find interesting articles or short videos.","start":3.4215873015873015,"end":8.259138321995465},{"text":"I rarely post long updates, but I sometimes share a photograph from a trip.","start":8.259138321995465,"end":14.45015873015873},{"text":"How do you stop social media from taking up too much time?","start":14.45015873015873,"end":18.98925170068027},{"text":"I try not to open it while I'm working, and I put my phone away before bed.","start":18.98925170068027,"end":23.65251700680272},{"text":"If I keep scrolling without a purpose, I remind myself what I originally wanted to check.","start":23.65251700680272,"end":29.077551020408162}],"sha256":"f50f2454a444962537dcc6f3b3d24db3b43b0dfeffcc55d3c49a203f90049c0e"},"audio/daniel-synced-160/93fa5e410d60230c.m4a":{"duration":28.581632653061224,"segments":[{"text":"Which area do you make the most effort to keep tidy?","start":0.0,"end":3.7466213151927437},{"text":"I make the most effort with my desk because clutter distracts me when I'm working.","start":3.7466213151927437,"end":8.351972789115646},{"text":"I put cables and small items in a drawer and clear away empty cups before starting.","start":8.351972789115646,"end":14.717142857142857},{"text":"Were you as tidy when you were a child?","start":14.717142857142857,"end":17.6859410430839},{"text":"Not really.","start":17.6859410430839,"end":18.608616780045352},{"text":"I left books and toys wherever I finished using them.","start":18.608616780045352,"end":21.81043083900227},{"text":"My parents often had to remind me to clean up, but I became more organised when I started sharing space with others.","start":21.81043083900227,"end":28.581632653061224}],"sha256":"95c3b7c2979bad7d8a52e832b3a3c5872b33f8debbc9e03ba9844b433db1036c"},"audio/daniel-synced-160/4d366c43f6a919c1.m4a":{"duration":31.658956916099772,"segments":[{"text":"What makes a website useful enough for you to revisit?","start":0.0,"end":3.955691609977324},{"text":"A useful website gives me clear information without making me search through too many pages.","start":3.955691609977324,"end":9.46467120181406},{"text":"I often return to technical documentation because the examples help me solve problems at work.","start":9.46467120181406,"end":16.82780045351474},{"text":"Have you learned a practical skill through a website?","start":16.82780045351474,"end":20.371111111111112},{"text":"Yes, I learned how to prepare a simple dish by following a cooking website.","start":20.371111111111112,"end":25.29877551020408},{"text":"The instructions included photographs at each stage, which helped me understand what the food should look like.","start":25.29877551020408,"end":31.658956916099772}],"sha256":"9b65653a8a86ca85a6ceb723974c3b0fe47e2f095e03cd42ff3efe2de2111af2"},"audio/daniel-synced-160/00bad63d64b760ce.m4a":{"duration":28.45809523809524,"segments":[{"text":"When is wearing a watch useful for you?","start":0.0,"end":3.0965079365079364},{"text":"A watch is useful when I'm outside or in a meeting and want to check the time quickly.","start":3.0965079365079364,"end":7.699909297052154},{"text":"It saves me from looking at my phone and getting distracted by notifications.","start":7.699909297052154,"end":13.78453514739229},{"text":"Would you spend a lot of money on a watch?","start":13.78453514739229,"end":16.81138321995465},{"text":"Probably not.","start":16.81138321995465,"end":17.89374149659864},{"text":"I'd choose something comfortable and reliable rather than very expensive.","start":17.89374149659864,"end":22.079138321995465},{"text":"I can appreciate a well-designed watch, but I would rather spend extra money on travel or a useful device.","start":22.079138321995465,"end":28.45809523809524}],"sha256":"0eac661e9742b42c45928435c8eafd2c1d9a1d09385c1a15d5205462e180dc3a"},"audio/daniel-synced-160/90228df439e8c690.m4a":{"duration":31.097868480725623,"segments":[{"text":"How do you decide whether to buy something online?","start":0.0,"end":3.5638548752834467},{"text":"I compare the size, price and return conditions before ordering.","start":3.5638548752834467,"end":7.810566893424037},{"text":"For things like headphones, I also read a few detailed reviews because photographs alone don't tell me how comfortable a product is.","start":7.810566893424037,"end":17.36716553287982},{"text":"Do you prefer shopping alone or with someone else?","start":17.36716553287982,"end":21.021133786848072},{"text":"I prefer going alone when I know exactly what I need.","start":21.021133786848072,"end":24.45378684807256},{"text":"If I'm choosing a gift, I enjoy taking a friend because a second opinion can help me avoid an unsuitable choice.","start":24.45378684807256,"end":31.097868480725623}],"sha256":"1f9187695ab90d69e9e2f1bb890ad690975c9134c5977bd64df827effa7ea2fb"},"audio/daniel-synced-160/a638ad5f2ecb846f.m4a":{"duration":28.93455782312925,"segments":[{"text":"What do you enjoy about travelling by car?","start":0.0,"end":3.351927437641723},{"text":"I like the flexibility, especially when travelling with friends or carrying several bags.","start":3.351927437641723,"end":8.80467120181406},{"text":"We can leave at a convenient time and stop along the way without following somebody else's schedule.","start":8.80467120181406,"end":15.55015873015873},{"text":"How do you usually handle being stuck in traffic?","start":15.55015873015873,"end":19.32299319727891},{"text":"I try to stay patient and listen to a podcast if it's safe to do so.","start":19.32299319727891,"end":23.54512471655329},{"text":"Getting frustrated doesn't help, so I allow extra time when I know a journey may be busy.","start":23.54512471655329,"end":28.93455782312925}],"sha256":"250a61d4e1b4c2fcbc078eebbddac8a504ea6694f0836a06ccef3e18a789ab15"},"audio/daniel-synced-160/b2d4472b5f94d607.m4a":{"duration":27.809614512471654,"segments":[{"text":"What would you do during a quiet afternoon in a park?","start":0.0,"end":3.630612244897959},{"text":"I'd walk for a while and then sit somewhere shaded with a book.","start":3.630612244897959,"end":6.852380952380952},{"text":"I enjoy having space around me, and I don't need an organised activity to feel that the visit was worthwhile.","start":6.852380952380952,"end":14.935827664399094},{"text":"Did parks play a part in your childhood?","start":14.935827664399094,"end":18.04417233560091},{"text":"Yes, I often went to a local park with Ben.","start":18.04417233560091,"end":21.276780045351472},{"text":"We rode our bikes and made up simple games.","start":21.276780045351472,"end":24.05641723356009},{"text":"It was a place where we could spend an afternoon without needing much money.","start":24.05641723356009,"end":27.809614512471654}],"sha256":"20412941eb4c2973279266fc8f6e3143641cdbcd81dee9889c447d19c52b1e10"},"audio/daniel-synced-160/28c68625fb8c47f7.m4a":{"duration":33.67360544217687,"segments":[{"text":"Which area of science would you like to understand better?","start":0.0,"end":3.897551020408163},{"text":"I'd like to understand astronomy better because I find space fascinating.","start":3.897551020408163,"end":8.419637188208617},{"text":"I know a few basic ideas, but I'd enjoy learning how scientists study objects that are so far away.","start":8.419637188208617,"end":16.14312925170068},{"text":"How do you encounter science outside the classroom?","start":16.14312925170068,"end":20.113333333333333},{"text":"I encounter it through technology, cooking and short documentaries.","start":20.113333333333333,"end":24.463129251700682},{"text":"For example, learning why bread rises makes an ordinary kitchen activity more interesting, and it helps me understand what went wrong when a recipe fails.","start":24.463129251700682,"end":33.67360544217687}],"sha256":"541e4890bfa3e9f158aa3c58bfe1a6d7a0d50eb74645cb7229397c2a4d073420"},"audio/daniel-synced-160/75d480f22a608826.m4a":{"duration":25.915283446712017,"segments":[{"text":"When do you usually use a mirror during the day?","start":0.0,"end":3.4215419501133786},{"text":"I usually check a mirror before leaving home to make sure my clothes and hair look presentable.","start":3.4215419501133786,"end":8.560861678004535},{"text":"I don't spend very long on it, but it's part of getting ready.","start":8.560861678004535,"end":13.69673469387755},{"text":"Would you use mirrors to decorate your home?","start":13.69673469387755,"end":16.781632653061223},{"text":"Yes, I'd consider a simple mirror near the entrance.","start":16.781632653061223,"end":20.269659863945577},{"text":"It would be useful before going out, and it could make the space feel brighter without taking up much room.","start":20.269659863945577,"end":25.915283446712017}],"sha256":"22c7029172e73f39f932a23b71c1b3319cb37cf9ed4783b4535bd530eccdf03f"},"audio/daniel-synced-160/76473fce20b58b45.m4a":{"duration":31.171473922902493,"segments":[{"text":"What attracts your attention when you look at the night sky?","start":0.0,"end":3.874421768707483},{"text":"I notice the moon first because it's easy to see and its shape changes over time.","start":3.874421768707483,"end":8.537732426303855},{"text":"If I'm somewhere darker, I also enjoy trying to recognise a few stars.","start":8.537732426303855,"end":14.564308390022676},{"text":"Would you like to learn more about space in the future?","start":14.564308390022676,"end":18.125215419501135},{"text":"Yes, I'd like to understand how telescopes help scientists study distant objects.","start":18.125215419501135,"end":23.737868480725623},{"text":"A beginner's course or a well-made documentary would suit me because I want clear explanations before going into technical details.","start":23.737868480725623,"end":31.171473922902493}],"sha256":"62d77002ae99aa836f3010f1aeff3993c2fd68d8b47032740c892c42ceb07002"},"audio/daniel-synced-160/c5b6d4e162786f30.m4a":{"duration":29.242857142857144,"segments":[{"text":"In what situations do you find yourself singing?","start":0.0,"end":3.7940589569161},{"text":"I sometimes sing quietly when I'm cooking or travelling alone.","start":3.7940589569161,"end":7.399365079365079},{"text":"I usually follow a song I already know, and I enjoy it more when I'm not worrying about how I sound.","start":7.399365079365079,"end":14.960362811791382},{"text":"Would you feel comfortable singing in front of friends?","start":14.960362811791382,"end":18.846349206349206},{"text":"I'd feel comfortable in a relaxed group, especially if everyone joined in.","start":18.846349206349206,"end":23.461315192743765},{"text":"Singing alone in front of an audience would make me nervous, so I'd need some practice before trying that.","start":23.461315192743765,"end":29.242857142857144}],"sha256":"c64af30bdce0fb55d425324feb37b77e085f22392caee09df29e3b9033fdb25f"},"audio/daniel-synced-160/419321081b44e346.m4a":{"duration":29.43596371882086,"segments":[{"text":"How do you choose what to wear on an ordinary day?","start":0.0,"end":3.610294784580499},{"text":"I usually choose simple clothes that are comfortable and easy to combine.","start":3.610294784580499,"end":7.704716553287982},{"text":"For work, I want to look presentable, but I don't enjoy spending a long time deciding what to wear.","start":7.704716553287982,"end":15.415328798185941},{"text":"Do you keep clothes that you no longer wear?","start":15.415328798185941,"end":18.535238095238096},{"text":"I used to keep too many, especially items that didn't fit well.","start":18.535238095238096,"end":22.768979591836736},{"text":"Now I check my wardrobe occasionally and give away things in good condition, which makes it easier to find what I need.","start":22.768979591836736,"end":29.43596371882086}],"sha256":"c8c70bddb75a6e375fc003f4a72dc998cdc022088be98190ca72e4ccbcd539e4"},"audio/daniel-synced-160/5f048c7cd496e48f.m4a":{"duration":30.4865306122449,"segments":[{"text":"What kind of humour do you enjoy in a programme?","start":0.0,"end":3.630612244897959},{"text":"I enjoy humour based on ordinary situations, like misunderstandings between friends or small problems at work.","start":3.630612244897959,"end":10.685532879818593},{"text":"It feels relatable, and it doesn't need to be loud or cruel to make me laugh.","start":10.685532879818593,"end":16.73532879818594},{"text":"Do you and your friends have a similar sense of humour?","start":16.73532879818594,"end":20.24997732426304},{"text":"Ben and I often laugh at the same things because we've known each other since childhood.","start":20.24997732426304,"end":24.817641723356008},{"text":"A small comment can remind us of an old situation, even when nobody else understands the joke.","start":24.817641723356008,"end":30.4865306122449}],"sha256":"99cf9c611a6b9ac6df831e0f461f9058fa747d16f74191d56a421049c0dfe29a"},"audio/daniel-synced-160/823a9c56ccd1d91e.m4a":{"duration":29.573333333333334,"segments":[{"text":"When are headphones especially useful to you?","start":0.0,"end":3.3402721088435374},{"text":"They're useful when I'm travelling or listening to something while other people are nearby.","start":3.3402721088435374,"end":7.775691609977324},{"text":"I can enjoy a podcast without disturbing anyone, and comfortable headphones make a long journey more pleasant.","start":7.775691609977324,"end":15.557278911564627},{"text":"Are there times when you prefer not to wear headphones?","start":15.557278911564627,"end":19.472789115646258},{"text":"I take them off when somebody is speaking to me or when I need to pay attention to my surroundings.","start":19.472789115646258,"end":25.041678004535147},{"text":"For example, I prefer hearing what's happening when I'm crossing a busy road.","start":25.041678004535147,"end":29.573333333333334}],"sha256":"0a855351cb1ae3085927d2aa12152408e4b9bd6810e8899121a3ed1aea026b3f"},"audio/daniel-synced-160/0fca4afea60a2086.m4a":{"duration":28.68798185941043,"segments":[{"text":"What sort of activity makes you lose interest quickly?","start":0.0,"end":3.839591836734694},{"text":"I get bored when I have to wait with nothing useful to do.","start":3.839591836734694,"end":7.260589569160998},{"text":"If a queue moves slowly, I may read a short article, but I'd still prefer the process to be more efficient.","start":7.260589569160998,"end":15.005442176870748},{"text":"What did you do when you felt bored as a child?","start":15.005442176870748,"end":18.50829931972789},{"text":"I usually called Ben or went outside with my bike.","start":18.50829931972789,"end":21.499773242630386},{"text":"If the weather was bad, we made things from paper or cardboard.","start":21.499773242630386,"end":25.15111111111111},{"text":"Having somebody to share an activity with made a big difference.","start":25.15111111111111,"end":28.68798185941043}],"sha256":"7a2753a945a57c1844c03f64e9c4e15ef0cf64fa29b5b11e06f3ca52015c0240"},"audio/daniel-synced-160/fbc2800c0be86215.m4a":{"duration":31.12875283446712,"segments":[{"text":"What task would be difficult for you without a computer?","start":0.0,"end":3.653786848072562},{"text":"My work would be difficult because I use a computer to write code, test applications and communicate with my team.","start":3.653786848072562,"end":10.32312925170068},{"text":"A phone is useful for messages, but it couldn't replace that setup.","start":10.32312925170068,"end":15.885351473922903},{"text":"What would you look for when buying your next computer?","start":15.885351473922903,"end":19.48108843537415},{"text":"I'd look for reliable performance, a comfortable keyboard and a screen that doesn't strain my eyes.","start":19.48108843537415,"end":25.373151927437643},{"text":"Portability would matter too, but I wouldn't choose the lightest model if it made daily work uncomfortable.","start":25.373151927437643,"end":31.12875283446712}],"sha256":"ac02a3b7a100eddb6e3261be7f4b3337e44047a98643abd49598722ae4d3f7a6"},"audio/daniel-synced-160/9eae5b496890cc5a.m4a":{"duration":29.385895691609978,"segments":[{"text":"Is there anything small that you like keeping over time?","start":0.0,"end":3.817278911564626},{"text":"I keep a few postcards and tickets from trips.","start":3.817278911564626,"end":6.6578231292517005},{"text":"I don't try to build a valuable collection; I like them because they remind me of places, people and small moments I enjoyed.","start":6.6578231292517005,"end":15.636598639455782},{"text":"Did you collect anything when you were younger?","start":15.636598639455782,"end":18.698503401360544},{"text":"I collected stickers for a while when I was at school.","start":18.698503401360544,"end":21.759637188208618},{"text":"Ben and I traded the ones we had twice.","start":21.759637188208618,"end":24.36530612244898},{"text":"I eventually lost interest, but comparing our collections was enjoyable at the time.","start":24.36530612244898,"end":29.385895691609978}],"sha256":"f04d9528e4df0695dc3f85f08f430e56ce98c7eaf64b12e9551fd99d0adc7898"},"audio/daniel-synced-160/531d5878fffc2674.m4a":{"duration":31.128707482993196,"segments":[{"text":"What would encourage you to visit a street market?","start":0.0,"end":3.4680272108843537},{"text":"I'd go for fresh food, small local products and the chance to walk around.","start":3.4680272108843537,"end":8.141043083900227},{"text":"I enjoy seeing several stalls together, especially when I'm visiting a place and want to understand its everyday life.","start":8.141043083900227,"end":16.51469387755102},{"text":"How does shopping at a market feel different from a supermarket?","start":16.51469387755102,"end":20.77514739229025},{"text":"A market feels more personal because I can ask the seller about an item directly.","start":20.77514739229025,"end":25.517868480725625},{"text":"A supermarket is usually easier when I'm in a hurry, since the layout and prices are more predictable.","start":25.517868480725625,"end":31.128707482993196}],"sha256":"4712330aeb8c16f557ba2874867d9e3d5e2f05b8b7c77d3a42234153fc1838b2"},"audio/daniel-synced-160/c440c9ff01bfee44.m4a":{"duration":34.414920634920634,"segments":[{"text":"What is a personal goal you're currently working towards?","start":0.0,"end":3.87437641723356},{"text":"I'm working towards speaking English more confidently.","start":3.87437641723356,"end":6.933605442176871},{"text":"I practise short answers aloud and record myself occasionally.","start":6.933605442176871,"end":10.81904761904762},{"text":"I'd like to explain my ideas smoothly in conversations, especially when I haven't prepared every sentence.","start":10.81904761904762,"end":19.06312925170068},{"text":"Have your ambitions changed since childhood?","start":19.06312925170068,"end":22.432290249433105},{"text":"Yes.","start":22.432290249433105,"end":23.2384126984127},{"text":"When I was younger, I mainly imagined having an impressive job title.","start":23.2384126984127,"end":27.57378684807256},{"text":"Now I care more about doing useful work, learning steadily and having enough time for people and activities I enjoy.","start":27.57378684807256,"end":34.414920634920634}],"sha256":"11c284aa94b27fb6bd96ca758b8c29e3333d9ae88fd9e8e06d6292479e05d243"},"audio/daniel-synced-160/a063d2f90a4096d8.m4a":{"duration":32.442585034013604,"segments":[{"text":"What helps you become interested in a historical topic?","start":0.0,"end":3.886031746031746},{"text":"A personal story helps me become interested.","start":3.886031746031746,"end":6.585396825396826},{"text":"Ben once showed me his grandfather's old photographs and explained how the neighbourhood had changed.","start":6.585396825396826,"end":12.267619047619048},{"text":"That made history feel connected to real people's lives.","start":12.267619047619048,"end":17.20893424036281},{"text":"Would you choose to learn history through reading or visiting places?","start":17.20893424036281,"end":21.431609977324264},{"text":"I'd choose a combination.","start":21.431609977324264,"end":23.10925170068027},{"text":"Reading gives me the background, but visiting a museum or an old street makes the details easier to remember.","start":23.10925170068027,"end":29.360861678004536},{"text":"I enjoy comparing what I've read with what I can see.","start":29.360861678004536,"end":32.442585034013604}],"sha256":"14da98b588f18fdc647df0b53485da02faae7c8e6e7df2095bf0e5550d9109f4"},"audio/daniel-synced-160/06a7531066989a66.m4a":{"duration":30.149931972789116,"segments":[{"text":"What makes you decide to watch a particular film?","start":0.0,"end":3.6421768707482993},{"text":"I usually look at the story and a few reviews rather than choosing only by the actors.","start":3.6421768707482993,"end":8.502857142857144},{"text":"If a friend recommends something and explains why they enjoyed it, I'm more likely to try it.","start":8.502857142857144,"end":15.121541950113379},{"text":"Do you enjoy watching a film again after some time?","start":15.121541950113379,"end":19.019319727891155},{"text":"Yes, especially if I enjoyed the characters or didn't fully understand the story the first time.","start":19.019319727891155,"end":25.073151927437642},{"text":"A second viewing lets me notice smaller details without worrying about what will happen next.","start":25.073151927437642,"end":30.149931972789116}],"sha256":"f36eebc3b1de80880f7f24efaa04e2a9870ef942b6b95f44fc24ce19c1b93943"},"audio/daniel-synced-160/824327df7da2c324.m4a":{"duration":29.09106575963719,"segments":[{"text":"What interests you about an old building?","start":0.0,"end":2.8991836734693877},{"text":"I like noticing the materials, windows and small details that are different from modern buildings.","start":2.8991836734693877,"end":8.665396825396826},{"text":"They make me wonder how people used the space and what everyday life was like at the time.","start":8.665396825396826,"end":14.814285714285715},{"text":"Would you prefer an old home or a modern one?","start":14.814285714285715,"end":18.003673469387756},{"text":"For living, I'd probably choose a modern home because maintenance and comfort matter to me.","start":18.003673469387756,"end":23.25777777777778},{"text":"I enjoy visiting older buildings, but I wouldn't want to deal with frequent repairs in my own apartment.","start":23.25777777777778,"end":29.09106575963719}],"sha256":"5cf3763b9c0f50c4238cc0b67ed487fe2382bf67ef4cdc38e8f70b3fca5c55e0"},"audio/daniel-synced-160/d045a34f08efefd2.m4a":{"duration":29.87124716553288,"segments":[{"text":"What does a pleasant evening at home look like for you?","start":0.0,"end":3.7698866213151927},{"text":"A pleasant evening usually includes a simple meal, some music and time away from work.","start":3.7698866213151927,"end":9.116326530612245},{"text":"I might read or watch a film, but I try not to fill every quiet moment with my phone.","start":9.116326530612245,"end":15.760090702947846},{"text":"Do your weekend evenings differ from weekday evenings?","start":15.760090702947846,"end":19.57659863945578},{"text":"Yes, I'm more likely to meet friends or stay out a little later at the weekend.","start":19.57659863945578,"end":24.237233560090704},{"text":"On weekdays, I prefer a calm routine because I need to be ready for work the next morning.","start":24.237233560090704,"end":29.87124716553288}],"sha256":"48f543e3b703402872600a74a0623d8a307cc8a22c883da3bd63d0a5a82f756a"},"audio/daniel-synced-160/ee94299834e56753.m4a":{"duration":31.960544217687076,"segments":[{"text":"Which part of your morning routine do you value most?","start":0.0,"end":3.793015873015873},{"text":"I value having a few quiet minutes before checking messages.","start":3.793015873015873,"end":7.492380952380953},{"text":"Making breakfast and looking at the day's main tasks helps me feel prepared, instead of starting the morning by reacting to everything at once.","start":7.492380952380953,"end":17.059455782312924},{"text":"Was getting up early easy for you when you were younger?","start":17.059455782312924,"end":20.585532879818594},{"text":"It wasn't always easy, especially after school holidays.","start":20.585532879818594,"end":24.50390022675737},{"text":"I often stayed up later than usual and struggled with the alarm.","start":24.50390022675737,"end":28.13342403628118},{"text":"Having a fixed bedtime helped once the school term started again.","start":28.13342403628118,"end":31.960544217687076}],"sha256":"48e3c0be96e8a0dbf8fa76d140cbab4bd80571d76ebb0edd81029d1d720c5b1f"},"audio/daniel-synced-160/a89c6ac7aa1c1efc.m4a":{"duration":30.64235827664399,"segments":[{"text":"What keeps you interested when watching sport on television?","start":0.0,"end":4.048526077097506},{"text":"I enjoy a close match when the result is uncertain until the end.","start":4.048526077097506,"end":7.910748299319728},{"text":"Watching with friends makes it more exciting because we discuss the players' decisions and react together to important moments.","start":7.910748299319728,"end":16.026167800453514},{"text":"Would you rather watch sport at home or at the venue?","start":16.026167800453514,"end":19.598684807256237},{"text":"For convenience, I'd choose home because I can see the action clearly and avoid the journey.","start":19.598684807256237,"end":24.945668934240363},{"text":"However, I'd like to attend an important match occasionally to experience the atmosphere in person.","start":24.945668934240363,"end":30.64235827664399}],"sha256":"ff9583706097971dfe78de77eacc644f67b4543656ec281a7bb114127e04ba70"},"audio/daniel-synced-160/66b168cfb14e1379.m4a":{"duration":30.593333333333334,"segments":[{"text":"What would you do first if you realised you'd lost something?","start":0.0,"end":3.897641723356009},{"text":"I'd stop and think about where I last used it, then retrace my steps if possible.","start":3.897641723356009,"end":9.02344671201814},{"text":"For something important, I'd contact the place I visited rather than immediately assuming it was stolen.","start":9.02344671201814,"end":16.443809523809524},{"text":"How would you deal with an item someone else had left behind?","start":16.443809523809524,"end":20.57655328798186},{"text":"I'd hand it to a responsible member of staff or the appropriate lost-property desk.","start":20.57655328798186,"end":25.31922902494331},{"text":"I'd prefer it to be stored safely where the owner might look, rather than taking it home with me.","start":25.31922902494331,"end":30.593333333333334}],"sha256":"d700812d74e23cf8b9fddb4841776aa6729f45a1f9c8cbf11004d146e470b5f5"},"audio/daniel-synced-160/a144eb99e5891207.m4a":{"duration":31.958367346938775,"segments":[{"text":"What kind of artwork do you find easy to connect with?","start":0.0,"end":3.886031746031746},{"text":"I connect most easily with pictures of familiar places or everyday life.","start":3.886031746031746,"end":8.224263038548752},{"text":"I don't need to understand every technique, but I enjoy recognising a mood or detail that reminds me of my own experiences.","start":8.224263038548752,"end":17.319138321995464},{"text":"Would you like to spend more time making art?","start":17.319138321995464,"end":20.613015873015872},{"text":"Yes, I'd like to try simple sketching.","start":20.613015873015872,"end":23.450884353741497},{"text":"It would give me something to do away from a screen, and I wouldn't need expensive equipment.","start":23.450884353741497,"end":28.704399092970522},{"text":"I'd start by drawing ordinary objects around my home.","start":28.704399092970522,"end":31.958367346938775}],"sha256":"807b6f346fd3c392fdd6a77da40f18083d257f5a36472b4a259ce194d64239b3"},"audio/daniel-synced-160/146022d62e96d850.m4a":{"duration":30.508163265306123,"segments":[{"text":"What would make you accept a new opportunity?","start":0.0,"end":3.328707482993197},{"text":"I'd accept it if it gave me a useful skill or a chance to work with people I could learn from.","start":3.328707482993197,"end":8.814421768707483},{"text":"I'd also check whether I had enough time to take it seriously.","start":8.814421768707483,"end":13.923809523809524},{"text":"Have you ever hesitated before trying something new?","start":13.923809523809524,"end":17.61764172335601},{"text":"Yes, I hesitated before giving a short presentation at work because I was worried about making mistakes.","start":17.61764172335601,"end":24.240362811791382},{"text":"Preparing a few clear points helped, and the experience made the next presentation feel less intimidating.","start":24.240362811791382,"end":30.508163265306123}],"sha256":"431611054fce3d487dbb2ef490069b2724d5d8f813dcee684b682a7e50d5df0d"},"audio/daniel-synced-160/b81a49d3c25981e0.m4a":{"duration":29.15392290249433,"segments":[{"text":"How do you usually spend a day with no work planned?","start":0.0,"end":3.854104308390023},{"text":"I like starting slowly, having breakfast without rushing and going out for a walk.","start":3.854104308390023,"end":8.796054421768707},{"text":"Later, I might meet a friend or visit Alex's coffee shop, but I leave some time unplanned.","start":8.796054421768707,"end":15.87891156462585},{"text":"Would you rather stay home or go out on a day off?","start":15.87891156462585,"end":19.381768707482994},{"text":"I'd usually do a little of both.","start":19.381768707482994,"end":21.488979591836735},{"text":"Going out helps me feel refreshed, while a quiet afternoon at home gives me time to read or finish small tasks without watching the clock.","start":21.488979591836735,"end":29.15392290249433}],"sha256":"69fb29248dc54b9cfb3f18e188e20b15b2f0be779006a65d2926c7e1a5d70383"},"audio/daniel-synced-160/69f7fb9782fc8d98.m4a":{"duration":29.800181405895692,"segments":[{"text":"Do you tend to remember what you dreamed about?","start":0.0,"end":3.317278911564626},{"text":"I remember a dream occasionally, usually if I wake up during it.","start":3.317278911564626,"end":7.365260770975056},{"text":"The details often disappear quickly, though, so by breakfast I may only remember a place or a strong feeling.","start":7.365260770975056,"end":15.478367346938775},{"text":"Would you ever tell a friend about an unusual dream?","start":15.478367346938775,"end":19.074104308390023},{"text":"Yes, if it was funny or included somebody we both knew.","start":19.074104308390023,"end":22.8059410430839},{"text":"I wouldn't treat it as a prediction, but it could start an entertaining conversation, especially with a close friend like Ben.","start":22.8059410430839,"end":29.800181405895692}],"sha256":"a4d5f722c1c54beae020e267fa70e12358b4016b8a623ec1d9e9f72b8e053680"},"audio/daniel-synced-160/d3d8b63eed6157a9.m4a":{"duration":29.225759637188208,"segments":[{"text":"What helps you keep track of your keys?","start":0.0,"end":2.9571882086167802},{"text":"I keep them in the same small tray near the entrance when I get home.","start":2.9571882086167802,"end":6.900680272108843},{"text":"That simple habit saves me from searching through bags or pockets when I'm trying to leave quickly.","start":6.900680272108843,"end":13.699591836734694},{"text":"Have you ever had an inconvenient experience involving keys?","start":13.699591836734694,"end":18.020362811791383},{"text":"Once, I thought I'd lost my keys just before leaving home.","start":18.020362811791383,"end":21.972607709750566},{"text":"I checked several places and eventually found them in yesterday's jacket.","start":21.972607709750566,"end":26.136643990929706},{"text":"Since then, I've tried to put them away immediately.","start":26.136643990929706,"end":29.225759637188208}],"sha256":"42ab0f5ea6422f2067fda399d1294345c2b44b095a1acd2de3e166dde73dc861"},"audio/daniel-synced-160/c704f8ac3cd6421f.m4a":{"duration":30.833015873015874,"segments":[{"text":"Would you like to have plants where you live?","start":0.0,"end":2.9804081632653063},{"text":"Yes, I'd like a couple of easy plants near the window.","start":2.9804081632653063,"end":6.514875283446712},{"text":"They would make the room feel more pleasant, but I'd choose something manageable because I sometimes forget small household tasks during busy weeks.","start":6.514875283446712,"end":16.0534693877551},{"text":"What would make flowers a suitable gift for you?","start":16.0534693877551,"end":19.556326530612246},{"text":"Flowers would be a nice gift for a celebration or when visiting someone's home.","start":19.556326530612246,"end":24.165714285714287},{"text":"I'd choose a simple arrangement rather than something enormous, especially if the person had limited space to display it.","start":24.165714285714287,"end":30.833015873015874}],"sha256":"eaa6169e43928a1029fdf52887289d2ca902a045f0c3af3ad9a4874e9ec7f404"},"audio/daniel-synced-160/71caf20bd06a1a51.m4a":{"duration":33.12086167800454,"segments":[{"text":"Which relative do you enjoy talking with?","start":0.0,"end":3.0964172335600906},{"text":"I enjoy talking with my cousin Sara because she's thoughtful and curious.","start":3.0964172335600906,"end":7.399818594104309},{"text":"She's interested in becoming a nurse, so our conversations often include her plans, volunteer experiences and what she's learning.","start":7.399818594104309,"end":16.998548752834466},{"text":"How do you keep in touch with relatives who live far away?","start":16.998548752834466,"end":21.073242630385487},{"text":"We mainly use messages and occasional video calls.","start":21.073242630385487,"end":24.352108843537415},{"text":"A quick photograph or short update helps us stay connected between longer conversations, and we try to make time for family gatherings when possible.","start":24.352108843537415,"end":33.12086167800454}],"sha256":"5d094033cbb25a932c8af5185b17d7abd74e1001b446f37a7967968c52e8588a"},"audio/daniel-synced-160/580da1d099e9a8c2.m4a":{"duration":29.45206349206349,"segments":[{"text":"Which colours do you tend to choose for everyday things?","start":0.0,"end":3.8278458049886623},{"text":"I often choose blue, grey or other simple colours for clothes and bags.","start":3.8278458049886623,"end":8.316371882086168},{"text":"They combine easily, so I don't have to spend much time thinking about whether different items match.","start":8.316371882086168,"end":15.617097505668934},{"text":"Would you use a bright colour anywhere in your home?","start":15.617097505668934,"end":19.01546485260771},{"text":"I'd use a bright colour in a small detail, like a cushion or a picture.","start":19.01546485260771,"end":23.375011337868482},{"text":"I prefer calm colours for large surfaces, but one colourful item can make a room feel more lively.","start":23.375011337868482,"end":29.45206349206349}],"sha256":"3636e758266fa70fc1939ea305e59016243b64b479db3d56f8ff6f998ec415f9"},"audio/daniel-synced-160/eeb34dba008c7864.m4a":{"duration":31.844353741496597,"segments":[{"text":"What kind of geographical information do you find useful?","start":0.0,"end":4.303945578231293},{"text":"I find information about distance, climate and transport useful when planning a trip.","start":4.303945578231293,"end":9.75609977324263},{"text":"It helps me choose where to stay, what to pack and whether I can comfortably explore a place on foot.","start":9.75609977324263,"end":17.1178231292517},{"text":"Did you enjoy using maps when you were at school?","start":17.1178231292517,"end":20.551247165532878},{"text":"Yes, I liked comparing places on a map and seeing how far apart they were.","start":20.551247165532878,"end":25.47891156462585},{"text":"It made unfamiliar countries feel easier to imagine, especially when a teacher connected the map with a real story.","start":25.47891156462585,"end":31.844353741496597}],"sha256":"0b31c3a63280a9e9045df79e8c4eca08bef3cb3ed2bea27d321506635bd3ce0c"},"audio/daniel-synced-160/c82021191105fc79.m4a":{"duration":29.378095238095238,"segments":[{"text":"How do you make sure you arrive at an appointment on time?","start":0.0,"end":4.028253968253968},{"text":"I check the route in advance and leave a little extra time for unexpected delays.","start":4.028253968253968,"end":8.88888888888889},{"text":"For an important appointment, I also set a reminder so I don't become absorbed in another task.","start":8.88888888888889,"end":16.239591836734693},{"text":"How do you feel when somebody keeps you waiting?","start":16.239591836734693,"end":19.83827664399093},{"text":"A short delay doesn't bother me if the person lets me know.","start":19.83827664399093,"end":23.18780045351474},{"text":"What frustrates me is having no update, because I can't decide whether to keep waiting or change my plans.","start":23.18780045351474,"end":29.378095238095238}],"sha256":"209bc8775b9cbe9cf2c57ddc3d7aa911ef63c8d4b8f5697872937a8a2eacb779"},"audio/daniel-synced-160/053f87978e956bc9.m4a":{"duration":29.120090702947845,"segments":[{"text":"When would you choose handwriting instead of typing?","start":0.0,"end":3.491201814058957},{"text":"I'd choose handwriting for a short personal note or a rough plan.","start":3.491201814058957,"end":7.223809523809524},{"text":"It feels more direct, and I can add arrows or small drawings without worrying about how the page is formatted.","start":7.223809523809524,"end":14.945442176870749},{"text":"Has your handwriting changed since your school days?","start":14.945442176870749,"end":18.697732426303855},{"text":"Yes, it has become less neat because I type much more than I write by hand.","start":18.697732426303855,"end":23.56734693877551},{"text":"If I slow down, I can still write clearly, but quick notes sometimes look quite untidy.","start":23.56734693877551,"end":29.120090702947845}],"sha256":"bb46ec5fa2703fac2c53440c70661493c0c154a142a3d013ac7ac39937e99f15"},"audio/daniel-synced-160/2efe06913f29e729.m4a":{"duration":52.96861678004535,"segments":[{"text":"Why do people sometimes ask others to help them make decisions?","start":0.0,"end":4.6289795918367345},{"text":"Other people can notice risks that we overlook, especially when we feel excited or anxious.","start":4.6289795918367345,"end":10.41655328798186},{"text":"Someone considering a new job might ask a friend about the working hours rather than focus only on salary.","start":10.41655328798186,"end":16.538503401360543},{"text":"However, advice should support the decision, not replace it, because the person making the choice has to live with the consequences.","start":16.538503401360543,"end":25.797278911564625},{"text":"Do people make decisions differently now than in the past?","start":25.797278911564625,"end":29.845714285714287},{"text":"I think people often have more information available now, but that doesn't always make choosing easier.","start":29.845714285714287,"end":35.680997732426306},{"text":"When booking a hotel, for example, hundreds of reviews may create new doubts instead of resolving them.","start":35.680997732426306,"end":42.10616780045351},{"text":"Earlier decisions might have relied more on personal recommendations.","start":42.10616780045351,"end":46.130430839002265},{"text":"The difference also depends on the decision; family matters still require judgement that an online search cannot provide.","start":46.130430839002265,"end":52.96861678004535}],"sha256":"178a55665f34de9dfe51d7946df7bf4cfbc932b4f2db02151d22a8f91cc86d02"},"audio/daniel-synced-160/a3b033e53dd116f9.m4a":{"duration":53.85106575963719,"segments":[{"text":"Is hard work enough to make someone successful?","start":0.0,"end":3.550249433106576},{"text":"Hard work matters, but I wouldn't say it guarantees success.","start":3.550249433106576,"end":7.528662131519274},{"text":"A small business owner can work long hours and still struggle if customers don't need the product.","start":7.528662131519274,"end":12.81705215419501},{"text":"They also need sound decisions, useful skills and some opportunities.","start":12.81705215419501,"end":17.451972789115647},{"text":"Effort is valuable because it improves what someone can control, although the final result may depend on circumstances outside their control.","start":17.451972789115647,"end":26.996462585034013},{"text":"How might a young person's idea of success differ from an older person's?","start":26.996462585034013,"end":31.97673469387755},{"text":"A younger person might connect success with getting a desirable job or proving their ability.","start":31.97673469387755,"end":37.183854875283444},{"text":"Someone with more experience may value control over their time, such as being able to leave work for a family event.","start":37.183854875283444,"end":44.29265306122449},{"text":"These priorities can overlap, of course.","start":44.29265306122449,"end":47.26498866213152},{"text":"Age may influence what people want, but their responsibilities and personal values probably matter just as much.","start":47.26498866213152,"end":53.85106575963719}],"sha256":"da54bc5c80787bde2e285b022822a3c235269c8b3dbdbcabb74fb2b09ccb100c"},"audio/daniel-synced-160/4b41a740757c7534.m4a":{"duration":51.580997732426304,"segments":[{"text":"Can buying things make people happy?","start":0.0,"end":2.8406802721088433},{"text":"Yes, particularly when a purchase solves a problem or supports something they enjoy.","start":2.8406802721088433,"end":7.988934240362812},{"text":"A comfortable chair could make working at home more pleasant, for instance.","start":7.988934240362812,"end":12.464625850340136},{"text":"The excitement of owning something new may fade, though.","start":12.464625850340136,"end":15.750793650793652},{"text":"I think purchases contribute more lasting satisfaction when they have a clear purpose, rather than being used to fill every moment of boredom.","start":15.750793650793652,"end":25.191972789115646},{"text":"Do children and adults find happiness in different things?","start":25.191972789115646,"end":29.22907029478458},{"text":"Children may enjoy immediate experiences, like playing a game with a friend, while adults can appreciate something less visible, such as finishing a difficult responsibility.","start":29.22907029478458,"end":39.914739229024946},{"text":"However, I don't think the difference is complete.","start":39.914739229024946,"end":43.00181405895692},{"text":"An adult can still love a simple game, and a child can feel proud of an achievement.","start":43.00181405895692,"end":48.092834467120184},{"text":"Happiness depends on the meaning an experience has for someone.","start":48.092834467120184,"end":51.580997732426304}],"sha256":"ade51d0192f44f72ea11872445cdcd3cb1af4e1920491b64345e8f118d95377b"},"audio/daniel-synced-160/77ea05931fd6e023.m4a":{"duration":56.27301587301587,"segments":[{"text":"Why do people enjoy watching interviews with famous people?","start":0.0,"end":4.187800453514739},{"text":"An interview can reveal how someone thinks, rather than showing only their public performance.","start":4.187800453514739,"end":9.72},{"text":"A musician explaining how a song developed may help listeners appreciate it more.","start":9.72,"end":14.520770975056688},{"text":"Some viewers are simply curious about the person's life.","start":14.520770975056688,"end":17.984036281179137},{"text":"I find interviews more worthwhile when the questions explore their work or choices, although entertainment is a perfectly reasonable reason to watch.","start":17.984036281179137,"end":27.727074829931972},{"text":"Should interviewers treat celebrities differently from ordinary guests?","start":27.727074829931972,"end":32.364172335600905},{"text":"They may need to prepare differently because a celebrity's work is already familiar to the audience, but basic respect should remain the same.","start":32.364172335600905,"end":40.3427664399093},{"text":"An interviewer can ask a challenging question about a public statement without demanding private family details.","start":40.3427664399093,"end":46.699274376417236},{"text":"Fame shouldn't remove personal boundaries.","start":46.699274376417236,"end":49.253696145124714},{"text":"Equally, an ordinary guest deserves proper research and thoughtful questions, rather than being treated as less interesting.","start":49.253696145124714,"end":56.27301587301587}],"sha256":"3fe12a47a6976ba368d5707f4fe922fdce7adeb28521c212a167a9a82de4da17"},"audio/daniel-synced-160/ce085530cc5b22d1.m4a":{"duration":52.88022675736961,"segments":[{"text":"Why do some people find it difficult to stay organised?","start":0.0,"end":4.1413605442176875},{"text":"Sometimes the problem is an unrealistic system rather than a lack of effort.","start":4.1413605442176875,"end":8.34766439909297},{"text":"A person might create a detailed weekly schedule that leaves no room for unexpected tasks, then stop using it after one busy day.","start":8.34766439909297,"end":16.492108843537416},{"text":"I think organisation works better when it fits someone's actual routine.","start":16.492108843537416,"end":20.8297052154195},{"text":"Frequent interruptions can also make maintaining even a simple plan difficult.","start":20.8297052154195,"end":26.90875283446712},{"text":"Is being organised at home the same as being organised at work?","start":26.90875283446712,"end":31.3065306122449},{"text":"The basic aim is similar: making things easier to find and tasks easier to manage.","start":31.3065306122449,"end":36.452290249433105},{"text":"At work, though, the system usually needs to make sense to other people.","start":36.452290249433105,"end":41.009251700680274},{"text":"A shared folder requires clear names, while a personal drawer can follow someone's own preferences.","start":41.009251700680274,"end":47.08712018140589},{"text":"Home organisation may be more flexible, unless several family members depend on the same arrangement.","start":47.08712018140589,"end":52.88022675736961}],"sha256":"04b7e2ca369ea59b02bdf2557b1fb33d67d4de02b9eff381ab4107866d3951d0"},"audio/daniel-synced-160/745a5a417dff8838.m4a":{"duration":53.782267573696146,"segments":[{"text":"Why can the same noise annoy one person but not another?","start":0.0,"end":3.9672108843537415},{"text":"People may attach different meanings to a sound.","start":3.9672108843537415,"end":6.791065759637188},{"text":"Music from a neighbour's party could feel enjoyable to a guest but frustrating to someone trying to finish an assignment.","start":6.791065759637188,"end":13.251473922902495},{"text":"The timing and the person's activity matter too.","start":13.251473922902495,"end":16.08448979591837},{"text":"A sound doesn't have to be extremely loud to interrupt concentration, although tolerance varies and some people can work comfortably with background noise.","start":16.08448979591837,"end":26.441632653061223},{"text":"Would you expect noise problems to be different in a city and a village?","start":26.441632653061223,"end":30.966167800453515},{"text":"I would expect different sources rather than complete silence in one place.","start":30.966167800453515,"end":35.53659863945578},{"text":"A city resident might be disturbed by traffic, while someone in a village could hear machinery or barking dogs.","start":35.53659863945578,"end":41.95115646258503},{"text":"People may also have different expectations of quiet.","start":41.95115646258503,"end":45.28585034013606},{"text":"The important comparison is probably between particular locations and times, since a quiet city street can be calmer than a busy village centre.","start":45.28585034013606,"end":53.782267573696146}],"sha256":"75d7d0e8440cb21476086ac7bc4e920015f6f5bfb2e3443243647a87299cfec6"},"audio/daniel-synced-160/87d28b05da5f49a2.m4a":{"duration":50.2756462585034,"segments":[{"text":"Why should cities include parks and other green spaces?","start":0.0,"end":4.129750566893424},{"text":"They give residents places to spend time outside without needing to leave the city.","start":4.129750566893424,"end":8.658049886621315},{"text":"A small park can offer somewhere to sit, walk or meet a friend after work.","start":8.658049886621315,"end":13.238231292517007},{"text":"I think that makes neighbourhood life more enjoyable.","start":13.238231292517007,"end":16.19424036281179},{"text":"However, creating a park isn't enough by itself; it needs to be accessible and maintained so people actually feel comfortable using it.","start":16.19424036281179,"end":26.033514739229027},{"text":"How does visiting a city park differ from visiting a remote natural area?","start":26.033514739229027,"end":31.037006802721088},{"text":"A city park is usually easier to fit into an ordinary day, while a remote area can offer a stronger sense of getting away.","start":31.037006802721088,"end":38.2178231292517},{"text":"Someone might take a short walk in a park during lunch but plan a whole weekend around a mountain visit.","start":38.2178231292517,"end":44.003083900226756},{"text":"Neither experience is automatically better.","start":44.003083900226756,"end":46.78344671201814},{"text":"The choice depends on available time and what the visitor wants.","start":46.78344671201814,"end":50.2756462585034}],"sha256":"2088c282a8f0bfb24f6aa59367df12a48e81175267de5132c6d39f629ba5ed3d"},"audio/daniel-synced-160/686dbd658358d9ca.m4a":{"duration":53.637687074829934,"segments":[{"text":"Why do some people find it hard to save money?","start":0.0,"end":3.6189115646258503},{"text":"For some people, essential expenses leave very little to save, so it would be unfair to blame every case on poor discipline.","start":3.6189115646258503,"end":11.102131519274376},{"text":"Others may struggle because small purchases are easy to overlook.","start":11.102131519274376,"end":14.799954648526077},{"text":"Ordering extra food several evenings a week, for example, can reduce what remains.","start":14.799954648526077,"end":20.54108843537415},{"text":"The reasons differ, and practical advice needs to match the person's actual situation.","start":20.54108843537415,"end":27.00589569160998},{"text":"Should children learn about saving in the same way as adults?","start":27.00589569160998,"end":31.29469387755102},{"text":"The principle can be similar, but the examples should suit their responsibilities.","start":31.29469387755102,"end":36.205986394557826},{"text":"A child might save pocket money for a toy and learn that choosing one thing means waiting for another.","start":36.205986394557826,"end":41.784625850340134},{"text":"Adults need to think about larger commitments and unexpected expenses.","start":41.784625850340134,"end":46.120997732426304},{"text":"I would introduce the idea gradually, without making children feel responsible for financial pressures that belong to their parents.","start":46.120997732426304,"end":53.637687074829934}],"sha256":"5e75ca9be1b9e9ee30b7f0ed97eb3cbc5f3849074b3f6ae5a7f97dff2b18aa43"},"audio/daniel-synced-160/33455594594a7288.m4a":{"duration":56.64643990929705,"segments":[{"text":"Should schools spend time teaching practical skills?","start":0.0,"end":3.963718820861678},{"text":"Yes, because practical tasks can connect classroom learning with everyday life.","start":3.963718820861678,"end":9.158412698412699},{"text":"Preparing a simple meal, for instance, involves following instructions, measuring and working carefully.","start":9.158412698412699,"end":15.93968253968254},{"text":"I wouldn't replace core academic subjects with these activities, though.","start":15.93968253968254,"end":20.48684807256236},{"text":"Schools have limited time, so the most useful approach may be to include practical applications within existing lessons rather than add too many separate courses.","start":20.48684807256236,"end":31.54984126984127},{"text":"How does learning a skill from a parent differ from learning it from a teacher?","start":31.54984126984127,"end":36.170204081632654},{"text":"A parent may have more opportunities to practise a skill during daily routines, like showing a child how to care for a plant.","start":36.170204081632654,"end":43.69931972789116},{"text":"A teacher can provide a more structured sequence and experience with different learners.","start":43.69931972789116,"end":48.5465306122449},{"text":"Neither is always better.","start":48.5465306122449,"end":50.119455782312926},{"text":"What matters is whether the adult explains clearly, gives useful feedback and allows the child to try independently.","start":50.119455782312926,"end":56.64643990929705}],"sha256":"cf939440f6a93c1d0bcc92e79893fb23efbc2d11af9aabc63229c84e0d2c0ede"},"audio/daniel-synced-160/991a0e5b5a06b9ea.m4a":{"duration":55.034013605442176,"segments":[{"text":"Why do people take photographs of ordinary daily activities?","start":0.0,"end":4.721859410430839},{"text":"Ordinary moments can become meaningful later, even if they don't seem remarkable at the time.","start":4.721859410430839,"end":10.26562358276644},{"text":"A photograph of friends cooking together may bring back details that a formal group portrait misses.","start":10.26562358276644,"end":15.925532879818594},{"text":"People also use pictures to share their day with others.","start":15.925532879818594,"end":19.074467120181406},{"text":"I think this is understandable, provided taking the photograph doesn't distract everyone from enjoying the actual experience.","start":19.074467120181406,"end":27.93514739229025},{"text":"Has phone photography changed the value of professional photography?","start":27.93514739229025,"end":32.59260770975057},{"text":"It has made taking everyday pictures much easier, but I don't think it removes the need for professional work.","start":32.59260770975057,"end":38.728480725623584},{"text":"At a wedding, for example, guests can capture casual moments while a professional takes responsibility for recording the main events.","start":38.728480725623584,"end":46.954195011337866},{"text":"The difference is partly about reliability and judgement.","start":46.954195011337866,"end":50.19360544217687},{"text":"Some phone users are very skilled, so equipment alone doesn't define quality.","start":50.19360544217687,"end":55.034013605442176}],"sha256":"d2ea922752ce91d8f67784d7e114c2049f411dd8453d83e525a9d33f32e9b7cc"},"audio/daniel-synced-160/6a9495071d3fb769.m4a":{"duration":55.49895691609977,"segments":[{"text":"Why can communication between different generations be difficult?","start":0.0,"end":4.698639455782313},{"text":"People may assume their own experiences are the normal starting point.","start":4.698639455782313,"end":8.82281179138322},{"text":"A parent could see a stable job as the safest choice, while their child values trying different roles.","start":8.82281179138322,"end":15.063219954648526},{"text":"If neither explains the reasons behind their preference, the discussion can turn into an argument.","start":15.063219954648526,"end":20.69986394557823},{"text":"Different ages don't automatically create conflict, but unspoken expectations can make understanding harder.","start":20.69986394557823,"end":29.024172335600905},{"text":"Do you think relationships between grandparents and grandchildren are changing?","start":29.024172335600905,"end":34.094467120181406},{"text":"They can change when families live farther apart or follow different daily routines.","start":34.094467120181406,"end":38.994285714285716},{"text":"A grandparent might now join a birthday through a video call instead of visiting in person.","start":38.994285714285716,"end":44.0156462585034},{"text":"That helps maintain contact, but it doesn't replace every part of spending time together.","start":44.0156462585034,"end":49.44929705215419},{"text":"Some families remain very close, so the change depends more on their circumstances than on age alone.","start":49.44929705215419,"end":55.49895691609977}],"sha256":"a3df9f9f77c02738f3ef7d9d4afb12e94f8b60804e9b8754523838b2417f5999"},"audio/daniel-synced-160/707483233569fede.m4a":{"duration":52.1778231292517,"segments":[{"text":"Why is listening an important part of being polite?","start":0.0,"end":3.6189115646258503},{"text":"Listening shows that you consider the other person's contribution worth your attention.","start":3.6189115646258503,"end":8.279727891156462},{"text":"If a colleague explains a problem and you immediately change the subject, they may feel dismissed, even without an insulting word.","start":8.279727891156462,"end":15.866848072562359},{"text":"I think good listening includes asking relevant questions.","start":15.866848072562359,"end":19.368526077097506},{"text":"It doesn't require agreeing with everything, but disagreement is easier to discuss after both people feel understood.","start":19.368526077097506,"end":27.58938775510204},{"text":"Is it ever acceptable to interrupt someone?","start":27.58938775510204,"end":31.00031746031746},{"text":"Yes, when there is a clear reason, such as preventing a misunderstanding before it affects a decision.","start":31.00031746031746,"end":37.26312925170068},{"text":"In a meeting, someone might politely interrupt to correct a date that everyone is about to use.","start":37.26312925170068,"end":42.79528344671202},{"text":"However, the interruption should be brief and relevant.","start":42.79528344671202,"end":46.02167800453515},{"text":"Repeatedly taking over because you prefer your own ideas is different from helping the conversation stay accurate.","start":46.02167800453515,"end":52.1778231292517}],"sha256":"83988591475c938bc0b182f425cf632e3acad6ace85ba27a883260992e23512c"},"audio/daniel-synced-160/6bb8e47c9c316071.m4a":{"duration":56.07904761904762,"segments":[{"text":"Why do customers sometimes care more about service than price?","start":0.0,"end":4.7450793650793655},{"text":"Good service can reduce uncertainty and save people time.","start":4.7450793650793655,"end":8.488253968253968},{"text":"Someone buying a complicated appliance may value a clear explanation and dependable help if something goes wrong.","start":8.488253968253968,"end":15.016553287981859},{"text":"A slightly lower price may feel less attractive without that support.","start":15.016553287981859,"end":18.888526077097506},{"text":"This won't apply to every purchase, though; for a simple product that customers already understand, price can remain the main concern.","start":18.888526077097506,"end":28.90340136054422},{"text":"How does good online customer service differ from good service in a shop?","start":28.90340136054422,"end":33.76757369614513},{"text":"Online service needs especially clear written information because customers can't easily point to the product or read the assistant's expression.","start":33.76757369614513,"end":41.71460317460318},{"text":"In a shop, an employee can demonstrate a solution immediately.","start":41.71460317460318,"end":45.64458049886621},{"text":"For example, showing how a button works may take seconds in person.","start":45.64458049886621,"end":50.13242630385488},{"text":"Both settings still require listening carefully, but the way an explanation is delivered needs to fit the channel.","start":50.13242630385488,"end":56.07904761904762}],"sha256":"46aa8161c152234b1ae50d0510e5566dafba46e396ccdb0bdff21d9d4001ac62"},"audio/daniel-synced-160/b313ae89e3ed0c35.m4a":{"duration":51.86,"segments":[{"text":"Why do some people prefer handmade products?","start":0.0,"end":3.6537414965986397},{"text":"They may appreciate small differences that show someone worked directly on the object.","start":3.6537414965986397,"end":8.507120181405895},{"text":"A handmade bowl can feel personal because its shape or decoration isn't identical to every other one.","start":8.507120181405895,"end":14.225124716553289},{"text":"The maker's story may add meaning too.","start":14.225124716553289,"end":16.526439909297054},{"text":"I wouldn't assume handmade products are always better, though; customers still need to consider whether the item is suitable for its intended use.","start":16.526439909297054,"end":26.397777777777776},{"text":"When are machine-made products a better choice than handmade ones?","start":26.397777777777776,"end":30.887437641723356},{"text":"They can be a better choice when consistency and large quantities matter.","start":30.887437641723356,"end":35.13709750566893},{"text":"A café buying hundreds of matching cups may prefer products with predictable sizes and prices.","start":35.13709750566893,"end":40.88988662131519},{"text":"A handmade cup might be more appealing as a personal gift.","start":40.88988662131519,"end":44.16975056689343},{"text":"I think the comparison depends on the purpose: efficiency is valuable in one situation, while individuality adds value in another.","start":44.16975056689343,"end":51.86}],"sha256":"c9a66e7a44d4de17aca74511d3aa714bf15ef448339796273e628a420fb31079"},"audio/daniel-synced-160/4ed6ef838d35db3c.m4a":{"duration":49.98984126984127,"segments":[{"text":"Why do people enjoy organising gatherings for their friends?","start":0.0,"end":4.385170068027211},{"text":"A gathering creates time together that might otherwise be postponed.","start":4.385170068027211,"end":8.35002267573696},{"text":"Busy friends can keep saying they'll meet soon without choosing a date.","start":8.35002267573696,"end":12.221133786848073},{"text":"Organising a simple dinner gives everyone a clear opportunity to reconnect.","start":12.221133786848073,"end":16.603900226757368},{"text":"Some people also enjoy making others feel welcome.","start":16.603900226757368,"end":19.788526077097504},{"text":"However, I think hosting is more enjoyable when the organiser doesn't feel pressured to make every detail perfect.","start":19.788526077097504,"end":27.921133786848074},{"text":"How might a small gathering differ from a large party?","start":27.921133786848074,"end":31.693968253968254},{"text":"A small gathering makes it easier to have a proper conversation with each person.","start":31.693968253968254,"end":36.15804988662131},{"text":"At a large party, there may be more energy and more opportunities to meet someone new.","start":36.15804988662131,"end":41.225850340136056},{"text":"For a friend who has been going through a difficult week, a quiet dinner might be preferable.","start":41.225850340136056,"end":46.21868480725624},{"text":"The ideal size depends on the purpose and the guests' personalities.","start":46.21868480725624,"end":49.98984126984127}],"sha256":"efe68ad3b1d23d11237c0334e0a1fc86def421d7f2cd51d42c4f9a27d96acb80"},"audio/daniel-synced-160/c7bce18b29f3caa8.m4a":{"duration":53.07918367346939,"segments":[{"text":"Why do people sometimes spend longer on their phones than they intended?","start":0.0,"end":4.652199546485261},{"text":"There's often no clear finishing point.","start":4.652199546485261,"end":6.997414965986395},{"text":"Someone opens an app to check one message, then sees a video or another conversation and continues.","start":6.997414965986395,"end":13.165804988662131},{"text":"Unlike finishing a chapter, they may not notice a natural place to stop.","start":13.165804988662131,"end":17.490566893424035},{"text":"I think the purpose of using the phone matters too; talking to a friend is different from scrolling without much interest.","start":17.490566893424035,"end":25.538548752834465},{"text":"Should adults and children follow the same rules about screen use?","start":25.538548752834465,"end":30.117596371882087},{"text":"The rules shouldn't be identical because their responsibilities and independence differ.","start":30.117596371882087,"end":34.78503401360544},{"text":"An adult may need a screen for work, while a child might need guidance about choosing content and balancing activities.","start":34.78503401360544,"end":41.780090702947845},{"text":"However, shared family expectations can help.","start":41.780090702947845,"end":45.22707482993197},{"text":"For example, putting phones away during dinner can apply to everyone, rather than making children follow a rule that adults ignore.","start":45.22707482993197,"end":53.07918367346939}],"sha256":"f16bc583a5e420415d1274fac067f14c7d19ea7168956a9a4a96b115c7ad42cc"},"audio/daniel-synced-160/4973b689cf5c63b7.m4a":{"duration":53.66340136054422,"segments":[{"text":"Why is it useful to preserve historic buildings?","start":0.0,"end":3.7698412698412698},{"text":"They can help people understand how a place developed, beyond what a written description can show.","start":3.7698412698412698,"end":9.577369614512472},{"text":"Walking through an old market may reveal its layout and the way people once traded.","start":9.577369614512472,"end":13.9243537414966},{"text":"Historic buildings can also contribute to a neighbourhood's identity.","start":13.9243537414966,"end":17.92154195011338},{"text":"Preservation still requires judgement, though; the building's significance, condition and possible future use all deserve consideration.","start":17.92154195011338,"end":27.78625850340136},{"text":"Is visiting a historic place better than learning about it online?","start":27.78625850340136,"end":32.33496598639456},{"text":"Visiting can make the scale and atmosphere more memorable, while online material can explain details that aren't obvious on site.","start":32.33496598639456,"end":39.81709750566893},{"text":"Someone looking at an old fort may enjoy the setting but need a video or guide to understand its purpose.","start":39.81709750566893,"end":45.683628117913834},{"text":"I'd see the two methods as complementary.","start":45.683628117913834,"end":48.31328798185941},{"text":"Travel isn't always possible, and a thoughtful online resource can still teach a great deal.","start":48.31328798185941,"end":53.66340136054422}],"sha256":"beed4464c037fedf4e867bc465430d7bcfcdb5c1688be2f817334cf528d2590e"},"audio/daniel-synced-160/bec274770d556f02.m4a":{"duration":52.9328798185941,"segments":[{"text":"Why do some people prefer a film adaptation to the original book?","start":0.0,"end":4.698639455782313},{"text":"A film can make a story easier to enter, especially for someone who finds the book's language demanding.","start":4.698639455782313,"end":10.950657596371881},{"text":"Actors, music and visual details create an immediate impression.","start":10.950657596371881,"end":15.089659863945577},{"text":"Others may simply have less time for reading.","start":15.089659863945577,"end":17.71936507936508},{"text":"I don't think preferring the film means someone appreciates stories less, although an adaptation may leave out parts that readers consider important.","start":17.71936507936508,"end":27.719818594104307},{"text":"How does reading a story differ from watching it on screen?","start":27.719818594104307,"end":31.771292517006803},{"text":"Reading leaves more of the setting and characters' appearance to the reader's imagination.","start":31.771292517006803,"end":36.42063492063492},{"text":"A screen version makes those choices visible and controls the pace more directly.","start":36.42063492063492,"end":41.10530612244898},{"text":"For example, a reader can pause over a character's thoughts, while a film may communicate the same feeling through an expression.","start":41.10530612244898,"end":48.55369614512472},{"text":"Both can be powerful, but they invite the audience to participate differently.","start":48.55369614512472,"end":52.9328798185941}],"sha256":"f17b0fa0805eb5ec1e2197ab83226d3aee259d6374354fc923cf4566a3bd3acf"},"audio/daniel-synced-160/95171dd9a195c404.m4a":{"duration":55.131247165532876,"segments":[{"text":"Why might people continue driving even when public transport is available?","start":0.0,"end":5.07015873015873},{"text":"Availability doesn't always mean convenience.","start":5.07015873015873,"end":8.03655328798186},{"text":"A bus may exist, but it might require a long walk or several transfers for someone's particular journey.","start":8.03655328798186,"end":14.346621315192744},{"text":"A parent collecting children and carrying shopping could find driving easier.","start":14.346621315192744,"end":18.543673469387755},{"text":"I think people compare the whole trip, rather than just the fare.","start":18.543673469387755,"end":22.38204081632653},{"text":"Better connections may encourage change, but individual needs still have to be considered.","start":22.38204081632653,"end":28.988253968253968},{"text":"Should a city prioritise faster journeys or more comfortable journeys?","start":28.988253968253968,"end":33.8459410430839},{"text":"I'd try to balance them, but predictable journey times would be my first priority for daily commuting.","start":33.8459410430839,"end":39.97020408163265},{"text":"A comfortable bus is less useful if passengers can't estimate when they'll arrive.","start":39.97020408163265,"end":44.770975056689345},{"text":"For longer trips, seating and space become more important.","start":44.770975056689345,"end":48.608662131519274},{"text":"The best investment therefore depends on the journey and the users, rather than treating speed as the only measure of quality.","start":48.608662131519274,"end":55.131247165532876}],"sha256":"b0ef5b1728059c4e3afba7c62a31bf6d8c5855ffc481cb279dfa939e0bd9b41e"},"audio/daniel-synced-160/38099a1d51662299.m4a":{"duration":53.31591836734694,"segments":[{"text":"Why do some people struggle to make time for physical activities?","start":0.0,"end":4.756689342403628},{"text":"The difficulty may be fitting an activity into an unpredictable routine.","start":4.756689342403628,"end":8.936507936507937},{"text":"Someone working changing shifts might find it hard to join a class at the same time each week.","start":8.936507936507937,"end":14.396689342403628},{"text":"Others may choose an activity they don't really enjoy, so it becomes another obligation.","start":14.396689342403628,"end":19.685079365079364},{"text":"I think participation is more sustainable when the activity matches the person's interests and available time.","start":19.685079365079364,"end":27.40798185941043},{"text":"How is taking part in sport different from watching it?","start":27.40798185941043,"end":31.227256235827664},{"text":"Taking part requires you to make decisions and experience the effort yourself, while watching lets you appreciate other people's skill without that responsibility.","start":31.227256235827664,"end":40.39977324263039},{"text":"Someone playing tennis might be focused on returning the next shot; a spectator can notice the wider pattern of the match.","start":40.39977324263039,"end":47.55501133786848},{"text":"Both can be enjoyable, but the experience of participating depends on finding a suitable level.","start":47.55501133786848,"end":53.31591836734694}],"sha256":"098647f1d9cf8540a288a41884cbcbfe598a41482753ee56bfbb04043b688cb6"},"audio/daniel-synced-160/783bacaa66937657.m4a":{"duration":51.75079365079365,"segments":[{"text":"Are rules necessary to encourage environmentally responsible behaviour?","start":0.0,"end":5.0059410430839},{"text":"Rules can be useful because they set a shared expectation, but they work better alongside practical support.","start":5.0059410430839,"end":11.55936507936508},{"text":"Asking residents to separate rubbish makes more sense when the containers are clearly labelled and easy to reach.","start":11.55936507936508,"end":17.655056689342402},{"text":"I wouldn't expect a rule alone to solve every problem.","start":17.655056689342402,"end":20.936780045351473},{"text":"People also need to understand what to do and why it matters.","start":20.936780045351473,"end":25.915283446712017},{"text":"Should environmental policies focus more on individuals or businesses?","start":25.915283446712017,"end":30.865850340136053},{"text":"I'd focus on both, but give each group responsibilities it can realistically control.","start":30.865850340136053,"end":36.47927437641723},{"text":"A shopper can choose how much to buy, while a company decides how a product is packaged.","start":36.47927437641723,"end":41.81410430839002},{"text":"Asking the shopper to solve the packaging problem alone seems unfair.","start":41.81410430839002,"end":45.85301587301587},{"text":"The balance will vary by issue, and policies should connect the different parts rather than treat them separately.","start":45.85301587301587,"end":51.75079365079365}],"sha256":"a67494a08dfb858ce1c46fdc5c1a87541425e08989a2a398fc6eefc9c3089d03"},"audio/daniel-synced-160/ed010b9f1269734b.m4a":{"duration":56.824716553287985,"segments":[{"text":"Why do some language learners understand more than they can say?","start":0.0,"end":4.431609977324263},{"text":"Recognising language and producing it are different tasks.","start":4.431609977324263,"end":8.001179138321996},{"text":"A learner may follow a familiar conversation but need extra time to choose words when replying.","start":8.001179138321996,"end":13.3940589569161},{"text":"For example, watching a travel video doesn't require answering an unexpected question.","start":13.3940589569161,"end":18.97324263038549},{"text":"I think speaking practice helps connect knowledge with use, although confidence and familiarity with the topic can also affect what someone manages to say.","start":18.97324263038549,"end":29.250340136054422},{"text":"How does learning a language in a classroom differ from using it abroad?","start":29.250340136054422,"end":33.84748299319728},{"text":"A classroom can provide explanations and a planned sequence, while using the language abroad brings less predictable situations.","start":33.84748299319728,"end":41.6204081632653},{"text":"Ordering food may involve a question the learner hasn't practised.","start":41.6204081632653,"end":45.31818594104308},{"text":"That can reveal useful gaps, but living abroad doesn't automatically produce progress.","start":45.31818594104308,"end":51.042086167800456},{"text":"Someone who rarely speaks outside their own language group may still need deliberate practice and feedback.","start":51.042086167800456,"end":56.824716553287985}],"sha256":"039300019925f77d4da66bde7805a1bb64db043b702a0c79b0843d78ea8f4aa9"},"audio/daniel-synced-160/3bd965555b65af70.m4a":{"duration":52.14086167800453,"segments":[{"text":"Does technology always help people work more efficiently?","start":0.0,"end":4.2346031746031745},{"text":"No, because a tool can create extra steps as well as remove them.","start":4.2346031746031745,"end":8.539727891156463},{"text":"A team might adopt a planning app but spend more time updating it than discussing the actual work.","start":8.539727891156463,"end":14.002267573696145},{"text":"I think technology helps when it addresses a clear problem.","start":14.002267573696145,"end":17.45750566893424},{"text":"The useful question is whether the task becomes easier or more reliable, rather than whether the tool looks advanced.","start":17.45750566893424,"end":25.4637641723356},{"text":"How might technology change the skills employees need?","start":25.4637641723356,"end":29.42235827664399},{"text":"If a tool handles routine parts of a task, employees may spend more time checking results and deciding what to do next.","start":29.42235827664399,"end":36.963038548752834},{"text":"For example, software can organise customer messages, but someone still needs to judge which problem is urgent.","start":36.963038548752834,"end":44.039909297052155},{"text":"New skills won't replace every existing one.","start":44.039909297052155,"end":46.97120181405896},{"text":"Understanding the work itself remains important when a tool produces an unexpected answer.","start":46.97120181405896,"end":52.14086167800453}],"sha256":"114e4ec1cf5010dca48eba31a235b75b74d243db46216c3f671eaeb4219c9bc0"},"audio/daniel-synced-160/0bae80ad5002d1e0.m4a":{"duration":52.9718820861678,"segments":[{"text":"Why do people value different features when choosing a home?","start":0.0,"end":4.2922902494331066},{"text":"Their routines create different needs.","start":4.2922902494331066,"end":6.730476190476191},{"text":"Someone working from home may want a quiet room, while someone commuting every day might prioritise being near a station.","start":6.730476190476191,"end":13.850884353741497},{"text":"A family could place more weight on space for children.","start":13.850884353741497,"end":16.97981859410431},{"text":"I don't think one feature is best for everyone, and the same person's priorities can change when their work or household situation changes.","start":16.97981859410431,"end":26.92222222222222},{"text":"Should new buildings copy traditional styles or use modern designs?","start":26.92222222222222,"end":31.75668934240363},{"text":"I'd prefer designs that respond to their surroundings without copying the past exactly.","start":31.75668934240363,"end":36.766394557823126},{"text":"A new building in a historic street could use a similar scale while including a modern layout inside.","start":36.766394557823126,"end":42.27537414965986},{"text":"In another location, a more distinct design might fit well.","start":42.27537414965986,"end":46.03120181405896},{"text":"The aim should be a useful building that belongs in its setting, rather than choosing appearance before considering people's needs.","start":46.03120181405896,"end":52.9718820861678}],"sha256":"4da1b7979fae667282a97d99a3b4ee2afdf987ae2be2bce1f9fd07f067638dc0"}};
